// Inline `code` spans in Builder copy (setup steps, notes) and copying them.

export type TextPart = { kind: "text"; text: string } | { kind: "code"; text: string };

const CODE_SPAN_RE = /`([^`\n]+)`/g;

/** Split text on single-backtick spans: "run `ls -l` now" →
 *  text "run " · code "ls -l" · text " now". An unpaired backtick, or an
 *  empty pair, stays as literal text. */
export function splitCodeSpans(text: string): TextPart[] {
  const parts: TextPart[] = [];
  let last = 0;
  for (const m of text.matchAll(CODE_SPAN_RE)) {
    const start = m.index ?? 0;
    if (start > last) parts.push({ kind: "text", text: text.slice(last, start) });
    parts.push({ kind: "code", text: m[1]! });
    last = start + m[0].length;
  }
  if (last < text.length) parts.push({ kind: "text", text: text.slice(last) });
  return parts;
}

/** Copy via a temporary <textarea> + execCommand("copy") — the only route
 *  on a plain-http LAN origin (http://sporeprint.local:3001), where
 *  navigator.clipboard does not exist. */
function copyWithTextarea(text: string): boolean {
  if (typeof document === "undefined" || typeof document.execCommand !== "function") return false;
  const previous = document.activeElement instanceof HTMLElement ? document.activeElement : null;
  const ta = document.createElement("textarea");
  ta.value = text;
  ta.setAttribute("readonly", "");
  ta.setAttribute("aria-hidden", "true");
  ta.style.position = "fixed";
  ta.style.top = "0";
  ta.style.left = "0";
  ta.style.opacity = "0";
  ta.style.pointerEvents = "none";
  document.body.appendChild(ta);
  try {
    ta.select();
    return document.execCommand("copy");
  } catch {
    return false;
  } finally {
    ta.remove();
    previous?.focus();
  }
}

/** Copy text to the clipboard: the async Clipboard API where the page may
 *  use it (secure context), else the textarea fallback. Resolves false —
 *  never rejects — when neither works, so the caller can say so. */
export async function copyText(text: string): Promise<boolean> {
  const clipboard = typeof navigator !== "undefined" ? navigator.clipboard : undefined;
  if (clipboard && typeof clipboard.writeText === "function") {
    try {
      await clipboard.writeText(text);
      return true;
    } catch {
      // permission denied / not focused — try the fallback
    }
  }
  try {
    return copyWithTextarea(text);
  } catch {
    return false;
  }
}
