const SETUP_COMPLETE_KEY = "sporeprint:setup_complete";

/**
 * Mark first-run setup as complete on the Pi server, then mirror the
 * flag in localStorage. Best-effort — if the server call fails we
 * still set localStorage so the operator isn't stuck in a redirect
 * loop on an offline Pi.
 */
async function markSetupComplete(): Promise<void> {
  try {
    await fetch("/api/settings/setup-status", {
      method: "POST",
      credentials: "same-origin",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ setup_complete: true }),
    });
  } catch {
    // ignore — localStorage is the fallback
  }
  if (typeof window !== "undefined") {
    window.localStorage.setItem(SETUP_COMPLETE_KEY, "1");
  }
}

// ── Real Pi API shapes (read from server/app/*) ──────────────────────

/** `GET /api/health` (main.py health()). */
interface PiHealthInfo {
  status: string;
  version: string;
}
/** Subset of `GET /api/health/detail/system` (health/service.py). */
interface PiSystemInfo {
  uptime_hours: number;
}
/** Subset of `GET /api/cloud/status` (cloud/service.py get_cloud_status). */
interface CloudStatus {
  configured: boolean;
  connected: boolean;
  cloud_url: string | null;
  device_id: string | null;
  queue_depth: number;
  last_forward: number | null;
}
/** One entry from the parallel `GET /api/hardware/discover` LAN scan. The Pi
 *  sources these from the heartbeat registry: `mac` is always null (no MAC in
 *  the heartbeat) and `ip` is nullable (the `ip_address` column can be empty). */
interface DiscoverNode {
  node_id: string;
  mac: string | null;
  ip: string | null;
  personality: string;
  claimed: boolean;
}

/** Everything the welcome/network/done summaries read, fetched once. Each
 *  endpoint is settled independently so a Pi missing one (older build) still
 *  shows the fields it can serve — never a fabricated value. */
interface PiSnapshot {
  health: PiHealthInfo | null;
  system: PiSystemInfo | null;
  cloud: CloudStatus | null;
  nodes: HardwareNode[] | null;
}

function settled<T>(r: PromiseSettledResult<T>): T | null {
  return r.status === "fulfilled" ? r.value : null;
}

async function loadSnapshot(): Promise<PiSnapshot> {
  const [h, s, c, n] = await Promise.allSettled([
    apiGet<PiHealthInfo>("/api/health"),
    apiGet<PiSystemInfo>("/api/health/detail/system"),
    apiGet<CloudStatus>("/api/cloud/status"),
    apiGet<HardwareNode[]>("/api/hardware/nodes"),
  ]);
  return { health: settled(h), system: settled(s), cloud: settled(c), nodes: settled(n) };
}

/** The address the browser reached the Pi on — first-party truth, never a
 *  guessed LAN IP. Empty in SSR/test, rendered as an em dash. */
function piHost(): string {
  if (typeof window === "undefined") return "—";
  return window.location.host || "—";
}

function fmtUptime(hours: number): string {
  if (!Number.isFinite(hours) || hours < 0) return "—";
  return hours >= 48 ? `${(hours / 24).toFixed(1)} d` : `${hours.toFixed(1)} h`;
}

/** Cloud-link summary line + pill tone, derived from real `/api/cloud/status`. */
function cloudLabel(c: CloudStatus | null): { text: string; tone: StatusPillTone } {
  if (!c || !c.configured) return { text: "local only — not paired", tone: "idle" };
  if (c.connected) {
    return {
      text: c.last_forward != null ? `synced · ${relativeSeen(c.last_forward)}` : "connected",
      tone: "signal",
    };
  }
  return { text: "configured · offline", tone: "warn" };
}

type Step = 1 | 2 | 3 | 4 | 5;

const STEPS: Record<Step, { roman: string; title: string; sub: string }> = {
  1: { roman: "§ I", title: "Welcome", sub: "Let's get your chambers online. This wizard takes about 5 minutes." },
  2: {
    roman: "§ II",
    title: "Network",
    sub: "Confirm the Pi is reachable on your network. Wired vs Wi-Fi switchover is handled by Raspberry Pi OS.",
  },
  3: { roman: "§ III", title: "Cloud link", sub: "Pair this Pi to a paid sporeprint.ai account, or run locally only." },
  4: { roman: "§ IV", title: "First chamber", sub: "Scan the LAN for an unclaimed ESP32 chamber and add it to the rack." },
  5: { roman: "§ V", title: "Done", sub: "Your fleet is live on the LAN. Everything else happens from the dashboard." },
};

export function SetupPage() {
  const [step, setStep] = useState<Step>(1);
  const meta = STEPS[step];

  return (
    <div className="flex min-h-screen flex-col bg-bg-0">
      <PublicTopBar
        brand={{ word: "sporeprint", suffix: " · local" }}
        rightNav={
          <span className="font-mono text-[13px] font-medium uppercase tracking-[0.16em] text-text-2">
            First-run setup
          </span>
        }
      />

      {/* Step indicator strip */}
      {/* Five equal columns that may shrink below their content
          (minmax(0,1fr)); under 640px only the § numerals show — the titles
          stay for screen readers — so the strip fits a 390px phone. */}
      <nav
        aria-label="setup progress"
        className="grid grid-cols-[repeat(5,minmax(0,1fr))] border-b border-border-soft bg-bg-1 px-2 sm:px-10"
      >
        {([1, 2, 3, 4, 5] as Step[]).map((s) => {
          const past = s < step;
          const current = s === step;
          return (
            <button
              key={s}
              type="button"
              onClick={() => setStep(s)}
              aria-current={current ? "step" : undefined}
              aria-label={`${STEPS[s].roman} ${STEPS[s].title}`}
              className={cn(
                "flex min-w-0 cursor-pointer flex-col items-center gap-1 border-b-[3px] bg-transparent px-1 py-4 text-center sm:items-start sm:px-4 sm:py-5 sm:text-left",
                current
                  ? "border-b-accent text-accent"
                  : past
                    ? "border-b-accent-line text-text-1"
                    : "border-b-transparent text-text-3",
              )}
            >
              <span className="whitespace-nowrap font-mono text-[13px] font-medium uppercase tracking-[0.16em] text-inherit">
                {STEPS[s].roman}
              </span>
              <span className="font-body text-[18px] font-medium leading-[1.25] text-inherit max-sm:sr-only">
                {STEPS[s].title}
              </span>
            </button>
          );
        })}
      </nav>

      {/* Step body — generous, full-width */}
      <main className="mx-auto flex w-full min-w-0 max-w-[960px] flex-1 flex-col gap-6 px-4 pt-8 pb-12 sm:px-10 sm:pt-12 sm:pb-16">
        <section className="flex flex-col gap-3">
          <span className="font-mono text-[13px] font-medium uppercase tracking-[0.16em] text-text-2">{meta.roman}</span>
          <h1 className="font-display text-[clamp(36px,4.4vw,56px)] font-semibold italic leading-[1.05] tracking-[-0.015em] text-text-0">
            {meta.title}
          </h1>
          <p className="max-w-[720px] font-body text-[18px] leading-[1.5] text-text-1">{meta.sub}</p>
        </section>

        {step === 1 && <StepOne />}
        {step === 2 && <StepTwo />}
        {step === 3 && <StepThree />}
        {step === 4 && <StepFour />}
        {step === 5 && <StepFive />}

        {/* Bottom nav */}
        <nav className="flex items-center justify-between gap-3 border-t border-border-soft pt-6">
          <Button
            variant="ghost"
            disabled={step === 1}
            onClick={() => setStep((s) => (s > 1 ? ((s - 1) as Step) : s))}
          >
            ← back
          </Button>
          <Button
            onClick={async () => {
              if (step === 5) {
                await markSetupComplete();
                window.location.href = "/";
              } else {
                setStep((s) => ((s + 1) as Step));
              }
            }}
          >
            {step === 5 ? "open fleet →" : "continue →"}
          </Button>
        </nav>
      </main>
    </div>
  );
}

// ── § I — Welcome ────────────────────────────────────────────────────

function StepOne() {
  const { data, loading } = usePiLoad(loadSnapshot, []);
  const shown = (v: string | undefined) => v ?? (loading && !data ? "…" : "—");
  return (
    <section className="grid min-w-0 auto-rows-fr grid-cols-[repeat(auto-fit,minmax(min(320px,100%),1fr))] gap-3">
      <Card label="this Pi">
        <Row k="reachable at" v={piHost()} />
        <Row k="server" v={shown(data?.health ? `v${data.health.version}` : undefined)} />
        <Row k="uptime" v={shown(data?.system ? fmtUptime(data.system.uptime_hours) : undefined)} />
      </Card>
      <Card label="what happens next">
        <Row k="§ II" v="confirm the network" />
        <Row k="§ III" v="(optional) pair to cloud" />
        <Row k="§ IV" v="claim your first chamber" />
        <Row k="§ V" v="done — fleet is live" />
      </Card>
      <Card label="need help?">
        <p className="font-body text-[16px] leading-[1.55] text-text-1">
          Setup typically takes about 5 minutes for a single chamber. The Pi works fully
          offline — cloud is optional.
        </p>
        {/* sporeprint.ai/docs/* answers 403 (Cloudflare error 1000) — the
            public README's Quick Start is the setup guide that works. */}
        <a
          href="https://github.com/59psi/SporePrint#quick-start"
          target="_blank"
          rel="noopener noreferrer"
          className="self-start font-mono text-[14px] font-medium uppercase tracking-[0.16em] text-accent no-underline hover:text-text-0"
        >
          read the full guide →
        </a>
      </Card>
    </section>
  );
}

// ── § II — Network ───────────────────────────────────────────────────

function StepTwo() {
  const [tick, setTick] = useState(0);
  const { data, loading } = usePiLoad(loadSnapshot, [tick]);
  const proto =
    typeof window !== "undefined" ? window.location.protocol.replace(/:$/, "") : "—";
  const reachable = data?.health?.status === "ok";
  return (
    <section className="grid min-w-0 auto-rows-fr grid-cols-[repeat(auto-fit,minmax(min(360px,100%),1fr))] gap-3">
      <Card label="reachability">
        <Row k="reached at" v={piHost()} />
        <Row k="scheme" v={proto} />
        <Row
          k="pi server"
          v={
            <StatusPill tone={reachable ? "signal" : loading && !data ? "idle" : "warn"}>
              {reachable ? "responding" : loading && !data ? "checking…" : "no response"}
            </StatusPill>
          }
        />
        <Row k="uptime" v={data?.system ? fmtUptime(data.system.uptime_hours) : "—"} />
        <Button
          variant="ghost"
          disabled={loading}
          onClick={() => setTick((t) => t + 1)}
        >
          {loading ? "checking…" : "recheck reachability"}
        </Button>
      </Card>
      <Card label="uplink details">
        <p className="font-body text-[16px] leading-[1.55] text-text-1">
          The Pi server doesn&rsquo;t expose the OS network interface — SSID, signal, and DNS are
          managed in Raspberry Pi OS, not through this app. This step just confirms the box is
          reachable at the address above.
        </p>
        <p className="font-body text-[16px] leading-[1.55] text-text-1">
          You&rsquo;re reading this page over that uplink, so it&rsquo;s already working. Plug in
          ethernet any time — the OS switches over and Wi-Fi goes idle.
        </p>
      </Card>
    </section>
  );
}

// ── § III — Cloud link ───────────────────────────────────────────────

interface PairingCode {
  value: string;
  expiresAt: number;
}

function StepThree() {
  const [status, setStatus] = useState<CloudStatus | null>(null);
  const [statusLoaded, setStatusLoaded] = useState(false);
  const [code, setCode] = useState<PairingCode | null>(null);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  const [nowMs, setNowMs] = useState(() => Date.now());

  const paired = Boolean(status?.configured && status?.connected);
  const codeExpired = code != null && nowMs >= code.expiresAt;
  const awaitingLink = code != null && !codeExpired && !paired;
  const secondsLeft = code ? Math.max(0, Math.round((code.expiresAt - nowMs) / 1000)) : 0;

  const refreshStatus = useCallback(async () => {
    try {
      const s = await apiGet<CloudStatus>("/api/cloud/status");
      setStatus(s);
    } catch {
      setStatus(null);
    } finally {
      setStatusLoaded(true);
    }
  }, []);

  useEffect(() => {
    void refreshStatus();
  }, [refreshStatus]);

  // While a code is live and we're not yet linked: tick the countdown (1s) and
  // poll cloud status (3s) so the card flips to "paired" the moment the app
  // finishes /pair + /configure against this Pi. Cleared on unmount / settle.
  useEffect(() => {
    if (!awaitingLink) return;
    const countdown = setInterval(() => setNowMs(Date.now()), 1000);
    const poll = setInterval(() => void refreshStatus(), 3000);
    return () => {
      clearInterval(countdown);
      clearInterval(poll);
    };
  }, [awaitingLink, refreshStatus]);

  async function generate() {
    if (busy) return;
    setBusy(true);
    setErr(null);
    try {
      const res = await apiSend<{ code: string; expires_in: number }>(
        "/api/cloud/pairing-code",
        "POST",
      );
      setCode({ value: res.code, expiresAt: Date.now() + res.expires_in * 1000 });
      setNowMs(Date.now());
    } catch (e) {
      setErr(e instanceof Error ? e.message : "could not generate a pairing code");
    } finally {
      setBusy(false);
    }
  }

  return (
    <section className="flex flex-col gap-[18px]">
      <Card label="cloud link">
        {!statusLoaded ? (
          <p className="font-mono text-[13px] tracking-[0.05em] text-text-2">checking cloud link…</p>
        ) : paired ? (
          <>
            <StatusPill tone="signal" className="self-start">
              paired
            </StatusPill>
            <Row k="account device" v={status?.device_id ?? "—"} />
            <Row k="cloud" v={status?.cloud_url ?? "https://sporeprint.ai"} />
            <p className="font-body text-[16px] leading-[1.55] text-text-1">
              This Pi is linked to your cloud account. Remote control, push, and AI are live for
              premium subscribers.
            </p>
          </>
        ) : (
          <>
            <p className="font-body text-[16px] leading-[1.55] text-text-1">
              Generate a pairing code on this Pi, then in the SporePrint app — mobile on this
              network, or <code>sporeprint.ai/account</code> — choose <em>Add Pi</em> and enter it.
              Premium accounts get cloud relay, push, AI, and remote control. Free users can run the
              Pi forever without cloud.
            </p>

            {awaitingLink && code && (
              <div className="flex flex-col gap-2 rounded-sm border border-accent-line bg-accent-soft p-4">
                <span className="font-mono text-[12px] font-medium uppercase tracking-[0.14em] text-text-2">
                  pairing code
                </span>
                <span className="font-mono text-[34px] leading-none tracking-[0.28em] text-accent">
                  {code.value}
                </span>
                <span className="font-mono text-[12px] text-text-2">
                  expires in {secondsLeft}s · waiting for the cloud to confirm…
                </span>
              </div>
            )}

            {code && codeExpired && (
              <StatusPill tone="warn" className="self-start">
                code expired — generate a new one
              </StatusPill>
            )}

            <div className="mt-1 flex items-center gap-3">
              <Button onClick={() => void generate()} disabled={busy}>
                {busy
                  ? "generating…"
                  : awaitingLink
                    ? "regenerate code"
                    : code && codeExpired
                      ? "generate new code →"
                      : "generate pairing code →"}
              </Button>
              {awaitingLink && (
                <span className="font-mono text-[12px] text-text-2">polling every 3s</span>
              )}
            </div>

            {err && (
              <StatusPill tone="err" className="self-start">
                {err}
              </StatusPill>
            )}
          </>
        )}
      </Card>

      <Card label="what cloud unlocks">
        <ul className="flex flex-col gap-2 pl-[22px] font-body text-[16px] leading-[1.55] text-text-1">
          <li>Remote control from the mobile + web apps</li>
          <li>APNS / FCM push notifications when alerts fire</li>
          <li>Cloud Claude vision + grow advisor (or BYOK on-Pi)</li>
          <li>Long-range telemetry + analytics + exports</li>
          <li>OTA firmware push</li>
        </ul>
      </Card>
    </section>
  );
}

// ── § IV — First chamber ─────────────────────────────────────────────

function StepFour() {
  const [discovered, setDiscovered] = useState<DiscoverNode[] | null>(null);
  const [unavailable, setUnavailable] = useState(false);
  const [fallbackNodes, setFallbackNodes] = useState<HardwareNode[] | null>(null);
  const [loading, setLoading] = useState(true);
  const [err, setErr] = useState<string | null>(null);
  const [claiming, setClaiming] = useState<string | null>(null);

  const scan = useCallback(async () => {
    setLoading(true);
    setErr(null);
    try {
      const res = await apiGet<{ nodes: DiscoverNode[] }>("/api/hardware/discover");
      setDiscovered(res.nodes ?? []);
      setUnavailable(false);
    } catch {
      // Discovery ships in parallel with this wiring; an older Pi server 404s
      // here. Degrade honestly: fall back to the hardware that HAS reported
      // (GET /api/hardware/nodes, which exists today) and disable the
      // scan/claim actions — never invent unclaimed chambers.
      setUnavailable(true);
      setDiscovered(null);
      try {
        setFallbackNodes(await apiGet<HardwareNode[]>("/api/hardware/nodes"));
      } catch {
        setFallbackNodes([]);
      }
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void scan();
  }, [scan]);

  async function claim(nodeId: string) {
    if (claiming) return;
    setClaiming(nodeId);
    setErr(null);
    try {
      await apiSend<unknown>("/api/hardware/claim", "POST", { node_id: nodeId });
      await scan(); // the claimed node comes back with claimed:true
    } catch (e) {
      setErr(e instanceof Error ? e.message : "claim failed");
    } finally {
      setClaiming(null);
    }
  }

  const DISCOVERY_UNAVAILABLE =
    "Hardware discovery (GET /api/hardware/discover) isn't available on this Pi's server build yet — update the Pi server to claim new chambers from here.";

  return (
    <section className="flex flex-col gap-[18px]">
      {unavailable ? (
        <>
          <Card label="discovery unavailable">
            <p className="font-body text-[16px] leading-[1.55] text-text-1">
              This Pi&rsquo;s server build doesn&rsquo;t expose the LAN chamber-discovery endpoint
              yet, so new chambers can&rsquo;t be claimed from this wizard. Below is the hardware
              that has already reported to this Pi.
            </p>
            <Button
              variant="ghost"
              disabled
              title={DISCOVERY_UNAVAILABLE}
              aria-disabled="true"
            >
              rescan
            </Button>
          </Card>
          <Card label="already-registered hardware">
            {loading ? (
              <p className="font-mono text-[13px] tracking-[0.05em] text-text-2">Loading…</p>
            ) : (fallbackNodes?.length ?? 0) === 0 ? (
              <p className="font-mono text-[13px] tracking-[0.05em] text-text-2">
                No hardware nodes have reported to this Pi yet.
              </p>
            ) : (
              <DataTable<HardwareNode & { id?: string }>
                rowKey={(n) => n.node_id}
                columns={[
                  {
                    key: "node",
                    header: "Node",
                    render: (n) => (
                      <span className="font-mono text-text-0">
                        {n.node_type} · {n.node_id}
                      </span>
                    ),
                  },
                  {
                    key: "fw",
                    header: "Firmware",
                    render: (n) => <span className="font-mono text-text-1">{n.firmware_version ?? "—"}</span>,
                  },
                  {
                    key: "status",
                    header: "Status",
                    render: (n) => <StatusPill tone={toneForStatus(n.status)}>{n.status ?? "unknown"}</StatusPill>,
                  },
                  {
                    key: "seen",
                    header: "Last seen",
                    align: "right",
                    render: (n) => <span className="font-mono text-text-1">{relativeSeen(n.last_seen)}</span>,
                  },
                ]}
                rows={fallbackNodes ?? []}
              />
            )}
          </Card>
        </>
      ) : (
        <Card label="discovered ESP32 chambers">
          <p className="font-body text-[16px] leading-[1.55] text-text-1">
            The Pi is scanning your LAN. Chambers in pairing mode show up here within 30 seconds of
            being powered on. Claim one to add it to the rack.
          </p>
          {loading && !discovered ? (
            <p className="font-mono text-[13px] tracking-[0.05em] text-text-2">Scanning…</p>
          ) : (discovered?.length ?? 0) === 0 ? (
            <p className="font-mono text-[13px] tracking-[0.05em] text-text-2">
              No unclaimed chambers found — power one on in pairing mode and rescan.
            </p>
          ) : (
            <DataTable<DiscoverNode & { id?: string }>
              rowKey={(d) => d.node_id}
              columns={[
                {
                  key: "serial",
                  header: "Serial",
                  render: (d) => <span className="font-mono text-text-0">esp32:{d.node_id}</span>,
                },
                { key: "mac", header: "MAC", render: (d) => <span className="font-mono text-text-1">{d.mac ?? "—"}</span> },
                { key: "ip", header: "IP", render: (d) => <span className="font-mono text-text-1">{d.ip ?? "—"}</span> },
                {
                  key: "personality",
                  header: "Personality",
                  render: (d) => <span className="font-mono text-text-1">{d.personality}</span>,
                },
                {
                  key: "claim",
                  header: "Claim",
                  align: "right",
                  render: (d) =>
                    d.claimed ? (
                      <StatusPill tone="signal">claimed</StatusPill>
                    ) : (
                      <Button
                        variant="link"
                        size="sm"
                        disabled={claiming != null}
                        onClick={() => void claim(d.node_id)}
                      >
                        {claiming === d.node_id ? "claiming…" : "claim →"}
                      </Button>
                    ),
                },
              ]}
              rows={discovered ?? []}
            />
          )}
          <div className="flex items-center gap-3">
            <Button variant="ghost" disabled={loading} onClick={() => void scan()}>
              {loading ? "scanning…" : "rescan"}
            </Button>
            {err && (
              <StatusPill tone="err" className="self-center">
                {err}
              </StatusPill>
            )}
          </div>
        </Card>
      )}

      <Card label="not seeing your chamber?">
        <ul className="flex flex-col gap-2 pl-[22px] font-body text-[16px] leading-[1.55] text-text-1">
          <li>Make sure the chamber is powered on and on the same Wi-Fi as the Pi</li>
          <li>Hold the BOOT button for 5 seconds to enter pairing mode</li>
          <li>Check <code>/firmware</code> after claiming — your chamber may be running old firmware</li>
        </ul>
      </Card>
    </section>
  );
}

// ── § V — Done ───────────────────────────────────────────────────────

function StepFive() {
  const { data, loading } = usePiLoad(loadSnapshot, []);
  const nodes = data?.nodes ?? [];
  const online = nodes.filter((n) => n.status === "online").length;
  const cloud = cloudLabel(data?.cloud ?? null);
  return (
    <section className="grid min-w-0 auto-rows-fr grid-cols-[repeat(auto-fit,minmax(min(360px,100%),1fr))] gap-3">
      <Card label="all set">
        <Row
          k="hardware"
          v={
            loading && !data
              ? "…"
              : `${nodes.length} node${nodes.length === 1 ? "" : "s"} · ${online} online`
          }
        />
        <Row k="cloud" v={<StatusPill tone={cloud.tone}>{cloud.text}</StatusPill>} />
        <Row k="fleet url" v={piHost()} />
        <Row k="server" v={data?.health ? `v${data.health.version}` : loading && !data ? "…" : "—"} />
      </Card>
      <Card label="what's next">
        <ul className="flex flex-col gap-2 pl-[22px] font-body text-[16px] leading-[1.55] text-text-1">
          <li>Open the fleet on any LAN device at the address above</li>
          <li>Add a grow session under <em>Sessions</em></li>
          <li>Browse the species library and pick a beginner-friendly mushroom</li>
          <li>If hardware isn't fully built, head to <em>Builder</em> for the BOM + wiring guide</li>
        </ul>
      </Card>
    </section>
  );
}

function Card({ label, children }: { label: string; children: React.ReactNode }) {
  return (
    <article className="flex min-h-[180px] flex-col gap-3 rounded-md border border-border-soft bg-bg-1 px-6 py-[22px]">
      <div className="font-mono text-[13px] font-medium uppercase tracking-[0.16em] text-text-2">{label}</div>
      <div className="flex flex-col gap-3">
        {children}
      </div>
    </article>
  );
}

function Row({ k, v }: { k: string; v: React.ReactNode }) {
  return (
    <div className="flex items-baseline justify-between gap-3">
      <span className="font-mono text-[12px] font-medium uppercase tracking-[0.14em] text-text-2">{k}</span>
      <span className="font-mono text-[14px] text-text-1">{v}</span>
    </div>
  );
}
