// Shopping List grow supplies: loading each species' list from the Pi,
// reading why one has none, and the per-species grow-count overrides.
//
// The list per species comes from lib/shopping-list.ts loadGrowList()
// (GET /api/species/{id}/shopping-list?grows=N). Changing one species'
// grow count refetches that species only, after a short pause, so typing
// "12" asks the Pi once, for 12.

import { useEffect, useRef, useState } from "react";
import { apiGet } from "./api";
import { loadGrowList, type GrowListResult, type GrowPrefs, type GrowTarget } from "./shopping-list";

type Getter = <T>(path: string) => Promise<T>;

// ── Why a species has no list ─────────────────────────────────────────

/** The server's `detail` from an api.ts error message
 *  ('HTTP 404: {"detail":"Species profile not found"}' → "Species profile
 *  not found"); the text after the status otherwise. */
export function serverDetail(message: string): string {
  const m = /^HTTP \d+:\s*([\s\S]*)$/.exec(message);
  const body = (m ? m[1]! : message).trim();
  try {
    const parsed: unknown = JSON.parse(body);
    if (parsed && typeof parsed === "object" && typeof (parsed as { detail?: unknown }).detail === "string") {
      return (parsed as { detail: string }).detail;
    }
  } catch {
    // not JSON — the text itself
  }
  return body;
}

export type GrowProblem =
  /** 404 "Species profile not found" — no such profile on this Pi. */
  | { kind: "unknown-species" }
  /** 404 "No substrate recipes available for this species". */
  | { kind: "no-recipe" }
  /** Another 404. */
  | { kind: "no-data"; detail: string }
  /** The Pi didn't answer (network, 5xx, unexpected body). */
  | { kind: "error"; message: string };

/** Why `result` holds no list (server/app/species/router.py shopping_list
 *  raises two different 404s); null for a list. */
export function growListProblem(result: GrowListResult): GrowProblem | null {
  if (result.status === "ok") return null;
  if (result.status === "error") return { kind: "error", message: result.message };
  const detail = serverDetail(result.message);
  if (/species profile not found/i.test(detail)) return { kind: "unknown-species" };
  if (/no substrate recipe/i.test(detail)) return { kind: "no-recipe" };
  return { kind: "no-data", detail };
}

// ── Grow-count overrides ──────────────────────────────────────────────

/** The count a species shops for without an override: its active sessions,
 *  or 1 for a species added by hand. */
export function defaultGrows(target: Pick<GrowTarget, "activeSessions">): number {
  return target.activeSessions > 0 ? target.activeSessions : 1;
}

/** Set one species' grow count. A count equal to its default is no override
 *  at all — the key is dropped, so the list follows the sessions again. */
export function setGrowCount(prefs: GrowPrefs, speciesId: string, n: number, base: number): GrowPrefs {
  const grows = { ...prefs.grows };
  if (n === base) delete grows[speciesId];
  else grows[speciesId] = n;
  return { ...prefs, grows };
}

/** Drop stored overrides that no longer change anything: for a species
 *  neither active nor added, or equal to its active-session count. Only call
 *  with the Pi's real session counts — while they are unknown every session
 *  species would look inactive. Returns `prefs` itself when nothing changes. */
export function pruneGrowOverrides(prefs: GrowPrefs, counts: ReadonlyMap<string, number>): GrowPrefs {
  let changed = false;
  const grows: Record<string, number> = {};
  for (const [id, n] of Object.entries(prefs.grows)) {
    const active = counts.get(id);
    const keep = active !== undefined ? n !== active : prefs.added.includes(id);
    if (keep) grows[id] = n;
    else changed = true;
  }
  return changed ? { ...prefs, grows } : prefs;
}

/** A session species shopping for a count the operator set, not its
 *  active-session count. */
export function isGrowOverride(target: GrowTarget): boolean {
  return !target.added && target.grows !== target.activeSessions;
}

// ── Loading ───────────────────────────────────────────────────────────

/** Pause after a grow-count change before asking the Pi (per species). */
export const GROW_REFETCH_DELAY_MS = 400;

export interface GrowListSlot {
  /** The count this slot's request was for. */
  grows: number;
  /** The last answer (kept while a new count loads); null before the first. */
  result: GrowListResult | null;
  loading: boolean;
}

/**
 * Each target's list, loaded per species: a species new to the list loads
 * at once; a changed grow count reloads only that species, GROW_REFETCH_
 * DELAY_MS after the last change (the previous list stays on screen until
 * then). Nothing loads until `ready`. A late answer for a count that has
 * since changed is dropped.
 */
export function useGrowLists(
  targets: readonly GrowTarget[],
  ready: boolean,
  { delayMs = GROW_REFETCH_DELAY_MS, get = apiGet }: { delayMs?: number; get?: Getter } = {},
): Record<string, GrowListSlot> {
  const [slots, setSlots] = useState<Record<string, GrowListSlot>>({});
  const requested = useRef(new Map<string, number>());
  const timers = useRef(new Map<string, ReturnType<typeof setTimeout>>());
  const key = targets.map((t) => `${t.speciesId}:${t.grows}`).join("|");

  useEffect(() => {
    if (!ready) return;
    const wanted = new Map(targets.map((t) => [t.speciesId, t.grows]));
    // A species that left the list is forgotten; adding it back loads afresh.
    for (const id of [...requested.current.keys()]) {
      if (wanted.has(id)) continue;
      requested.current.delete(id);
      clearTimeout(timers.current.get(id));
      timers.current.delete(id);
      setSlots((s) => {
        if (!(id in s)) return s;
        const next = { ...s };
        delete next[id];
        return next;
      });
    }
    for (const [id, grows] of wanted) {
      const prev = requested.current.get(id);
      if (prev === grows) continue;
      requested.current.set(id, grows);
      clearTimeout(timers.current.get(id));
      const run = () => {
        timers.current.delete(id);
        setSlots((s) => ({ ...s, [id]: { grows, result: s[id]?.result ?? null, loading: true } }));
        void loadGrowList(id, grows, get).then((result) => {
          if (requested.current.get(id) !== grows) return;
          setSlots((s) => ({ ...s, [id]: { grows, result, loading: false } }));
        });
      };
      if (prev === undefined) run();
      else timers.current.set(id, setTimeout(run, delayMs));
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps -- `key` is the targets' identity
  }, [key, ready]);

  useEffect(() => {
    const pending = timers.current;
    return () => {
      for (const t of pending.values()) clearTimeout(t);
      pending.clear();
    };
  }, []);

  return slots;
}
