// Grow-phase helpers shared by the session, transcript and timeline views.
// The phase list itself is generated from the Pi's GrowPhase enum
// (lib/pi-enums.ts via scripts/port_enums.py), so the maps below are typed
// over it: a phase added on the Pi fails typecheck here until it is mapped.

import type { GrowSessionStub } from "@sporeprint/design";
import { GROW_PHASES, type GrowPhase } from "./pi-enums";
import type { PiSession, PiSpecies } from "./pi-types";

/** "substrate_colonization" → "substrate colonization" (wraps in a cell). */
export function phaseLabel(phase: string | null | undefined): string {
  return (phase ?? "").replace(/_/g, " ") || "—";
}

/** A list of phases for one line ("browning, primordia induction"). */
export function phaseListLabel(phases: readonly string[] | null | undefined): string {
  return (phases ?? []).map((p) => phaseLabel(p)).join(", ");
}

/** Day N of a phase, counted from 1: the day the phase is entered is day 1,
 *  24 h later is day 2. The one day count every screen shows (chamber tile,
 *  chamber detail, the session's phase-progress label), so the same grow
 *  reads the same day everywhere. Pi timestamps are Unix seconds. */
export function phaseDayNumber(enteredAtSec: number, nowSec: number = Date.now() / 1000): number {
  return Math.max(1, Math.floor((nowSec - enteredAtSec) / 86_400) + 1);
}

/** The session's current phase day ({@link phaseDayNumber}), or 0 when its
 *  phase_history has no row for the current phase (older servers return
 *  the list without it) — no day count rather than a made-up one. */
export function currentPhaseDay(
  session: Pick<PiSession, "current_phase" | "phase_history">,
  nowSec: number = Date.now() / 1000,
): number {
  const history = session.phase_history ?? [];
  const entry =
    history.find((h) => h.exited_at == null && h.phase === session.current_phase) ??
    [...history].reverse().find((h) => h.phase === session.current_phase);
  return entry ? phaseDayNumber(entry.entered_at, nowSec) : 0;
}

/** The species profile's longest expected duration for a phase, 0 when the
 *  profile has none (e.g. cold_storage). */
export function phaseDayTotal(species: PiSpecies | null | undefined, phase: string): number {
  return species?.phases?.[phase]?.expected_duration_days?.[1] ?? 0;
}

export function isGrowPhase(phase: unknown): phase is GrowPhase {
  return typeof phase === "string" && (GROW_PHASES as readonly string[]).includes(phase);
}

/** A Pi phase → the session table's display bucket. Browning (shiitake's
 *  block forming its brown skin after colonization) is still pre-fruiting. */
export const PHASE_TO_STUB: Record<GrowPhase, GrowSessionStub["phase"]> = {
  agar: "spawn",
  liquid_culture: "spawn",
  grain_colonization: "spawn",
  substrate_colonization: "spawn",
  browning: "spawn",
  cold_storage: "spawn",
  primordia_induction: "fruiting",
  fruiting: "fruiting",
  rest: "harvest",
  complete: "complete",
};

/** Phase-progress bar fill for a past phase that has its own colour — the
 *  browning stage reads brown (the --warn tan) on the bar. */
export const PHASE_SEGMENT_TONE: Partial<Record<GrowPhase, string>> = {
  browning: "bg-warn/60",
};
