import { SPECIES_LIBRARY } from "@sporeprint/design";

type SpeciesEntry = (typeof SPECIES_LIBRARY)[number];

/** The species-library entry for a session's `species_profile_id`.
 *
 *  The Pi seeds its profiles with underscored ids (`lions_mane`) while the
 *  design library — and sessions created from this UI — use the hyphenated
 *  form (`lions-mane`); the server resolves either (species_id_candidates),
 *  so this does too: exact match first, then the swapped variant. */
export function findSpecies(id: string | null | undefined): SpeciesEntry | undefined {
  if (!id) return undefined;
  return (
    SPECIES_LIBRARY.find((s) => s.id === id) ??
    SPECIES_LIBRARY.find((s) => s.id === id.replace(/_/g, "-")) ??
    SPECIES_LIBRARY.find((s) => s.id === id.replace(/-/g, "_"))
  );
}

/** One spelling per species, so ids from sessions (`lions-mane`, as this UI
 *  creates them) and from the Pi's /api/species (`lions_mane`) compare equal.
 *  Underscored, like the Pi's profile table and /api/species, so the id
 *  matches the picker and the shopping-list response; the Pi resolves either
 *  spelling (species_id_candidates), so it is safe to send back in a URL. */
export function canonicalSpeciesId(id: string): string {
  return id.replace(/-/g, "_");
}

/** A species id as people read it: the library's common name, else the id
 *  with its separators turned into spaces (a custom profile the library has
 *  never seen). */
export function speciesCommonName(id: string | null | undefined): string {
  return findSpecies(id)?.common ?? (id ?? "").replace(/[_-]+/g, " ").trim();
}
