import { useEffect, useMemo, useState } from "react";
import { useSearchParams } from "react-router-dom";
import {
  Button,
  DataTable,
  Input,
  PageHeader,
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
  SPECIES_LIBRARY,
  StatusPill,
  cn,
} from "@sporeprint/design";
import { CloudPill } from "../components/CloudPill";
import { PiTopBar } from "../components/PiTopBar";
import { apiGet, apiSend } from "../lib/api";
import { PLANNED_EVENT_KINDS } from "../lib/pi-enums";
import { phaseLabel } from "../lib/phases";
import { usePiLoad } from "../lib/use-pi-load";
import type { PiChamber, PiSession } from "../lib/pi-types";

const DOW = ["mon", "tue", "wed", "thu", "fri", "sat", "sun"];
const MONTHS = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];

// `.event.<tone>` accents (components.css) keyed by the real planner-event
// kinds (allowlist: PLANNED_EVENT_KINDS from lib/pi-enums).
const EVENT_CLASS: Record<string, string> = {
  inoculate: "signal",
  transfer: "",
  "harvest-window": "warn",
  maintenance: "",
  custom: "",
};

// ── Real Pi API shapes ──────────────────────────────────────────
interface PlannedEvent {
  id: number;
  title: string;
  kind: string;
  date: string; // YYYY-MM-DD
  chamber_id: number | null;
  session_id: number | null;
  notes: string | null;
  created_at: number;
  updated_at: number;
}
interface ChamberSlot {
  id: number;
  name: string;
  nodes: number;
  phase: string;
}
interface DerivedConflict {
  date: string;
  chamberId: number;
  chamberName: string;
  titles: string[];
}

// ── Species-dated cycle proposer (V1-2) — GET /api/planner/propose ──────
// Mirrors planner/models.py ProposedCycle. Dates arrive as ISO YYYY-MM-DD.
interface ProposedPhaseSetpoints {
  temp_min_f: number;
  temp_max_f: number;
  humidity_min: number;
  humidity_max: number;
  co2_max_ppm: number;
  co2_min_ppm: number | null;
  light_hours_on: number;
  light_hours_off: number;
  light_spectrum: string;
  fae_mode: string;
}
interface ProposedPhase {
  phase: string;
  label: string;
  start_date: string;
  end_date: string;
  duration_days: number;
  min_days: number;
  max_days: number;
  setpoints: ProposedPhaseSetpoints;
  notes: string;
}
interface ProposedCycle {
  species_id: string;
  common_name: string;
  scientific_name: string;
  start_date: string;
  end_date: string;
  total_days: number;
  harvest_date: string | null;
  phases: ProposedPhase[];
}

// ── Hardware-capability verdict (V2-2) ──────────────────────────────────
// GET /api/chambers/{id}/automation-coverage?species=... (coverage.py).
interface CoverageRequirement {
  target: string;
  channel: string | null;
  available: boolean;
  fallback: string | null;
}
interface CoveragePhase {
  phase: string;
  requirements: CoverageRequirement[];
}

/** Reconcile a handoff species id with the local library spelling so the
 *  picker reflects it: the wizard sends the underscored profile id, the
 *  species page sends the hyphenated library id. Both resolve server-side
 *  (species_id_candidates), so an id not in the library is forwarded as-is. */
function resolveSpeciesId(raw: string): string {
  if (!raw) return "";
  if (SPECIES_LIBRARY.some((s) => s.id === raw)) return raw;
  const hyphenated = raw.replace(/_/g, "-");
  return SPECIES_LIBRARY.some((s) => s.id === hyphenated) ? hyphenated : raw;
}

/** Tally automated vs total actuator requirements across every phase. */
function summarizeCoverage(phases: CoveragePhase[]): { total: number; automated: number } {
  let total = 0;
  let automated = 0;
  for (const p of phases) {
    for (const r of p.requirements) {
      total += 1;
      if (r.available) automated += 1;
    }
  }
  return { total, automated };
}

function pad(n: number): string {
  return String(n).padStart(2, "0");
}
function dateStr(y: number, m0: number, day: number): string {
  return `${y}-${pad(m0 + 1)}-${pad(day)}`;
}

export function PlannerPage() {
  const today = useMemo(() => new Date(), []);
  const [year, setYear] = useState(today.getFullYear());
  const [monthIdx, setMonthIdx] = useState(today.getMonth());
  const [refreshKey, setRefreshKey] = useState(0);

  const [actionError, setActionError] = useState<string | null>(null);
  const [showAdd, setShowAdd] = useState(false);
  const [draggingId, setDraggingId] = useState<number | null>(null);
  const [hoverDay, setHoverDay] = useState<number | null>(null);

  const total = useMemo(() => new Date(year, monthIdx + 1, 0).getDate(), [year, monthIdx]);
  const lead = useMemo(() => (new Date(year, monthIdx, 1).getDay() + 6) % 7, [year, monthIdx]);

  // Month events for the visible month.
  const { data: events, error: eventsError } = usePiLoad(
    () =>
      apiGet<PlannedEvent[]>(
        `/api/planner/events?from=${dateStr(year, monthIdx, 1)}&to=${dateStr(year, monthIdx, total)}`,
      ),
    [year, monthIdx, total, refreshKey],
  );

  // Chambers + sessions (for the add form + the chamber-slots table).
  // Failures degrade to empty lists — the calendar itself still works.
  const { data: refRows } = usePiLoad(
    () =>
      Promise.all([
        apiGet<PiChamber[]>("/api/chambers").catch(() => [] as PiChamber[]),
        apiGet<PiSession[]>("/api/sessions").catch(() => [] as PiSession[]),
      ]),
    [refreshKey],
  );
  const [chambers, sessions] = refRows ?? [[], []];

  const eventsByDay = useMemo(() => {
    const map = new Map<number, PlannedEvent[]>();
    for (const ev of events ?? []) {
      const parts = ev.date.split("-");
      const ey = Number(parts[0]);
      const em = Number(parts[1]);
      const ed = Number(parts[2]);
      if (ey === year && em === monthIdx + 1) {
        const list = map.get(ed) ?? [];
        list.push(ev);
        map.set(ed, list);
      }
    }
    return map;
  }, [events, year, monthIdx]);

  // Same-day + same-chamber collisions (client-derived).
  const conflicts = useMemo<DerivedConflict[]>(() => {
    const groups = new Map<string, PlannedEvent[]>();
    for (const ev of events ?? []) {
      if (ev.chamber_id == null) continue;
      const key = `${ev.date}::${ev.chamber_id}`;
      const list = groups.get(key) ?? [];
      list.push(ev);
      groups.set(key, list);
    }
    const out: DerivedConflict[] = [];
    for (const [, list] of groups) {
      const first = list[0];
      if (list.length < 2 || !first || first.chamber_id == null) continue;
      const cid = first.chamber_id;
      out.push({
        date: first.date,
        chamberId: cid,
        chamberName: chambers.find((c) => c.id === cid)?.name ?? `chamber ${cid}`,
        titles: list.map((e) => e.title),
      });
    }
    return out.sort((a, b) => a.date.localeCompare(b.date));
  }, [events, chambers]);

  const slots = useMemo<ChamberSlot[]>(
    () =>
      chambers.map((c) => {
        const active = c.active_session_id != null ? sessions.find((s) => s.id === c.active_session_id) : undefined;
        return {
          id: c.id,
          name: c.name,
          nodes: c.node_ids.length,
          phase: active ? phaseLabel(active.current_phase) : "idle",
        };
      }),
    [chambers, sessions],
  );

  const cells: Array<{ day: number; events: PlannedEvent[] } | null> = [];
  for (let i = 0; i < lead; i++) cells.push(null);
  for (let day = 1; day <= total; day++) cells.push({ day, events: eventsByDay.get(day) ?? [] });
  while (cells.length < 42) cells.push(null);

  function shift(delta: number) {
    let m = monthIdx + delta;
    let y = year;
    while (m < 0) {
      m += 12;
      y -= 1;
    }
    while (m > 11) {
      m -= 12;
      y += 1;
    }
    setMonthIdx(m);
    setYear(y);
  }

  async function reschedule(eventId: number, day: number) {
    setActionError(null);
    try {
      await apiSend(`/api/planner/events/${eventId}`, "PUT", { date: dateStr(year, monthIdx, day) });
      setRefreshKey((k) => k + 1);
    } catch (err) {
      setActionError(err instanceof Error ? err.message : "reschedule failed");
    }
  }

  async function remove(eventId: number) {
    setActionError(null);
    try {
      await apiSend(`/api/planner/events/${eventId}`, "DELETE");
      setRefreshKey((k) => k + 1);
    } catch (err) {
      setActionError(err instanceof Error ? err.message : "delete failed");
    }
  }

  function handleDrop(targetDay: number) {
    const id = draggingId;
    setDraggingId(null);
    setHoverDay(null);
    if (id !== null) void reschedule(id, targetDay);
  }

  const monthLabel = `${MONTHS[monthIdx]} ${year}`;
  const eventCount = events?.length ?? 0;

  return (
    <>
      <PiTopBar
        crumbs={[{ label: "plan" }, { label: "planner", active: true }]}
        right={<CloudPill />}
      />

      <PageHeader
        eyebrow="Plan"
        title={monthLabel}
        italic={false}
        meta={
          <span>
            {eventCount} event{eventCount === 1 ? "" : "s"} · {conflicts.length} conflict
            {conflicts.length === 1 ? "" : "s"} · drag an event to reschedule
          </span>
        }
        right={
          <div className="flex flex-wrap items-center gap-2">
            <Button type="button" variant="ghost" size="sm" onClick={() => shift(-1)} aria-label="previous month">←</Button>
            <Button
              type="button"
              variant="ghost"
              size="sm"
              onClick={() => {
                setYear(today.getFullYear());
                setMonthIdx(today.getMonth());
              }}
            >
              today
            </Button>
            <Button type="button" variant="ghost" size="sm" onClick={() => shift(1)} aria-label="next month">→</Button>
            <Button type="button" variant={showAdd ? "solid" : "ghost"} onClick={() => setShowAdd((v) => !v)}>
              {showAdd ? "cancel" : "add event →"}
            </Button>
          </div>
        }
      />

      <div className="grid grid-cols-[minmax(0,1fr)_400px] gap-[22px] px-4 pt-4 pb-6 sm:px-7 sm:pt-[22px] sm:pb-7 max-[1180px]:grid-cols-1">
        <main className="flex flex-col gap-3.5">
          <PlanGrowPanel chambers={chambers} />

          {showAdd && (
            <AddEventForm
              chambers={chambers}
              defaultDate={dateStr(year, monthIdx, 1)}
              onClose={() => setShowAdd(false)}
              onCreated={() => {
                setShowAdd(false);
                setRefreshKey((k) => k + 1);
              }}
            />
          )}

          {eventsError && (
            <p className="font-mono text-[13px] tracking-[0.05em] text-err">Failed to load events: {eventsError}</p>
          )}
          {actionError && (
            <p className="font-mono text-[13px] tracking-[0.05em] text-err">{actionError}</p>
          )}

          {/* `.calendar`/`.dow`/`.day`/`.dnum`/`.event` — self-contained
              calendar-grid family (kept legacy, same as cloud-web's planner). */}
          <div className="calendar">
            {DOW.map((d) => (
              <div key={d} className="dow">{d}</div>
            ))}
            {cells.map((c, i) => {
              if (!c) return <div key={`pad-${i}`} className="day dim" />;
              const isHover = hoverDay === c.day && draggingId !== null;
              return (
                <div
                  key={`d-${c.day}`}
                  className={cn("day cursor-default", isHover && "border-accent-line bg-accent-soft")}
                  onDragOver={(e) => {
                    e.preventDefault();
                    setHoverDay(c.day);
                  }}
                  onDragLeave={() => setHoverDay((d) => (d === c.day ? null : d))}
                  onDrop={() => handleDrop(c.day)}
                >
                  <span className="dnum">{c.day}</span>
                  {c.events.map((ev) => (
                    <span
                      key={ev.id}
                      draggable
                      onDragStart={() => setDraggingId(ev.id)}
                      onDragEnd={() => {
                        setDraggingId(null);
                        setHoverDay(null);
                      }}
                      title={ev.notes ?? ev.title}
                      className={cn(
                        `event ${EVENT_CLASS[ev.kind] ?? ""}`.trim(),
                        "flex items-center justify-between gap-1 cursor-grab",
                        draggingId === ev.id && "opacity-40",
                      )}
                    >
                      <span className="truncate">{ev.title}</span>
                      <button
                        type="button"
                        aria-label={`delete ${ev.title}`}
                        onClick={(e) => {
                          e.stopPropagation();
                          void remove(ev.id);
                        }}
                        className="shrink-0 px-1 text-text-3 hover:text-err"
                      >
                        ×
                      </button>
                    </span>
                  ))}
                </div>
              );
            })}
          </div>
        </main>

        <aside className="flex flex-col gap-3.5">
          <section className="flex flex-col gap-[18px] rounded-md border border-border-soft bg-bg-1 p-[26px]">
            <div className="mb-1.5 font-mono text-[15px] font-medium tracking-[0.16em] uppercase text-text-2">
              Conflicts · {conflicts.length}
            </div>
            {conflicts.length === 0 ? (
              <p className="font-body text-[14px] leading-[1.55] text-text-1">
                No same-day, same-chamber collisions for {monthLabel}.
              </p>
            ) : (
              <ul className="flex flex-col gap-2.5">
                {conflicts.map((c, i) => (
                  <li
                    key={`cf-${i}`}
                    className="flex flex-col gap-1.5 rounded-sm border border-warn bg-bg-2 px-3.5 py-3"
                  >
                    <div className="flex items-center justify-between gap-3">
                      <span className="font-mono text-[14px] text-text-1">{c.date}</span>
                      <StatusPill tone="warn">double-booked</StatusPill>
                    </div>
                    <span className="font-body text-[14px] leading-[1.55] text-text-1">
                      {c.chamberName}: {c.titles.join(" · ")}
                    </span>
                  </li>
                ))}
              </ul>
            )}
          </section>

          <section className="flex flex-col gap-[18px] rounded-md border border-border-soft bg-bg-1 p-[26px]">
            <div className="mb-1.5 font-mono text-[15px] font-medium tracking-[0.16em] uppercase text-text-2">
              Chamber slots
            </div>
            {slots.length === 0 ? (
              <p className="font-mono text-[12px] text-text-2">No chambers configured on this Pi.</p>
            ) : (
              <DataTable<ChamberSlot>
                rowKey={(s) => String(s.id)}
                columns={[
                  { key: "name", header: "Chamber", render: (s) => <span className="font-mono text-text-0">{s.name}</span> },
                  { key: "nodes", header: "Nodes", align: "right", render: (s) => <>{s.nodes}</> },
                  { key: "phase", header: "Active phase", render: (s) => <>{s.phase}</> },
                ]}
                rows={slots}
              />
            )}
          </section>
        </aside>
      </div>
    </>
  );
}

// ── Plan-a-grow: dated cycle proposal (V1-2) + hardware-coverage verdict
//    (V2-2). The wizard / species-page handoff (?species=&start=) is read on
//    mount (V1-3). All three read real Pi endpoints — nothing is fabricated.
function PlanGrowPanel({ chambers }: { chambers: PiChamber[] }) {
  const [searchParams] = useSearchParams();
  const today = useMemo(() => new Date(), []);
  const [species, setSpecies] = useState<string>(() =>
    resolveSpeciesId(searchParams.get("species") ?? ""),
  );
  const [start, setStart] = useState<string>(
    () => searchParams.get("start") ?? dateStr(today.getFullYear(), today.getMonth(), today.getDate()),
  );
  const [chamberId, setChamberId] = useState<string>("");

  const [cycle, setCycle] = useState<ProposedCycle | null>(null);
  const [cycleLoading, setCycleLoading] = useState(false);
  const [cycleError, setCycleError] = useState<string | null>(null);

  const [coverage, setCoverage] = useState<CoveragePhase[] | null>(null);
  const [coverageLoading, setCoverageLoading] = useState(false);
  const [coverageError, setCoverageError] = useState<string | null>(null);

  // Dated per-phase cycle (V1-2) — refetched whenever species / start change.
  useEffect(() => {
    if (!species) {
      setCycle(null);
      setCycleError(null);
      setCycleLoading(false);
      return;
    }
    let cancelled = false;
    setCycleLoading(true);
    setCycleError(null);
    const q = new URLSearchParams({ species });
    if (start) q.set("start", start);
    apiGet<ProposedCycle>(`/api/planner/propose?${q.toString()}`)
      .then((c) => {
        if (!cancelled) setCycle(c);
      })
      .catch((err: unknown) => {
        if (cancelled) return;
        setCycleError(err instanceof Error ? err.message : "could not propose a cycle");
        setCycle(null);
      })
      .finally(() => {
        if (!cancelled) setCycleLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [species, start]);

  // Hardware-capability verdict (V2-2) — only once a chamber is chosen.
  useEffect(() => {
    if (!species || !chamberId) {
      setCoverage(null);
      setCoverageError(null);
      setCoverageLoading(false);
      return;
    }
    let cancelled = false;
    setCoverageLoading(true);
    setCoverageError(null);
    apiGet<{ phases: CoveragePhase[] }>(
      `/api/chambers/${encodeURIComponent(chamberId)}/automation-coverage?species=${encodeURIComponent(species)}`,
    )
      .then((res) => {
        if (!cancelled) setCoverage(Array.isArray(res.phases) ? res.phases : []);
      })
      .catch((err: unknown) => {
        if (cancelled) return;
        setCoverageError(err instanceof Error ? err.message : "coverage check failed");
        setCoverage(null);
      })
      .finally(() => {
        if (!cancelled) setCoverageLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [species, chamberId]);

  return (
    <section className="flex flex-col gap-[18px] rounded-md border border-border-soft bg-bg-1 p-[26px]">
      <div className="flex flex-wrap items-baseline justify-between gap-3">
        <div className="font-mono text-[15px] font-medium tracking-[0.16em] uppercase text-text-2">Plan a grow</div>
        <span className="font-mono text-[12px] text-text-2">
          species-dated cycle + hardware coverage, before you commit
        </span>
      </div>

      <div className="grid grid-cols-[repeat(auto-fit,minmax(180px,1fr))] items-end gap-3">
        <Field label="Species">
          <Select value={species} onValueChange={setSpecies}>
            <SelectTrigger aria-label="species" className="w-full">
              <span className="min-w-0 flex-1 truncate text-left">
                <SelectValue placeholder="choose a species" />
              </span>
            </SelectTrigger>
            <SelectContent>
              {SPECIES_LIBRARY.map((s) => (
                <SelectItem key={s.id} value={s.id}>
                  {s.common} · {s.binomial}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </Field>
        <Field label="Inoculation date">
          <Input type="date" value={start} onChange={(e) => setStart(e.target.value)} />
        </Field>
        <Field label="Check chamber (optional)">
          <Select value={chamberId || "none"} onValueChange={(v) => setChamberId(v === "none" ? "" : v)}>
            <SelectTrigger aria-label="chamber" className="w-full">
              <span className="min-w-0 flex-1 truncate text-left">
                <SelectValue />
              </span>
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="none">no coverage check</SelectItem>
              {chambers.map((c) => (
                <SelectItem key={c.id} value={String(c.id)}>{c.name}</SelectItem>
              ))}
            </SelectContent>
          </Select>
        </Field>
      </div>

      {!species && (
        <p className="font-body text-[14px] leading-[1.55] text-text-2">
          Pick a species — or arrive here from the wizard or species library — to lay out a dated
          inoculation-to-harvest cycle. Add a chamber to verify its hardware can automate every phase first.
        </p>
      )}

      {species && (
        <>
          {cycleError && (
            <p className="font-mono text-[13px] tracking-[0.05em] text-err">Failed to propose a cycle: {cycleError}</p>
          )}
          {cycleLoading && (
            <p className="font-mono text-[13px] tracking-[0.05em] text-text-2">Proposing cycle…</p>
          )}
          {cycle && <ProposedCycleView cycle={cycle} />}
        </>
      )}

      {species && chamberId && (
        <>
          {coverageError && (
            <p className="font-mono text-[13px] tracking-[0.05em] text-err">Coverage check failed: {coverageError}</p>
          )}
          {coverageLoading && (
            <p className="font-mono text-[13px] tracking-[0.05em] text-text-2">Checking hardware coverage…</p>
          )}
          {coverage && <CoverageVerdict phases={coverage} />}
        </>
      )}
    </section>
  );
}

/** A cycle-table date: "Oct 6" when it falls in the cycle's start year (the
 *  header above the table carries the full start and end dates), "Jan 20,
 *  2027" when it does not. The ISO dates made the window cell ~180px wide,
 *  and at 1440 the table ran 52px past its 628px card, clipping FAE. */
export function cycleDate(iso: string, startYear: string): string {
  const [y, m, d] = iso.split("-");
  const month = MONTHS[Number(m) - 1];
  if (!y || !month || !d) return iso;
  const short = `${month.slice(0, 3)} ${Number(d)}`;
  return y === startYear ? short : `${short}, ${y}`;
}

function ProposedCycleView({ cycle }: { cycle: ProposedCycle }) {
  const th =
    "border-b border-border-soft bg-bg-1 px-3 py-2.5 text-left font-mono text-[12px] font-medium uppercase tracking-[0.14em] text-text-2";
  const td = "border-t border-border-soft px-3 py-2.5 align-middle font-mono text-text-0";
  const startYear = cycle.start_date.slice(0, 4);
  return (
    <div className="flex flex-col gap-2.5">
      <div className="flex flex-wrap items-baseline justify-between gap-3">
        <span className="font-serif text-[22px] font-medium italic leading-[1.18] text-text-0">
          {cycle.scientific_name}
        </span>
        <span className="font-mono text-[12px] text-text-2">
          {cycle.start_date} → {cycle.end_date} · {cycle.total_days} days
          {cycle.harvest_date ? ` · first harvest ${cycle.harvest_date}` : ""}
        </span>
      </div>
      <div className="overflow-x-auto">
        <table className="w-full min-w-[560px] overflow-hidden border-collapse rounded-md border border-border-soft bg-bg-1 font-body text-[13px] text-text-1">
          <thead>
            <tr>
              <th className={th}>Phase</th>
              <th className={th}>Window</th>
              <th className={th}>Days</th>
              <th className={th}>Temp</th>
              <th className={th}>RH</th>
              <th className={th}>CO₂</th>
              <th className={th}>Light</th>
              <th className={th}>FAE</th>
            </tr>
          </thead>
          <tbody>
            {cycle.phases.map((p) => (
              <tr key={p.phase} className="hover:bg-bg-2">
                <td className="border-t border-border-soft px-3 py-2.5 align-middle font-body text-text-0">{p.label}</td>
                {/* Each date and the day range stay whole: at 1440 the cells
                    broke at the hyphens ("2026-" / "10-06 →"). The line
                    may break only after the arrow / before the range. The
                    full ISO date is the <time> value and its tooltip. */}
                <td className={td} data-planner-window="">
                  <time dateTime={p.start_date} title={p.start_date} className="whitespace-nowrap">
                    {cycleDate(p.start_date, startYear)} →
                  </time>{" "}
                  <time dateTime={p.end_date} title={p.end_date} className="whitespace-nowrap">
                    {cycleDate(p.end_date, startYear)}
                  </time>
                </td>
                <td className={td}>
                  <span className="whitespace-nowrap">{p.duration_days}d</span>{" "}
                  <span className="whitespace-nowrap text-text-3">
                    ({p.min_days}–{p.max_days})
                  </span>
                </td>
                <td className={td}>{p.setpoints.temp_min_f}–{p.setpoints.temp_max_f}°F</td>
                <td className={td}>{p.setpoints.humidity_min}–{p.setpoints.humidity_max}%</td>
                <td className={td}>≤{p.setpoints.co2_max_ppm}</td>
                <td className={td}>{p.setpoints.light_hours_on}/{p.setpoints.light_hours_off}</td>
                <td className={td}>{p.setpoints.fae_mode}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

function CoverageVerdict({ phases }: { phases: CoveragePhase[] }) {
  const { total, automated } = summarizeCoverage(phases);
  const gaps = total - automated;
  return (
    <div className="flex flex-col gap-2.5 border-t border-border-soft pt-3.5">
      <div className="flex flex-wrap items-center gap-2.5">
        <span className="font-mono text-[13px] font-medium tracking-[0.16em] uppercase text-text-2">Hardware coverage</span>
        {total === 0 ? (
          <span className="font-mono text-[12px] text-text-2">no automatable requirements for this species</span>
        ) : (
          <>
            <StatusPill tone={gaps === 0 ? "signal" : "warn"}>
              {automated} of {total} automated
            </StatusPill>
            {gaps > 0 && (
              <span className="font-mono text-[12px] text-text-2">
                {gaps} phase requirement{gaps === 1 ? "" : "s"} fall back or need a manual step
              </span>
            )}
          </>
        )}
      </div>
      {phases.map((phase) =>
        phase.requirements.length === 0 ? null : (
          <div key={phase.phase} className="flex flex-col gap-1.5">
            <span className="font-mono text-[12px] font-medium tracking-[0.14em] uppercase text-text-2">
              {phaseLabel(phase.phase)}
            </span>
            {phase.requirements.map((req, i) => (
              <div
                key={`${phase.phase}-${req.target}-${req.channel ?? ""}-${i}`}
                className="grid grid-cols-[1fr_auto] items-start gap-2.5 rounded-sm border border-border-soft bg-bg-2 px-2.5 py-2"
              >
                <div className="flex min-w-0 flex-col gap-0.5">
                  <span className="font-mono text-[14px] text-text-0">
                    {req.channel ? `${req.target} · ${req.channel}` : req.target}
                  </span>
                  {!req.available && req.fallback && (
                    <span className="font-mono text-[12px] text-text-2">fallback · {req.fallback}</span>
                  )}
                </div>
                <StatusPill tone={req.available ? "signal" : req.fallback ? "warn" : "err"}>
                  {req.available ? "available" : req.fallback ? "fallback" : "unavailable"}
                </StatusPill>
              </div>
            ))}
          </div>
        ),
      )}
    </div>
  );
}

function Field({ label, children }: { label: string; children: React.ReactNode }) {
  return (
    <label className="flex flex-col gap-1.5">
      <span className="font-mono text-[12px] font-medium tracking-[0.14em] uppercase text-text-2">{label}</span>
      {children}
    </label>
  );
}

function AddEventForm({
  chambers,
  defaultDate,
  onClose,
  onCreated,
}: {
  chambers: PiChamber[];
  defaultDate: string;
  onClose: () => void;
  onCreated: () => void;
}) {
  const [title, setTitle] = useState("");
  const [kind, setKind] = useState<string>("inoculate");
  const [date, setDate] = useState(defaultDate);
  const [chamber, setChamber] = useState("none");
  const [notes, setNotes] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  return (
    <form
      className="flex flex-col gap-3 rounded-md border border-border-soft bg-bg-1 p-[26px]"
      onSubmit={async (e) => {
        e.preventDefault();
        if (submitting || !title.trim()) return;
        setSubmitting(true);
        setError(null);
        try {
          await apiSend("/api/planner/events", "POST", {
            title: title.trim(),
            kind,
            date,
            chamber_id: chamber === "none" ? null : Number(chamber),
            notes: notes.trim() || null,
          });
          onCreated();
        } catch (err) {
          setError(err instanceof Error ? err.message : "create failed");
        } finally {
          setSubmitting(false);
        }
      }}
    >
      <div className="mb-1.5 font-mono text-[15px] font-medium tracking-[0.16em] uppercase text-text-2">New planned event</div>
      <div className="grid grid-cols-[repeat(auto-fit,minmax(180px,1fr))] gap-3">
        <Field label="Title">
          <Input value={title} onChange={(e) => setTitle(e.target.value)} placeholder="e.g. inoculate grain jars" />
        </Field>
        <Field label="Kind">
          <Select value={kind} onValueChange={setKind}>
            <SelectTrigger aria-label="kind" className="w-full">
              <span className="min-w-0 flex-1 truncate text-left">
                <SelectValue />
              </span>
            </SelectTrigger>
            <SelectContent>
              {PLANNED_EVENT_KINDS.map((k) => (
                <SelectItem key={k} value={k}>{k}</SelectItem>
              ))}
            </SelectContent>
          </Select>
        </Field>
        <Field label="Date">
          <Input type="date" value={date} onChange={(e) => setDate(e.target.value)} />
        </Field>
        <Field label="Chamber (optional)">
          <Select value={chamber} onValueChange={setChamber}>
            <SelectTrigger aria-label="chamber" className="w-full">
              <span className="min-w-0 flex-1 truncate text-left">
                <SelectValue />
              </span>
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="none">unassigned</SelectItem>
              {chambers.map((c) => (
                <SelectItem key={c.id} value={String(c.id)}>{c.name}</SelectItem>
              ))}
            </SelectContent>
          </Select>
        </Field>
        <Field label="Notes (optional)">
          <Input value={notes} onChange={(e) => setNotes(e.target.value)} placeholder="optional" />
        </Field>
      </div>
      {error && <p className="font-mono text-[12px] text-err">{error}</p>}
      <div className="flex items-center gap-2.5 justify-end">
        <Button type="button" variant="ghost" onClick={onClose}>cancel</Button>
        <Button type="submit" disabled={submitting || !title.trim()}>
          {submitting ? "adding…" : "add event →"}
        </Button>
      </div>
    </form>
  );
}
