import type { Telemetry } from "../data/types";
import { formatReading } from "../lib/format";

/**
 * 2×2 telemetry grid per components.md §4. The `accent` arg picks one
 * cell to highlight in saffron — semantic, used for "currently
 * adjusting" e.g. humidity while the mister is engaged.
 */
export function KvCluster({
  t,
  accent,
}: {
  t: Telemetry;
  accent?: "temp" | "humidity" | "co2" | "vpd";
}) {
  return (
    <div className="f-kv" role="list">
      {/* A sensor with no reading (NaN) shows "—" with no unit. */}
      <Cell label="Temp" value={formatReading(t.tempF, 1)} unit="°F" accent={accent === "temp"} />
      <Cell label="Humidity" value={formatReading(t.humidity)} unit="%" accent={accent === "humidity"} />
      <Cell label="CO₂" value={formatReading(t.co2)} unit="ppm" accent={accent === "co2"} />
      <Cell label="VPD" value={formatReading(t.vpdKpa, 2)} unit="kPa" accent={accent === "vpd"} />
    </div>
  );
}

function Cell({ label, value, unit, accent }: { label: string; value: string; unit: string; accent?: boolean }) {
  return (
    <div className={accent ? "accent" : ""} role="listitem">
      <div className="k">{label}</div>
      <div className="v">
        {value}
        {value !== "—" && <span className="u">{unit}</span>}
      </div>
    </div>
  );
}
