// Shopping List page data. Three sources, none of them demo rows:
//
//   • Hardware — the BOM the Builder sent (lib/shopping-bom.ts hand-off),
//     read from the Pi's GET /api/builder/tiers/{id} with the generated
//     built-in copy as fallback, priced with the Builder's own line-cost
//     helpers (lib/builder-data.ts) so both pages show the same total.
//   • Grow supplies — the Pi's GET /api/species/{id}/shopping-list
//     (server/app/species/shopping.py) for each species with an active
//     session, plus any species the operator adds. The generator returns
//     quantities and supplier links but no prices.
//   • Custom items the operator types in.
//
// Purchased flags and notes are keyed by stable ids under the same
// localStorage keys the page always used:
//   hw:<component name>       a hardware part, whichever build it is in — so
//                             switching build keeps the Pi, the PSU and the
//                             kits already bought (it was bom:<tierId>:<name>;
//                             migrateHardwareKeys folds those in)
//   grow:*:<item>             a grow supply every species on the list shares
//                             (merged across species — mergeGrowLists)
//   grow:<speciesId>:<item>   a species' own supply: its spawn, or any other
//                             culture / inoculant (isPerSpeciesItem). Also
//                             the key a shared supply was ticked under
//                             before the lists were merged — such a tick
//                             counts for its species only (growPurchase).
//   custom:<id>               a custom item

import { HARDWARE_TIERS, type BuilderComponent, type BuilderTier } from "@sporeprint/design";
import { apiGet } from "./api";
import { bomLine, groupByCategory, loadBuilderLive, type CategoryGroup } from "./builder-data";
import type { PiSession, PiSpecies } from "./pi-types";
import type { ShoppingBomTierId } from "./shopping-bom";
import { canonicalSpeciesId } from "./species";

// ── localStorage ──────────────────────────────────────────────────────

export const STORAGE_PURCHASED = "pi:shopping:purchased";
export const STORAGE_NOTES = "pi:shopping:notes";
export const STORAGE_CUSTOM = "pi:shopping:custom";
/** Species added by hand + per-species grow-count overrides. */
export const STORAGE_GROW = "pi:shopping:grow";

/** Read + validate a stored JSON value; `fallback` when absent, unparsable,
 *  or storage is unavailable (private window, blocked site data). */
export function loadStored<T>(key: string, parse: (value: unknown) => T, fallback: T): T {
  try {
    if (typeof window === "undefined") return fallback;
    const raw = window.localStorage.getItem(key);
    return raw ? parse(JSON.parse(raw)) : fallback;
  } catch {
    return fallback;
  }
}

export function saveStored(key: string, value: unknown): void {
  try {
    if (typeof window === "undefined") return;
    window.localStorage.setItem(key, JSON.stringify(value));
  } catch {
    // quota / private mode — the list still works for this visit
  }
}

const isRecord = (v: unknown): v is Record<string, unknown> =>
  typeof v === "object" && v !== null && !Array.isArray(v);

/** { id: true } purchased flags; anything that is not a boolean is dropped. */
export function toFlagMap(value: unknown): Record<string, boolean> {
  if (!isRecord(value)) return {};
  const out: Record<string, boolean> = {};
  for (const [k, v] of Object.entries(value)) if (typeof v === "boolean") out[k] = v;
  return out;
}

/** { id: "note" } — non-string values are dropped. */
export function toNoteMap(value: unknown): Record<string, string> {
  if (!isRecord(value)) return {};
  const out: Record<string, string> = {};
  for (const [k, v] of Object.entries(value)) if (typeof v === "string") out[k] = v;
  return out;
}

// ── Ids ───────────────────────────────────────────────────────────────

/** A hardware part by name — the same id in every build. */
export const hardwareItemId = (name: string) => `hw:${name}`;
/** A species' own grow supply (its spawn). */
export const growItemId = (speciesId: string, name: string) => `grow:${speciesId}:${name}`;
/** A grow supply shared by every species on the list ("*": no species id
 *  is a bare asterisk). */
export const sharedGrowItemId = (name: string) => `grow:*:${name}`;

/** The per-build hardware key this page used before (bom:<tierId>:<name>). */
const LEGACY_BOM_ID = /^bom:(?:bare_bones|recommended|all_the_things):([\s\S]+)$/;

/** Fold `from` keys into `to` keys: each pair's values merge with `combine`
 *  (the value already under `to` first), and the `from` key goes. Returns
 *  `map` itself when no `from` key is present, so a state update with it is
 *  a no-op. */
function foldKeys<T>(
  map: Record<string, T>,
  pairs: ReadonlyArray<readonly [from: string, to: string]>,
  combine: (a: T, b: T) => T,
): Record<string, T> {
  const present = pairs.filter(([from]) => from in map);
  if (present.length === 0) return map;
  const out = { ...map };
  for (const [from, to] of present) {
    const value = out[from]!;
    delete out[from];
    out[to] = to in out ? combine(out[to]!, value) : value;
  }
  return out;
}

/** Bought under any key → bought. */
export const combineFlags = (a: boolean, b: boolean) => a || b;

/** Two notes for one item: both kept (distinct, non-empty), " · " between. */
export function combineNotes(a: string, b: string): string {
  const parts: string[] = [];
  for (const n of [a, b].flatMap((s) => s.split(" · "))) {
    const t = n.trim();
    if (t && !parts.includes(t)) parts.push(t);
  }
  return parts.join(" · ");
}

/** The stored map with every per-build hardware key (bom:<tierId>:<name>)
 *  folded into its build-independent one (hw:<name>) — a part bought, or
 *  noted, under any build stays bought / noted under all of them. */
export function migrateHardwareKeys<T>(map: Record<string, T>, combine: (a: T, b: T) => T): Record<string, T> {
  const pairs: Array<[string, string]> = [];
  for (const key of Object.keys(map)) {
    const m = LEGACY_BOM_ID.exec(key);
    if (m) pairs.push([key, hardwareItemId(m[1]!)]);
  }
  return foldKeys(map, pairs, combine);
}

/** The stored map with each per-species key of a now-merged grow supply
 *  (grow:<speciesId>:<item>) folded into the merged row's id. For notes
 *  (combineNotes keeps every one). Purchased flags are not folded: one
 *  species' tick does not buy the merged row for the others (growPurchase
 *  reads them per species instead). */
export function migrateGrowKeys<T>(
  map: Record<string, T>,
  rows: ReadonlyArray<Pick<GrowRow, "id" | "legacyIds">>,
  combine: (a: T, b: T) => T,
): Record<string, T> {
  return foldKeys(
    map,
    rows.flatMap((r) => r.legacyIds.map((from) => [from, r.id] as const)),
    combine,
  );
}

export function newCustomId(now: number = Date.now()): string {
  return `custom:${now.toString(36)}${Math.random().toString(36).slice(2, 6)}`;
}

// ── Custom items ──────────────────────────────────────────────────────

/** Same fields the page has stored under pi:shopping:custom since it
 *  shipped, so existing lists keep loading. `estCost` is the whole line. */
export interface CustomItem {
  id: string;
  category: string;
  item: string;
  qty: number;
  unit: string;
  supplier: string;
  url: string;
  estCost: number;
}

const num = (v: unknown, fallback: number) => (typeof v === "number" && Number.isFinite(v) ? v : fallback);
const str = (v: unknown, fallback: string) => (typeof v === "string" ? v : fallback);

/** Stored custom items; rows without an id or a name are dropped. */
export function toCustomItems(value: unknown): CustomItem[] {
  if (!Array.isArray(value)) return [];
  const out: CustomItem[] = [];
  for (const v of value) {
    if (!isRecord(v) || typeof v.id !== "string" || typeof v.item !== "string" || !v.item.trim()) continue;
    out.push({
      id: v.id,
      category: str(v.category, "Custom"),
      item: v.item,
      qty: Math.max(1, num(v.qty, 1)),
      unit: str(v.unit, "ea"),
      supplier: str(v.supplier, ""),
      url: str(v.url, ""),
      estCost: Math.max(0, num(v.estCost, 0)),
    });
  }
  return out;
}

export function customTotal(items: CustomItem[]): number {
  return items.reduce((sum, it) => sum + it.estCost, 0);
}

// ── Links ─────────────────────────────────────────────────────────────

/** Only absolute http(s) URLs are rendered as links. */
export function isHttpUrl(value: string): boolean {
  try {
    const u = new URL(value);
    return u.protocol === "http:" || u.protocol === "https:";
  } catch {
    return false;
  }
}

/** "https://www.amazon.com/s?k=x" → "amazon.com search"; "https://fungi.com" → "fungi.com". */
export function linkLabel(href: string): string {
  const u = new URL(href);
  const host = u.hostname.replace(/^www\./, "");
  return u.search ? `${host} search` : host;
}

export interface SupplierLinks {
  links: Array<{ href: string; label: string }>;
  /** Plain-text sourcing hints ("Available at local feed stores"). */
  hints: string[];
}

/** The server's `supplier_links` mixes URLs with plain-text hints. */
export function splitSupplierLinks(raw: readonly string[] | undefined): SupplierLinks {
  const out: SupplierLinks = { links: [], hints: [] };
  for (const s of raw ?? []) {
    const v = s.trim();
    if (!v) continue;
    if (isHttpUrl(v)) out.links.push({ href: v, label: linkLabel(v) });
    else out.hints.push(v);
  }
  return out;
}

// ── Hardware (the sent BOM) ───────────────────────────────────────────

type Getter = <T>(path: string) => Promise<T>;

/** The Pi's tier BOMs (all or nothing, exactly as the Builder loads them),
 *  or null when the Pi can't serve them. Only /api/builder/tiers* is
 *  requested — the models / diagrams / firmware listings are not needed. */
export async function loadBomTiers(get: Getter = apiGet): Promise<BuilderTier[] | null> {
  const tiersOnly: Getter = <T>(path: string) =>
    path.startsWith("/api/builder/tiers") ? get<T>(path) : Promise.reject<T>(new Error("not used by /shopping"));
  return (await loadBuilderLive(tiersOnly)).tiers;
}

export interface ResolvedBomTier {
  tier: BuilderTier | null;
  /** True when `tier` came from this Pi, false for the built-in copy. */
  live: boolean;
}

/** The sent tier from the Pi's BOM, else from the built-in copy. */
export function resolveBomTier(liveTiers: BuilderTier[] | null, tierId: ShoppingBomTierId): ResolvedBomTier {
  const live = liveTiers?.find((t) => t.id === tierId);
  if (live) return { tier: live, live: true };
  return { tier: HARDWARE_TIERS.find((t) => t.id === tierId) ?? null, live: false };
}

/** One hardware line, sized and priced like the Builder's (bomLine). Its
 *  units / packs / packSize are what lib/bom-labels words. */
export interface BomLine {
  /** hardwareItemId(name): the same in every build. */
  id: string;
  component: BuilderComponent;
  shared: boolean;
  /** Units to buy for `chambers` chambers (the Pi side's share included). */
  units: number;
  /** Whole packs to buy for a pack-sold line — ceil(units / packSize), packs
   *  shared across chambers — else null. */
  packs: number | null;
  /** Units per pack when known, else null. */
  packSize: number | null;
  /** What the units are ("ft", "g", "chamber set"); "" = pieces. */
  unit: string;
  /** Builder lineTotal(): what this line costs for `chambers` chambers. */
  total: number;
}

export interface BomSection extends Omit<CategoryGroup, "items"> {
  lines: BomLine[];
}

/** The tier's BOM in the Builder's category order, each line sized and
 *  priced for `chambers` with the Builder's bomLine() — the same numbers the
 *  Builder's Shopping tab and the Pi's parts_cost(chambers) give. */
export function bomSections(tier: BuilderTier, chambers: number): BomSection[] {
  return groupByCategory(tier.components).map((g) => ({
    category: g.category,
    label: g.label,
    lines: g.items.map((c) => {
      const m = bomLine(c, chambers);
      return {
        id: hardwareItemId(c.name),
        component: c,
        shared: m.shared,
        units: m.units,
        packs: m.packs,
        packSize: m.packSize,
        unit: m.unit,
        total: m.total,
      };
    }),
  }));
}

/** Chamber count from free text: an integer 1–99 (the hand-off contract
 *  only requires ≥ 1; 99 keeps a typo from producing a 5-digit total). */
export function clampCount(value: number): number {
  if (!Number.isFinite(value)) return 1;
  return Math.min(99, Math.max(1, Math.floor(value)));
}

// ── Grow supplies ─────────────────────────────────────────────────────

/** One item of GET /api/species/{id}/shopping-list. */
export interface PiShoppingListItem {
  name: string;
  /** "substrate" | "spawn" | "containers" | "supplies" today. */
  category: string;
  /** Already formatted by the server ("6.6 lbs", "300 g", "2", "1 box"). */
  quantity: string;
  /** http(s) URLs and plain-text sourcing hints, mixed. */
  supplier_links: string[];
}

/** GET /api/species/{id}/shopping-list (species/shopping.py
 *  generate_shopping_list) — 404 when the species is unknown or has no
 *  substrate recipe. */
export interface PiShoppingList {
  species_id: string;
  common_name: string;
  recipe_name: string;
  grows: number;
  container_liters: number;
  items: PiShoppingListItem[];
}

export interface GrowPrefs {
  /** Species added with the picker (shown even without an active session). */
  added: string[];
  /** Grow-count overrides by species id. */
  grows: Record<string, number>;
}

export const EMPTY_GROW_PREFS: GrowPrefs = { added: [], grows: {} };

/** Stored prefs with every species id canonical (canonicalSpeciesId), so a
 *  species saved as `lions_mane` by an older build matches a `lions-mane`
 *  session. When both spellings carry a grow count, the first one wins. */
export function toGrowPrefs(value: unknown): GrowPrefs {
  if (!isRecord(value)) return EMPTY_GROW_PREFS;
  const added = Array.isArray(value.added)
    ? [
        ...new Set(
          value.added
            .filter((x): x is string => typeof x === "string" && x.length > 0)
            .map(canonicalSpeciesId),
        ),
      ]
    : [];
  const grows: Record<string, number> = {};
  if (isRecord(value.grows)) {
    for (const [k, v] of Object.entries(value.grows)) {
      const id = canonicalSpeciesId(k);
      if (typeof v === "number" && Number.isFinite(v) && !(id in grows)) grows[id] = clampCount(v);
    }
  }
  return { added, grows };
}

/** Active sessions per canonical species id, in the order the sessions list
 *  returns them (newest first). Non-active rows are ignored even if the
 *  server sent them. */
export function activeGrowCounts(sessions: readonly PiSession[]): Map<string, number> {
  const counts = new Map<string, number>();
  for (const s of sessions) {
    if (s.status !== "active" || !s.species_profile_id) continue;
    const id = canonicalSpeciesId(s.species_profile_id);
    counts.set(id, (counts.get(id) ?? 0) + 1);
  }
  return counts;
}

export interface GrowTarget {
  speciesId: string;
  /** Grows to shop for (override, else active sessions, else 1). */
  grows: number;
  /** Active sessions of this species (0 for a species added by hand). */
  activeSessions: number;
  /** Added with the picker — removable; session species are not. */
  added: boolean;
}

/** Session species first, then hand-added ones, each species once — by
 *  canonical id, so a `lions-mane` session and a `lions_mane` picked from
 *  /api/species are one target (2026-10 audit: they were listed twice). */
export function growTargets(counts: ReadonlyMap<string, number>, prefs: GrowPrefs): GrowTarget[] {
  const { added, grows } = toGrowPrefs(prefs);
  const active = new Map<string, number>();
  for (const [id, n] of counts) {
    const speciesId = canonicalSpeciesId(id);
    active.set(speciesId, (active.get(speciesId) ?? 0) + n);
  }
  const out: GrowTarget[] = [];
  for (const [speciesId, n] of active) {
    out.push({ speciesId, grows: grows[speciesId] ?? n, activeSessions: n, added: false });
  }
  for (const speciesId of added) {
    if (active.has(speciesId)) continue;
    out.push({ speciesId, grows: grows[speciesId] ?? 1, activeSessions: 0, added: true });
  }
  return out;
}

export type GrowListResult =
  | { status: "ok"; list: PiShoppingList }
  /** 404: unknown species or no substrate recipe on this Pi. */
  | { status: "no-data"; message: string }
  | { status: "error"; message: string };

/** One species' grow supplies from the Pi. Never rejects. */
export async function loadGrowList(speciesId: string, grows: number, get: Getter = apiGet): Promise<GrowListResult> {
  try {
    const list = await get<PiShoppingList>(
      `/api/species/${encodeURIComponent(speciesId)}/shopping-list?grows=${clampCount(grows)}`,
    );
    if (!list || !Array.isArray(list.items)) return { status: "error", message: "unexpected response" };
    return { status: "ok", list };
  } catch (err) {
    const message = err instanceof Error ? err.message : "fetch failed";
    return /^HTTP 404\b/.test(message) ? { status: "no-data", message } : { status: "error", message };
  }
}

export interface GrowContext {
  /** null = the sessions request failed (active grows unknown). */
  sessions: PiSession[] | null;
  /** null = the species request failed (no picker). */
  species: PiSpecies[] | null;
}

/** Active sessions + the species library. Never rejects. */
export async function loadGrowContext(get: Getter = apiGet): Promise<GrowContext> {
  const [sessions, species] = await Promise.all([
    get<PiSession[]>("/api/sessions?status=active").then(
      (rows) => (Array.isArray(rows) ? rows : null),
      () => null,
    ),
    get<PiSpecies[]>("/api/species").then(
      (rows) => (Array.isArray(rows) ? rows : null),
      () => null,
    ),
  ]);
  return { sessions, species };
}

// ── Grow supplies merged across species ───────────────────────────────
//
// Every species' list repeats the same consumables (the generator adds the
// recipe's vessel per grow — a filter-patch bag, jars, or a monotub + liner —
// a bottle of isopropyl, gloves, a spray bottle and often a pressure cooker
// to each), so two species listed them twice. The
// page lists each item once, with the species it serves:
//   • the same item (same category + name) in several lists → one row; the
//     quantities add up when they share a unit ("2" + "1" → "3", "300 g" +
//     "150 g" → "450 g"); a quantity that is not an amount of something —
//     a ratio ("3 parts"), a depth ("1 inch"), a share ("5% (~75 g)"), a
//     range, "as needed" — is shown once when every list says the same,
//     else each list's is joined with " + ";
//   • equipment one of which serves every grow (a pressure cooker, a spray
//     bottle) takes the largest count, not the sum;
//   • a culture is never merged: "Grain spawn" is a different culture for
//     every species, so each species keeps its own row — whatever category
//     the server files it under: its "spawn" category, and the inoculants
//     some recipes list as substrate ingredients ("grain spawn", "plug
//     spawn", "spawn", "spore slurry").

/** Supplies one of which serves every species on the list. */
const EQUIPMENT = /\b(?:pressure cooker|spray bottle)\b/i;

/** Categories whose items are per species however alike their names. */
const PER_SPECIES_CATEGORIES = new Set(["spawn"]);

/** A culture or inoculant by name: spawn of any kind, spores or a spore
 *  slurry, an inoculum, mycelium, a liquid or agar culture. */
const CULTURE_ITEM = /\b(?:spawn|spores?|slurry|inocul(?:um|ant)s?|mycelium|cultures?)\b/i;

/** True for an item each species needs its own of — a culture or
 *  inoculant, in any category — so it is never merged across species. */
export function isPerSpeciesItem(item: { category: string; name: string }): boolean {
  return PER_SPECIES_CATEGORIES.has(item.category) || CULTURE_ITEM.test(item.name);
}

/** Units that are not an amount to add up: ratios, depths, shares. */
const NOT_ADDITIVE_UNIT = /^(?:parts?|inch(?:es)?|in|cm|mm|%)$/i;

/** Count nouns written with an "s" when there is more than one. */
const PLURALS: Record<string, string> = {
  bottle: "bottles",
  box: "boxes",
  bag: "bags",
  block: "blocks",
  brick: "bricks",
  cup: "cups",
  jar: "jars",
  log: "logs",
  pack: "packs",
  plug: "plugs",
  quart: "quarts",
  roll: "rolls",
};

/** "boxes" / "Box" → "box", "lbs" → "lb": a unit's comparable form. */
function unitKey(unit: string): string {
  const u = unit.trim().toLowerCase();
  if (/xes$/.test(u)) return u.slice(0, -2);
  if (u.length > 1 && u.endsWith("s") && !u.endsWith("ss")) return u.slice(0, -1);
  return u;
}

const AMOUNT = /^(\d+(?:\.\d+)?)(?:\s*([A-Za-z][A-Za-z ]*?))?\s*$/;

/** "300 g" → { value: 300, unit: "g" }, "2" → { value: 2, unit: "" }; null
 *  for anything that is not a plain amount to add up. */
function parseAmount(q: string): { value: number; unit: string } | null {
  const m = AMOUNT.exec(q.trim());
  if (!m) return null;
  const unit = (m[2] ?? "").trim();
  if (NOT_ADDITIVE_UNIT.test(unit)) return null;
  return { value: Number(m[1]), unit };
}

const trimNumber = (n: number) => String(Math.round(n * 100) / 100);

/** Several lists' quantities for one item as one quantity (see above). */
export function mergeQuantities(quantities: readonly string[], mode: "sum" | "max" = "sum"): string {
  const qs = quantities.map((q) => q.trim()).filter(Boolean);
  if (qs.length === 0) return "";
  if (qs.length === 1) return qs[0]!;
  const amounts = qs.map(parseAmount);
  const units = new Set(amounts.map((a) => (a ? unitKey(a.unit) : null)));
  if (amounts.every((a) => a !== null) && units.size === 1) {
    const values = amounts.map((a) => a!.value);
    const total = mode === "max" ? Math.max(...values) : values.reduce((s, v) => s + v, 0);
    const unit = amounts[0]!.unit;
    const shown = total !== 1 && PLURALS[unitKey(unit)] && unitKey(unit) === unit.toLowerCase() ? PLURALS[unitKey(unit)]! : unit;
    return shown ? `${trimNumber(total)} ${shown}` : trimNumber(total);
  }
  if (new Set(qs).size === 1) return qs[0]!;
  return qs.join(" + ");
}

/** One row of the merged grow-supplies list. */
export interface GrowRow {
  /** sharedGrowItemId(name), or growItemId(species, name) for a per-species
   *  row (a culture — isPerSpeciesItem). */
  id: string;
  name: string;
  /** The server's category ("substrate", "spawn", …). */
  category: string;
  /** The merged quantity. */
  quantity: string;
  /** Every list's supplier links and hints, each once, in order. */
  supplierLinks: string[];
  /** The species it serves, in list order (one for a per-species row). */
  speciesIds: string[];
  /** One species' own row (a culture), never merged. */
  perSpecies: boolean;
  /** The per-species ids a merged row replaces, one per `speciesIds` entry,
   *  in the same order: notes under them fold into `id` (migrateGrowKeys),
   *  ticks under them count per species (growPurchase). [] for a
   *  per-species row. */
  legacyIds: string[];
  /** A per-species row outside the "spawn" category — a culture listed as a
   *  substrate ingredient — was one merged row before cultures were kept
   *  per species: that row's id (sharedGrowItemId), whose stored tick and
   *  note this row still reads until it has its own. Else null. */
  splitFrom: string | null;
}

export interface GrowRowGroup {
  category: string;
  label: string;
  rows: GrowRow[];
}

const categoryLabel = (c: string) => c.charAt(0).toUpperCase() + c.slice(1);

/** One spelling of a pound: the recipes write "5 lbs" and "1 lb", so a list
 *  read "2.6 lbs" beside "1.32 lb". "lb" is the abbreviation for both. */
export function tidyQuantity(q: string): string {
  return q.replace(/(\d)\s*lbs\b/gi, "$1 lb");
}

/** Every species' generated list as one list: grouped by the server's
 *  category (in the order the lists name them), each item once with the
 *  species it serves — a culture per species (isPerSpeciesItem). */
export function mergeGrowLists(lists: ReadonlyArray<{ speciesId: string; list: PiShoppingList }>): GrowRowGroup[] {
  type Acc = GrowRow & { quantities: string[] };
  const groups = new Map<string, Map<string, Acc>>();
  for (const { speciesId, list } of lists) {
    for (const it of list.items) {
      const category = it.category || "other";
      const perSpecies = isPerSpeciesItem({ category, name: it.name });
      const key = perSpecies ? `${speciesId}\u0000${it.name}` : it.name;
      const group = groups.get(category) ?? new Map<string, Acc>();
      groups.set(category, group);
      const row = group.get(key);
      if (row) {
        if (!row.speciesIds.includes(speciesId)) row.speciesIds.push(speciesId);
        row.quantities.push(it.quantity);
        for (const s of it.supplier_links ?? []) if (!row.supplierLinks.includes(s)) row.supplierLinks.push(s);
        continue;
      }
      group.set(key, {
        id: perSpecies ? growItemId(speciesId, it.name) : sharedGrowItemId(it.name),
        name: it.name,
        category,
        quantity: "",
        supplierLinks: [...new Set(it.supplier_links ?? [])],
        speciesIds: [speciesId],
        perSpecies,
        legacyIds: [],
        splitFrom: perSpecies && !PER_SPECIES_CATEGORIES.has(category) ? sharedGrowItemId(it.name) : null,
        quantities: [it.quantity],
      });
    }
  }
  return [...groups].map(([category, rows]) => ({
    category,
    label: categoryLabel(category),
    rows: [...rows.values()].map(({ quantities, ...row }) => ({
      ...row,
      quantity: tidyQuantity(mergeQuantities(quantities, EQUIPMENT.test(row.name) ? "max" : "sum")),
      legacyIds: row.perSpecies ? [] : row.speciesIds.map((s) => growItemId(s, row.name)),
    })),
  }));
}

// ── Bought / partly bought ────────────────────────────────────────────
//
// A merged row is bought when its own id is ticked. Before the lists were
// merged each species' supply was ticked on its own (grow:<species>:<item>);
// those ticks are kept as they are and read per species: the row counts as
// bought once every species it serves is ticked, and "partly bought" while
// only some are. Ticking or unticking the row itself decides for all of
// them (its own id, explicitly true or false, wins from then on). A
// per-species row that used to be one merged row (splitFrom) reads that
// row's tick until it has its own.

export type GrowPurchaseState = "bought" | "partial" | "none";

export interface GrowPurchase {
  state: GrowPurchaseState;
  /** The species a tick covers: all of `speciesIds` when bought, the ticked
   *  ones when partial, none otherwise. */
  boughtFor: string[];
}

type FlagRow = Pick<GrowRow, "id" | "speciesIds" | "legacyIds" | "splitFrom">;

/** How much of `row` is bought, from the stored flags. */
export function growPurchase(row: FlagRow, purchased: Readonly<Record<string, boolean>>): GrowPurchase {
  const bought: GrowPurchase = { state: "bought", boughtFor: [...row.speciesIds] };
  const none: GrowPurchase = { state: "none", boughtFor: [] };
  if (Object.hasOwn(purchased, row.id)) return purchased[row.id] ? bought : none;
  if (row.splitFrom && Object.hasOwn(purchased, row.splitFrom)) return purchased[row.splitFrom] ? bought : none;
  if (row.legacyIds.length === 0) return none;
  const boughtFor = row.speciesIds.filter((_, i) => purchased[row.legacyIds[i]!] === true);
  if (boughtFor.length === 0) return none;
  return boughtFor.length === row.speciesIds.length ? bought : { state: "partial", boughtFor };
}

/** `purchased` with each grow row's id set to whether the row is bought
 *  (growPurchase) — the map counts, filters, the CSV and the checkboxes read.
 *  Returns `purchased` itself when that changes nothing. */
export function effectiveGrowFlags(
  purchased: Record<string, boolean>,
  rows: readonly FlagRow[],
): Record<string, boolean> {
  let out = purchased;
  for (const row of rows) {
    const isBought = growPurchase(row, purchased).state === "bought";
    if (Boolean(purchased[row.id]) === isBought) continue;
    if (out === purchased) out = { ...purchased };
    out[row.id] = isBought;
  }
  return out;
}

/** The stored flags after the operator sets a grow row to `bought`: its own
 *  id says so explicitly, and the per-species ticks it decides for go. */
export function setGrowPurchased(
  purchased: Record<string, boolean>,
  row: Pick<GrowRow, "id" | "legacyIds">,
  bought: boolean,
): Record<string, boolean> {
  const out = { ...purchased, [row.id]: bought };
  for (const id of row.legacyIds) delete out[id];
  return out;
}

/** `notes` with each per-species row that used to be one merged row
 *  (splitFrom) showing that row's note until it has its own. Returns
 *  `notes` itself when that changes nothing. */
export function effectiveGrowNotes(
  notes: Record<string, string>,
  rows: ReadonlyArray<Pick<GrowRow, "id" | "splitFrom">>,
): Record<string, string> {
  let out = notes;
  for (const row of rows) {
    if (!row.splitFrom || Object.hasOwn(notes, row.id) || !Object.hasOwn(notes, row.splitFrom)) continue;
    if (out === notes) out = { ...notes };
    out[row.id] = notes[row.splitFrom]!;
  }
  return out;
}

// ── Search / status filter ────────────────────────────────────────────

export type StatusFilter = "all" | "unpurchased" | "purchased";

export function matchesFilter(
  id: string,
  haystack: ReadonlyArray<string | undefined>,
  filter: StatusFilter,
  query: string,
  purchased: Record<string, boolean>,
): boolean {
  const isP = Boolean(purchased[id]);
  if (filter === "unpurchased" && isP) return false;
  if (filter === "purchased" && !isP) return false;
  const q = query.trim().toLowerCase();
  if (!q) return true;
  return haystack.join(" ").toLowerCase().includes(q);
}

