// Styling: design-system primitives (Button, Input) and Tailwind tokens only.
// The panel used to lean on `.card` / `.btn-primary` / `.btn-secondary` /
// `.t-display`, which no stylesheet defines — the page rendered unstyled
// (no card, borderless inputs, buttons as plain text).
const CARD = "flex min-w-0 flex-col gap-4 rounded-md border border-border-soft bg-bg-1 p-4 sm:p-[22px]";
const META = "font-mono text-[13px] leading-[1.5] tracking-[0.03em] text-text-2 [overflow-wrap:anywhere]";
const FIELD_LABEL = "font-mono text-[12px] font-medium uppercase tracking-[0.14em] text-text-2";
const CHECKBOX = "h-[18px] w-[18px] shrink-0 cursor-pointer accent-accent";
const TEXTAREA =
  "min-h-[96px] w-full min-w-0 rounded-md border border-border bg-bg-1 px-2.5 py-2 font-mono text-[13px] leading-[1.5] text-text-0 placeholder:text-text-3 transition-colors duration-200 ease-brand hover:border-accent-line focus:border-accent-line";

// ────────────────────────────────────────────────────────────────────────
// Types — match the Pi server's GET /api/integrations response shape.
// ────────────────────────────────────────────────────────────────────────

export type IntegrationTier = "free" | "premium";
export type IntegrationState = "ok" | "degraded" | "disabled" | "error";

export interface IntegrationHealth {
  state: IntegrationState | null;
  last_error: string | null;
  last_checked_at: number | null;
}

export interface IntegrationDriverState {
  slug: string;
  tier_required: IntegrationTier;
  enabled: boolean;
  /** Config map. Secret fields are already redacted to ••••last4. */
  config: Record<string, unknown>;
  health: IntegrationHealth;
}

export interface IntegrationFieldDescriptor {
  name: string;
  label: string;
  type: "text" | "password" | "number" | "boolean" | "json" | "url";
  placeholder?: string;
  description?: string;
}

/** Per-vendor field schema. The Pi exposes a JSON schema from pydantic at
 *  GET /api/integrations/{slug}/config but rendering raw JSON Schema is a
 *  rabbit hole; for v4.1.0 we ship hand-curated schemas keyed by slug.
 *  Future: auto-generate from the Pi's response.
 */
export interface IntegrationVendorSchema {
  slug: string;
  label: string;
  blurb: string;
  fields: IntegrationFieldDescriptor[];
  /** v4.1.2 — list of writable actions surfaced as buttons-with-form. */
  actions?: VendorActionDescriptor[];
  /** Optional helper rendered above the form. */
  helper?: ReactNode;
}

/** Per-action input shape so the UI can render a focused control
 *  (e.g. percent slider for set_dim) instead of a generic JSON blob.
 */
export interface VendorActionDescriptor {
  name: string;
  label: string;
  fields: IntegrationFieldDescriptor[];
}

// ────────────────────────────────────────────────────────────────────────
// Status pill
// ────────────────────────────────────────────────────────────────────────

function stateTone(state: IntegrationState | null): "signal" | "accent" | "warn" | "err" | "idle" {
  switch (state) {
    case "ok":
      return "signal";
    case "degraded":
      return "warn";
    case "error":
      return "err";
    case "disabled":
    default:
      return "idle";
  }
}

function stateLabel(state: IntegrationState | null): string {
  switch (state) {
    case "ok":
      return "ok";
    case "degraded":
      return "degraded";
    case "error":
      return "error";
    case "disabled":
    default:
      return "disabled";
  }
}

export function IntegrationStatusPill({ state }: { state: IntegrationState | null }) {
  return (
    <Chip active tone={stateTone(state)}>
      {stateLabel(state)}
    </Chip>
  );
}

// ────────────────────────────────────────────────────────────────────────
// Single driver card
// ────────────────────────────────────────────────────────────────────────

export interface IntegrationCardCallbacks {
  onSave: (slug: string, enabled: boolean, config: Record<string, unknown>) => Promise<void>;
  onTest: (slug: string) => Promise<{ state: IntegrationState; last_error?: string | null } | null>;
  /** v4.1.2 — invoke a vendor write action. Returns the Pi's response
   *  body verbatim so the UI can show success/error feedback.
   */
  onAction?: (
    slug: string,
    action: string,
    payload: Record<string, unknown>,
  ) => Promise<unknown>;
}

interface IntegrationCardProps {
  driver: IntegrationDriverState;
  schema: IntegrationVendorSchema;
  /** When true, the card is read-only — used in the cloud-web mirror to
   *  surface state without offering a config form (Pi LAN UI is the
   *  primary surface). */
  readOnly?: boolean;
  callbacks?: IntegrationCardCallbacks;
}

export function IntegrationCard({
  driver,
  schema,
  readOnly = false,
  callbacks,
}: IntegrationCardProps) {
  const [enabled, setEnabled] = useState(driver.enabled);
  const [draft, setDraft] = useState<Record<string, unknown>>(() => ({ ...driver.config }));
  const [saving, setSaving] = useState(false);
  const [testing, setTesting] = useState(false);
  const [testResult, setTestResult] = useState<string | null>(null);
  const [saveError, setSaveError] = useState<string | null>(null);

  function setField(name: string, value: unknown) {
    setDraft((d) => ({ ...d, [name]: value }));
  }

  async function handleSave() {
    if (!callbacks) return;
    // Gate: a json field keeps its RAW text in `draft` while it is mid-edit or
    // unparseable (FieldInput only commits a parsed object on parse-success).
    // Forwarding that raw string to onSave would ship an unparseable STRING to
    // a field the Pi expects to be an object. Parse json fields here — blocking
    // the save with a surfaced error on any unparseable one, and normalizing
    // parseable strings back to objects so the Pi always receives an object.
    const outgoing: Record<string, unknown> = { ...draft };
    for (const field of schema.fields) {
      if (field.type !== "json") continue;
      const raw = draft[field.name];
      if (typeof raw !== "string") continue;
      try {
        outgoing[field.name] = JSON.parse(raw);
      } catch {
        setSaveError(`invalid JSON in "${field.label}"`);
        return;
      }
    }
    setSaving(true);
    setSaveError(null);
    try {
      await callbacks.onSave(driver.slug, enabled, outgoing);
    } catch (err) {
      setSaveError(err instanceof Error ? err.message : "save failed");
    } finally {
      setSaving(false);
    }
  }

  async function handleTest() {
    if (!callbacks) return;
    setTesting(true);
    setTestResult(null);
    try {
      const result = await callbacks.onTest(driver.slug);
      if (result == null) {
        setTestResult("test failed (no response)");
      } else if (result.state === "ok") {
        setTestResult("✓ connection ok");
      } else {
        setTestResult(`✗ ${result.state}${result.last_error ? `: ${result.last_error}` : ""}`);
      }
    } catch (err) {
      setTestResult(err instanceof Error ? `✗ ${err.message}` : "✗ test failed");
    } finally {
      setTesting(false);
    }
  }

  const tierTone = driver.tier_required === "premium" ? "accent" : "idle";

  return (
    <section className={CARD} aria-label={schema.label}>
      <header className="flex flex-wrap items-start justify-between gap-3">
        <div className="flex min-w-0 flex-[1_1_16rem] flex-col gap-1">
          <h3 className="m-0 font-body text-[18px] font-medium leading-[1.25] text-text-0 [overflow-wrap:anywhere]">
            {schema.label}
          </h3>
          <p className={cn(META, "m-0")}>{schema.blurb}</p>
        </div>
        <div className="flex flex-wrap items-center gap-2">
          <Chip active tone={tierTone}>
            {driver.tier_required}
          </Chip>
          <IntegrationStatusPill state={driver.health.state} />
        </div>
      </header>

      {driver.health.last_error && <p className={cn(META, "m-0 text-err")}>{driver.health.last_error}</p>}

      {schema.helper && <div className={META}>{schema.helper}</div>}

      {!readOnly && (
        <>
          {schema.fields.length > 0 && (
            <div className="grid grid-cols-[repeat(auto-fit,minmax(min(260px,100%),1fr))] gap-x-4 gap-y-3.5">
              {schema.fields.map((field) => (
                <FieldInput
                  key={field.name}
                  field={field}
                  value={draft[field.name]}
                  onChange={(v) => setField(field.name, v)}
                />
              ))}
            </div>
          )}

          <label className="flex cursor-pointer items-center gap-2.5 self-start font-body text-[15px] text-text-0">
            <input
              type="checkbox"
              className={CHECKBOX}
              checked={enabled}
              onChange={(e) => setEnabled(e.target.checked)}
            />
            <span>enabled</span>
          </label>

          <div className="flex flex-wrap items-center gap-2 border-t border-border-soft pt-4">
            <Button type="button" disabled={saving} onClick={handleSave}>
              {saving ? "saving…" : "save"}
            </Button>
            <Button type="button" variant="ghost" disabled={testing} onClick={handleTest}>
              {testing ? "testing…" : "test connection"}
            </Button>
            {testResult && <span className={META}>{testResult}</span>}
            {saveError && <span className={cn(META, "text-err")}>{saveError}</span>}
          </div>

          {schema.actions && schema.actions.length > 0 && callbacks?.onAction && (
            <VendorActionsBlock
              slug={driver.slug}
              actions={schema.actions}
              onAction={callbacks.onAction}
            />
          )}
        </>
      )}
    </section>
  );
}

function VendorActionsBlock({
  slug,
  actions,
  onAction,
}: {
  slug: string;
  actions: VendorActionDescriptor[];
  onAction: (slug: string, action: string, payload: Record<string, unknown>) => Promise<unknown>;
}) {
  return (
    <fieldset className="m-0 flex min-w-0 flex-col gap-4 rounded-md border border-border-soft p-4">
      <legend className={cn(FIELD_LABEL, "px-1.5")}>Vendor actions</legend>
      {actions.map((action) => (
        <VendorActionRow
          key={action.name}
          slug={slug}
          action={action}
          onAction={onAction}
        />
      ))}
    </fieldset>
  );
}

function VendorActionRow({
  slug,
  action,
  onAction,
}: {
  slug: string;
  action: VendorActionDescriptor;
  onAction: (slug: string, action: string, payload: Record<string, unknown>) => Promise<unknown>;
}) {
  const [draft, setDraft] = useState<Record<string, unknown>>({});
  const [busy, setBusy] = useState(false);
  const [result, setResult] = useState<string | null>(null);

  async function handleSubmit() {
    setBusy(true);
    setResult(null);
    try {
      const body = await onAction(slug, action.name, draft);
      setResult(`✓ ${action.name} ok${body ? ` — ${JSON.stringify(body).slice(0, 120)}` : ""}`);
    } catch (err) {
      setResult(`✗ ${err instanceof Error ? err.message : String(err)}`);
    } finally {
      setBusy(false);
    }
  }

  return (
    <div className="flex min-w-0 flex-col gap-2.5">
      <strong className="font-body text-[15px] font-medium text-text-0">{action.label}</strong>
      <div className="grid grid-cols-[repeat(auto-fit,minmax(min(200px,100%),1fr))] gap-x-4 gap-y-3">
        {action.fields.map((field) => (
          <FieldInput
            key={field.name}
            field={field}
            value={draft[field.name]}
            onChange={(v) => setDraft((d) => ({ ...d, [field.name]: v }))}
          />
        ))}
      </div>
      <div className="flex flex-wrap items-center gap-2">
        <Button type="button" variant="ghost" size="sm" disabled={busy} onClick={handleSubmit}>
          {busy ? "sending…" : `send ${action.name}`}
        </Button>
        {result && <span className={META}>{result}</span>}
      </div>
    </div>
  );
}

// ────────────────────────────────────────────────────────────────────────
// Field input
// ────────────────────────────────────────────────────────────────────────

function FieldInput({
  field,
  value,
  onChange,
}: {
  field: IntegrationFieldDescriptor;
  value: unknown;
  onChange: (v: unknown) => void;
}) {
  const descId = useId();
  const described = field.description ? descId : undefined;
  const description = field.description && (
    // JSON examples are one unbroken token — let them wrap anywhere.
    <span id={descId} className={cn(META, "text-[12px] text-text-3")}>
      {field.description}
    </span>
  );

  if (field.type === "boolean") {
    return (
      <div className="flex min-w-0 flex-col gap-1.5">
        <label className="flex cursor-pointer items-center gap-2.5 font-body text-[15px] text-text-0">
          <input
            type="checkbox"
            className={CHECKBOX}
            checked={Boolean(value)}
            aria-describedby={described}
            onChange={(e) => onChange(e.target.checked)}
          />
          <span className="[overflow-wrap:anywhere]">{field.label}</span>
        </label>
        {description}
      </div>
    );
  }

  return (
    <label className="flex min-w-0 flex-col gap-1.5">
      <span className={FIELD_LABEL}>{field.label}</span>
      {renderControl()}
      {description}
    </label>
  );

  function renderControl() {
    if (field.type === "number") {
      return (
        <Input
          type="number"
          value={typeof value === "number" ? value : ""}
          placeholder={field.placeholder}
          aria-describedby={described}
          onChange={(e) => onChange(e.target.value === "" ? "" : Number(e.target.value))}
        />
      );
    }
    if (field.type === "json") {
      const text = typeof value === "string" ? value : JSON.stringify(value ?? {}, null, 2);
      return (
        <textarea
          rows={4}
          className={TEXTAREA}
          value={text}
          placeholder={field.placeholder ?? "{}"}
          spellCheck={false}
          aria-describedby={described}
          onChange={(e) => {
            const raw = e.target.value;
            try {
              onChange(JSON.parse(raw));
            } catch {
              // Keep raw text in flight; commit on parse-success only.
              onChange(raw);
            }
          }}
        />
      );
    }
    return (
      <Input
        type={field.type === "password" ? "password" : field.type === "url" ? "url" : "text"}
        value={typeof value === "string" || typeof value === "number" ? String(value) : ""}
        placeholder={field.placeholder}
        aria-describedby={described}
        onChange={(e) => onChange(e.target.value)}
      />
    );
  }
}

