// Builder page data: the Pi's live /api/builder/* responses mapped onto the
// @sporeprint/design Builder types, the built-in fallback copy, and the pure
// BOM math (line cost, chamber multiplier, category grouping) the page shows.
// The BOM math is the server's own rule (builder/models.py
// Component.line_cost): a pack-sold line buys ceil(units / packSize) whole
// packs, so the Overview, the Shopping tab, the tier cards and the Shopping
// List page all price N chambers exactly as the Pi does.
//
// Source of truth is the Pi itself — its BOM, model files, wiring SVGs and
// firmware tree all ship in the same public-repo release, so what it serves
// matches the hardware it runs. The design package's generated copy
// (HARDWARE_TIERS / BUILDER_3D_MODELS / BUILDER_WIRING_DIAGRAMS, written by
// scripts/port_builder.py) and BUILDER_FIRMWARE are the per-resource fallback
// when a request fails.

import { useEffect, useState } from "react";
import {
  BUILDER_3D_MODELS,
  BUILDER_FIRMWARE,
  BUILDER_WIRING_DIAGRAMS,
  HARDWARE_TIERS,
  loadWiringSvgs,
  type WiringSvgs,
  type BuilderAlternate,
  type BuilderComponent,
  type BuilderComponentCategory,
  type BuilderFirmwareFile,
  type BuilderFirmwareNode,
  type BuilderModelFile,
  type BuilderTier,
  type BuilderWiring,
  type BuilderWiringDiagram,
} from "@sporeprint/design";
import { apiGet } from "./api";
import type {
  PiBuilderComponent,
  PiBuilderDiagram,
  PiBuilderModel,
  PiBuilderTier,
  PiBuilderTierSummary,
  PiBuilderWiring,
  PiFirmwareGroup,
} from "./pi-types";

/** The public repo on GitHub (docs/ diagram source links). */
export const PUBLIC_REPO_BLOB_URL = "https://github.com/59psi/SporePrint/blob/main";

const TIER_IDS: ReadonlyArray<BuilderTier["id"]> = ["bare_bones", "recommended", "all_the_things"];

function isTierId(id: string): id is BuilderTier["id"] {
  return (TIER_IDS as ReadonlyArray<string>).includes(id);
}

// ── Categories ────────────────────────────────────────────────────────

/** Shopping-list section order: the boards first, then what they drive,
 *  then power, cabling, mechanical hardware and the passives/misc bin. */
export const CATEGORY_ORDER: ReadonlyArray<BuilderComponentCategory> = [
  "controller",
  "sensor",
  "actuator",
  "plug",
  "power",
  "wiring",
  "hardware",
  "misc",
];

export const CATEGORY_LABELS: Record<BuilderComponentCategory, string> = {
  controller: "Controllers",
  sensor: "Sensors",
  actuator: "Actuators",
  plug: "Smart plugs",
  power: "Power",
  wiring: "Wiring & cabling",
  hardware: "Hardware & fasteners",
  misc: "Misc & passives",
};

/** A category this build doesn't know (a newer Pi) files under misc rather
 *  than dropping the part from the list. */
function toCategory(raw: string): BuilderComponentCategory {
  return (CATEGORY_ORDER as ReadonlyArray<string>).includes(raw) ? (raw as BuilderComponentCategory) : "misc";
}

export interface CategoryGroup {
  category: BuilderComponentCategory;
  label: string;
  items: BuilderComponent[];
}

/** Components grouped by category in CATEGORY_ORDER (empty groups omitted). */
export function groupByCategory(components: BuilderComponent[]): CategoryGroup[] {
  return CATEGORY_ORDER.map((category) => ({
    category,
    label: CATEGORY_LABELS[category],
    items: components.filter((c) => c.category === category),
  })).filter((g) => g.items.length > 0);
}

// ── snake_case → design types ─────────────────────────────────────────

const round1 = (n: number) => Math.round(n * 10) / 10;
const kb = (bytes: number) => round1(bytes / 1024);

export function mapComponent(c: PiBuilderComponent): BuilderComponent {
  const out: BuilderComponent = {
    name: c.name,
    role: c.role,
    quantity: c.quantity,
    priceApprox: c.price_approx,
    url: c.url,
    category: toCategory(c.category),
    notes: c.notes ?? "",
  };
  // The server sends pack_price "" and pack_size 0 for parts bought singly.
  if (c.pack_price) out.packPrice = c.pack_price;
  if (typeof c.pack_size === "number" && Number.isInteger(c.pack_size) && c.pack_size > 0) {
    out.packSize = c.pack_size;
  }
  // The Pi side's share of a per-chamber pack line; the server sends 0 for
  // none and an older Pi omits it.
  if (typeof c.shared_units === "number" && Number.isInteger(c.shared_units) && c.shared_units > 0) {
    out.sharedUnits = c.shared_units;
  }
  // What the counts count when not pieces ("ft", "g", "chamber set"); a Pi
  // older than the field sends none.
  if (typeof c.unit === "string" && c.unit.trim()) out.unit = c.unit.trim();
  // Absent on a Pi that predates the flag — isSharedComponent() decides then.
  if (typeof c.shared === "boolean") out.shared = c.shared;
  return out;
}

export function mapWiring(w: PiBuilderWiring): BuilderWiring {
  return {
    fromDevice: w.from_device,
    fromPin: w.from_pin,
    toDevice: w.to_device,
    toPin: w.to_pin,
    note: w.note ?? "",
  };
}

/** GET /api/builder/tiers/{id} → BuilderTier; null for an id this UI has no
 *  slot for (the tier union is the three reference builds). */
export function mapTier(t: PiBuilderTier): BuilderTier | null {
  if (!isTierId(t.id)) return null;
  const components = t.components.map(mapComponent);
  return {
    id: t.id,
    name: t.name,
    tagline: t.tagline,
    estimatedCost: t.estimated_cost,
    componentCount: components.reduce((n, c) => n + c.quantity, 0),
    bestFor: t.best_for ?? "",
    speciesSupport: t.species_support ?? "",
    whatYouGet: t.what_you_get ?? [],
    capabilityGroups: (t.capability_groups ?? []).map((g) => ({ title: g.title, items: g.items })),
    limitations: t.limitations ?? [],
    components,
    wiring: t.wiring.map(mapWiring),
    wiringDiagram: t.wiring_diagram || undefined,
    firmwareTargets: t.firmware_targets ?? [],
    setupSteps: t.setup_steps ?? [],
  };
}

export function mapModel(m: PiBuilderModel): BuilderModelFile {
  return {
    filename: m.filename,
    title: m.title || undefined,
    description: m.description ?? "",
    url: m.url || `/api/builder/models/${m.filename}`,
    sourceUrl: m.source_url || undefined,
    sizeKb: kb(m.size_bytes),
  };
}

/** docs/ filename prefix of each tier's wiring diagram (same map as the
 *  public repo's scripts/sync_ui_builder_data.py and port_builder.py). */
export const DIAGRAM_PREFIX: Record<BuilderTier["id"], string> = {
  bare_bones: "wiring-tier1-",
  recommended: "wiring-tier2-",
  all_the_things: "wiring-tier3-",
};

/** GET /api/builder/diagrams (every docs/*.svg) → one diagram per tier that
 *  has one; the architecture / overall-system SVGs are not tier diagrams. */
export function mapDiagrams(list: PiBuilderDiagram[]): BuilderWiringDiagram[] {
  const out: BuilderWiringDiagram[] = [];
  for (const tierId of TIER_IDS) {
    const prefix = DIAGRAM_PREFIX[tierId];
    const d = list
      .filter((x) => x.filename.startsWith(prefix) && x.filename.endsWith(".svg"))
      .sort((a, b) => a.filename.localeCompare(b.filename))[0];
    if (!d) continue;
    out.push({
      tierId,
      label: d.filename.slice(prefix.length, -".svg".length),
      filename: d.filename,
      url: d.url || `/api/builder/diagrams/${d.filename}`,
      sourceUrl: `${PUBLIC_REPO_BLOB_URL}/docs/${d.filename}`,
      sizeKb: kb(d.size_bytes),
    });
  }
  return out;
}

// ── Wiring SVGs (on demand) ───────────────────────────────────────────
//
// The embedded tier SVGs (~190 KB of text) are the design package's own
// lazy chunk (loadWiringSvgs → a dynamic import of builder.wiring.generated).
// Nothing in pi-ui may import BUILDER_WIRING_SVGS statically, or Vite folds
// the chunk back into the main bundle; the page reads the SVGs' sizes and
// titles through this hook instead.

let wiringSvgs: WiringSvgs | null = null;

/** Load the embedded tier SVGs once (a separate chunk) and keep them, so
 *  later renders read them synchronously. */
export function loadBuilderWiringSvgs(): Promise<WiringSvgs> {
  return loadWiringSvgs().then((m) => {
    wiringSvgs = m;
    return m;
  });
}

/** The embedded tier SVGs: at once when already loaded, else null until the
 *  chunk arrives (a failed load stays null — <WiringDiagram> says so). */
export function useWiringSvgs(): WiringSvgs | null {
  const [svgs, setSvgs] = useState<WiringSvgs | null>(wiringSvgs);
  useEffect(() => {
    if (svgs) return;
    let alive = true;
    loadBuilderWiringSvgs().then(
      (m) => {
        if (alive) setSvgs(m);
      },
      () => {
        // offline mid-upgrade: the diagram component shows its own message
      },
    );
    return () => {
      alive = false;
    };
  }, [svgs]);
  return svgs;
}

// ── Model descriptions ────────────────────────────────────────────────
//
// The Pi's model listing cuts each description at 240 characters
// (models_router.py _model_header): at a sentence end when one falls past
// character 80, otherwise mid-word with "…" (hx711_scale.scad: "… sits on
// the p…"). The whole paragraph is the .scad file's own header comment, so
// the Models tab reads it from the file on request.

/** True when the listing cut the description short. */
export function isCutDescription(text: string): boolean {
  return text.trimEnd().endsWith("…");
}

/** A cut description shortened to its last whole word, so it never ends
 *  mid-word: "… sits on the p…" → "… sits on the…". */
export function wholeWordDescription(text: string): string {
  const t = text.trimEnd();
  if (!t.endsWith("…")) return t;
  const body = t.slice(0, -1);
  const lastSpace = body.search(/\s+\S*$/);
  if (lastSpace <= 0) return t;
  return `${body.slice(0, lastSpace).replace(/[\s,;:(–—-]+$/, "")}…`;
}

/** The header paragraph of a model's source — the same rule as the server's
 *  _model_header (leading `//` lines; the first is the title; the paragraph
 *  ends at the first blank `//` or `// ──` line), without the length cap.
 *  null when the file has no such paragraph. */
export function parseModelDescription(source: string): string | null {
  const comments: string[] = [];
  for (const raw of source.split(/\r?\n/, 200)) {
    const s = raw.trim();
    if (!s.startsWith("//")) break;
    comments.push(s.slice(2).trim());
  }
  const lines: string[] = [];
  for (const text of comments.slice(1)) {
    if (!text || text.startsWith("─")) break;
    lines.push(text);
  }
  const description = lines.join(" ").split(/\s+/).filter(Boolean).join(" ");
  return description || null;
}

/** "https://github.com/o/r/blob/main/models/x.scad" → the raw file URL. */
export function rawGithubUrl(blobUrl: string | undefined): string | null {
  const m = /^https:\/\/github\.com\/([^/]+)\/([^/]+)\/blob\/(.+)$/.exec(blobUrl ?? "");
  return m ? `https://raw.githubusercontent.com/${m[1]}/${m[2]}/${m[3]}` : null;
}

type TextGetter = (url: string) => Promise<string>;

async function fetchText(url: string): Promise<string> {
  const res = await fetch(url, { credentials: url.startsWith("/") ? "same-origin" : "omit" });
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  return res.text();
}

/** A model's whole description, read from its .scad header: this Pi's own
 *  download first, then the file on GitHub. null when neither answers. */
export async function loadModelDescription(
  m: Pick<BuilderModelFile, "url" | "sourceUrl">,
  get: TextGetter = fetchText,
): Promise<string | null> {
  const urls = [m.url, rawGithubUrl(m.sourceUrl)].filter((u): u is string => Boolean(u));
  for (const url of urls) {
    try {
      const description = parseModelDescription(await get(url));
      if (description) return description;
    } catch {
      // try the next copy
    }
  }
  return null;
}

/** The tier's `wiring_diagram` text without its leading "See docs/<file>.svg:"
 *  pointer — on this page the diagram is right above the caption. */
export function diagramCaption(text: string | undefined): string {
  const body = (text ?? "").replace(/^\s*See\s+docs\/[^\s:]+\.svg\s*:?\s*/i, "").trim();
  return body ? body.charAt(0).toUpperCase() + body.slice(1) : "";
}

export interface BuilderFirmwareLive {
  nodes: BuilderFirmwareNode[];
  /** The whole firmware tree as one ZIP (the listing's synthetic "full" group). */
  fullBundleUrl: string | null;
}

/** Overlay GET /api/builder/firmware onto the built-in image list: each
 *  BUILDER_FIRMWARE entry whose `path` (src/node, src/cam) the Pi lists takes
 *  the Pi's bundle URL and file list (sizes + Pi download URLs). The image
 *  descriptions and PlatformIO envs stay from the built-in copy — the listing
 *  carries neither. null when the Pi lists none of the images. */
export function mergeFirmware(
  groups: PiFirmwareGroup[],
  base: BuilderFirmwareNode[] = BUILDER_FIRMWARE,
): BuilderFirmwareLive | null {
  let matched = 0;
  const nodes = base.map((n) => {
    const g = n.path ? groups.find((x) => x.path === n.path) : undefined;
    if (!g) return n;
    matched += 1;
    const prefix = `${g.path}/`;
    const files: BuilderFirmwareFile[] = g.files.map((f) => ({
      filename: f.filename.startsWith(prefix) ? f.filename.slice(prefix.length) : f.filename,
      url: f.url,
      sizeKb: kb(f.size_bytes),
    }));
    return { ...n, bundleUrl: g.bundle_url || n.bundleUrl, files };
  });
  if (matched === 0) return null;
  return { nodes, fullBundleUrl: groups.find((g) => g.node === "full")?.bundle_url || null };
}

/** The board each PlatformIO env is for (public repo firmware/platformio.ini,
 *  v2 firmware). An env this build doesn't know shows its command only. */
export const FIRMWARE_ENV_BOARDS: Record<string, string> = {
  node_esp32: "ESP32-WROOM-32 DevKit (the reference board)",
  node_esp32s3: "ESP32-S3-DevKitC-1 with quad flash — N8 / N8R8 / N16R8",
  node_esp32s3_n32r16v: "ESP32-S3-DevKitC-1-N32R16V (octal flash; node_esp32s3 does not boot on it)",
  cam: "AI-Thinker ESP32-CAM on its ESP32-CAM-MB programmer — OV2640 / OV3660 / OV5640 auto-detected",
  cam_esp32s3: "Freenove ESP32-S3-WROOM CAM (an earlier BOM's camera; no flash LED)",
  cam_xiao_esp32s3: "Seeed XIAO ESP32S3 Sense (an earlier BOM's camera; no flash LED)",
  cam_waveshare_s3: "Waveshare ESP32-S3-CAM-OV5640 / -OV3660 (an earlier BOM's camera; no flash LED)",
};

/** The flash command for one env, run from the firmware/ directory (the
 *  same line the Pi's bundle README prints). */
export function firmwareFlashCommand(env: string): string {
  return `pio run -t upload -e ${env}`;
}

export interface FirmwareImage {
  /** Image source dir (e.g. "src/node"), or the bundle URL for an entry without one. */
  key: string;
  path: string | undefined;
  envs: string[];
  bundleUrl: string;
  sourceUrl: string | undefined;
  files: BuilderFirmwareFile[];
  /** climate / relay / lighting all flash the ONE node image. */
  personalities: BuilderFirmwareNode[];
  /** True when one of the image's envs is a firmware target of the tier. */
  included: boolean;
}

/** One card per firmware image (entries sharing a `path` merge), matched
 *  against a tier's firmwareTargets by PlatformIO env. */
export function firmwareImages(nodes: BuilderFirmwareNode[], firmwareTargets: string[]): FirmwareImage[] {
  const targets = new Set(firmwareTargets);
  const byKey = new Map<string, FirmwareImage>();
  for (const n of nodes) {
    const key = n.path ?? n.bundleUrl;
    const envs = n.envs && n.envs.length > 0 ? n.envs : [n.node];
    const existing = byKey.get(key);
    if (existing) {
      existing.personalities.push(n);
      for (const e of envs) if (!existing.envs.includes(e)) existing.envs.push(e);
      existing.included = existing.envs.some((e) => targets.has(e));
      continue;
    }
    byKey.set(key, {
      key,
      path: n.path,
      envs: [...envs],
      bundleUrl: n.bundleUrl,
      sourceUrl: n.sourceUrl,
      files: n.files,
      personalities: [n],
      included: envs.some((e) => targets.has(e)),
    });
  }
  return [...byKey.values()];
}

// ── Pricing ───────────────────────────────────────────────────────────

const USD_RE = /^\s*~?\s*\$\s*(\d[\d,]*(?:\.\d+)?)\s*$/;

/** "$1,234.56" → 1234.56; null for anything that is not a plain price. */
export function parseUsd(price: string | undefined): number | null {
  const m = USD_RE.exec(price ?? "");
  return m ? Number(m[1]!.replace(/,/g, "")) : null;
}

/** Names the pre-`shared`-flag page hard-coded as shared. Consulted ONLY for
 *  a component that carries no `shared` flag (a Pi older than the 2026-09
 *  BOM audit); the current BOM flags every line. */
const LEGACY_SHARED_NAMES = new Set(["Raspberry Pi 5 (4GB)", "12V 5A Power Supply"]);

/** One per installation (the Pi side, spools, fastener kits, consumables) —
 *  not multiplied by the chamber count. */
export function isSharedComponent(c: BuilderComponent): boolean {
  return typeof c.shared === "boolean" ? c.shared : LEGACY_SHARED_NAMES.has(c.name);
}

/** Units in one pack of a pack-sold line; null when the line is bought singly,
 *  or when a Pi that predates `pack_size` sent a pack price without one. */
export function packSizeOf(c: BuilderComponent): number | null {
  if (!c.packPrice) return null;
  const n = c.packSize;
  return typeof n === "number" && Number.isInteger(n) && n > 0 ? n : null;
}

/** Units of a per-chamber line that the Pi side takes from the same packs,
 *  bought once (0 when none, and always 0 on a shared line). */
export function sharedUnitsOf(c: BuilderComponent): number {
  if (isSharedComponent(c)) return 0;
  const n = c.sharedUnits;
  return typeof n === "number" && Number.isInteger(n) && n > 0 ? n : 0;
}

/** Units to buy for `chambers` chambers — the server's Component.units(N): a
 *  shared line once; everything else `quantity` (units per chamber) ×
 *  chambers, plus the Pi side's `sharedUnits` once. */
export function lineQuantity(c: BuilderComponent, chambers: number): number {
  return isSharedComponent(c) ? c.quantity : c.quantity * chambers + sharedUnitsOf(c);
}

/** Packs to buy for `chambers` chambers; null for a line bought singly.
 *  With a pack size: ceil(units / packSize) — one 100-pack of resistors
 *  covers every chamber that needs ≤ 100. A legacy pack line (packPrice, no
 *  packSize) keeps the old rule: one pack per chamber, once if shared. */
export function linePacks(c: BuilderComponent, chambers: number): number | null {
  if (!c.packPrice) return null;
  const size = packSizeOf(c);
  if (size !== null) return Math.ceil(lineQuantity(c, chambers) / size);
  return isSharedComponent(c) ? 1 : chambers;
}

/** What the line costs for `chambers` chambers — the server's
 *  Component.line_cost(chambers): whole packs × packPrice for a pack-sold
 *  line, otherwise unit price × units. */
export function lineTotal(c: BuilderComponent, chambers: number): number {
  const packs = linePacks(c, chambers);
  if (packs !== null) return (parseUsd(c.packPrice) ?? 0) * packs;
  return (parseUsd(c.priceApprox) ?? 0) * lineQuantity(c, chambers);
}

/** What the line costs for one chamber (Component.line_cost()). */
export function lineCost(c: BuilderComponent): number {
  return lineTotal(c, 1);
}

/** One BOM line sized and priced for `chambers` chambers. */
export interface BomLineMath {
  shared: boolean;
  /** Units to buy. */
  units: number;
  /** Whole packs to buy for a pack-sold line, else null. */
  packs: number | null;
  /** Units per pack when known, else null (single part or legacy pack line). */
  packSize: number | null;
  /** What the units are ("ft", "g", "chamber set"); "" = pieces of the part. */
  unit: string;
  /** What the line costs. */
  total: number;
}

/** The one line helper the Overview, Shopping tab, tier cards and the
 *  Shopping List page share. */
export function bomLine(c: BuilderComponent, chambers: number): BomLineMath {
  return {
    shared: isSharedComponent(c),
    units: lineQuantity(c, chambers),
    packs: linePacks(c, chambers),
    packSize: packSizeOf(c),
    unit: c.unit ?? "",
    total: lineTotal(c, chambers),
  };
}

// How a line is WORDED ("4 · 2 packs of 2") is lib/bom-labels.ts, the one
// helper every view and the CSV use.

export interface BomCounts {
  /** Distinct BOM lines (what "parts" means on the Overview). */
  lines: number;
  /** Units to buy for the chamber count (packs counted by their units) —
   *  feet of wire, grams of solder and pieces alike, so not a figure to show. */
  units: number;
  /** What goes in the cart for the chamber count: whole packs for a
   *  pack-sold line, parts for the rest. */
  toBuy: number;
}

/** The Overview's component KPI: distinct lines, and what to buy for
 *  `chambers` (2026-10 audit: "3429 units" added feet, grams and pieces). */
export function bomCounts(components: BuilderComponent[], chambers: number): BomCounts {
  return {
    lines: components.length,
    units: components.reduce((n, c) => n + lineQuantity(c, chambers), 0),
    toBuy: components.reduce((n, c) => n + (linePacks(c, chambers) ?? lineQuantity(c, chambers)), 0),
  };
}

export interface BomTotals {
  /** Σ shared lines (bought once). */
  shared: number;
  /** Σ per-chamber lines for all `chambers` chambers (whole packs). */
  chambered: number;
  /** chambered ÷ chambers — the average per chamber, so
   *  shared + perChamber × chambers = total. Falls as packs are shared out. */
  perChamber: number;
  /** Σ per-chamber lines for ONE chamber (a chamber bought on its own). */
  oneChamber: number;
  /** oneChamber × chambers − chambered: what sharing packs across chambers
   *  saves (0 for one chamber). */
  packSavings: number;
  /** Every line for `chambers` chambers — HardwareTier.parts_cost(chambers). */
  total: number;
  /** Per-chamber pack lines with no pack size (a Pi older than pack_size):
   *  for those, one pack per chamber is an upper bound. 0 on a current Pi. */
  packLinesPerChamber: number;
}

export function bomTotals(components: BuilderComponent[], chambers: number): BomTotals {
  let shared = 0;
  let chambered = 0;
  let oneChamber = 0;
  let total = 0;
  let packLinesPerChamber = 0;
  for (const c of components) {
    // Summed over every line in BOM order, as parts_cost() sums: `total`
    // matches the server's figure to the cent.
    const t = lineTotal(c, chambers);
    total += t;
    if (isSharedComponent(c)) {
      shared += t;
    } else {
      chambered += t;
      oneChamber += lineTotal(c, 1);
      if (c.packPrice && packSizeOf(c) === null) packLinesPerChamber += 1;
    }
  }
  const packSavings = Math.max(0, Math.round((oneChamber * chambers - chambered) * 100) / 100);
  return {
    shared,
    chambered,
    perChamber: chambers > 0 ? chambered / chambers : chambered,
    oneChamber,
    packSavings,
    total,
    packLinesPerChamber,
  };
}

/** "$27", "$1.90", "$1,234" — cents only when there are any. */
export function formatUsd(n: number): string {
  const cents = Math.round(n * 100);
  const whole = cents % 100 === 0;
  return `$${(cents / 100).toLocaleString("en-US", {
    minimumFractionDigits: whole ? 0 : 2,
    maximumFractionDigits: whole ? 0 : 2,
  })}`;
}

/** Whole dollars, for a figure shown beside the whole-dollar totals: "$375"
 *  when it is whole, else rounded with a "~" ("~$373" for $372.83) — so the
 *  caption under a "$1,866" total does not read "$372.83 per chamber". */
export function approxUsd(n: number): string {
  const whole = Math.round(n * 100) % 100 === 0;
  return whole ? formatUsd(n) : `~${formatUsd(Math.round(n))}`;
}

/** Alternates for parts this tier actually lists — never for a part it
 *  doesn't (BUILDER_ALTERNATES is empty today: the audited BOM keeps every
 *  substitute in the part's own notes). */
export function relevantAlternates(alternates: BuilderAlternate[], components: BuilderComponent[]): BuilderAlternate[] {
  const names = new Set(components.map((c) => c.name));
  return alternates.filter((a) => names.has(a.forComponent));
}

// ── Loading + fallback ────────────────────────────────────────────────

export type BuilderResource = "tiers" | "models" | "diagrams" | "firmware";

/** What the Pi answered, per resource; null = request failed (or held
 *  nothing usable) → that resource falls back to the built-in copy. */
export interface BuilderLive {
  tiers: BuilderTier[] | null;
  models: BuilderModelFile[] | null;
  diagrams: BuilderWiringDiagram[] | null;
  firmware: BuilderFirmwareLive | null;
}

type Getter = <T>(path: string) => Promise<T>;

async function orNull<T>(load: () => Promise<T | null>): Promise<T | null> {
  try {
    return await load();
  } catch {
    return null;
  }
}

const nonEmpty = <T>(xs: T[]): T[] | null => (xs.length > 0 ? xs : null);

/** Fetch every Builder resource from the Pi. Never rejects: each resource
 *  resolves independently to its mapped data or null. The tier BOM is all or
 *  nothing (summary list, then every tier's detail) so the picker never mixes
 *  a live tier with a built-in one. */
export async function loadBuilderLive(get: Getter = apiGet): Promise<BuilderLive> {
  const [tiers, models, diagrams, firmware] = await Promise.all([
    orNull(async () => {
      const summary = await get<PiBuilderTierSummary[]>("/api/builder/tiers");
      const ids = summary.map((s) => s.id).filter(isTierId);
      const details = await Promise.all(
        ids.map((id) => get<PiBuilderTier>(`/api/builder/tiers/${encodeURIComponent(id)}`)),
      );
      return nonEmpty(details.map(mapTier).filter((t): t is BuilderTier => t !== null));
    }),
    orNull(async () => nonEmpty((await get<PiBuilderModel[]>("/api/builder/models")).map(mapModel))),
    orNull(async () => nonEmpty(mapDiagrams(await get<PiBuilderDiagram[]>("/api/builder/diagrams")))),
    orNull(async () => mergeFirmware(await get<PiFirmwareGroup[]>("/api/builder/firmware"))),
  ]);
  return { tiers, models, diagrams, firmware };
}

export interface ResolvedBuilderData {
  tiers: BuilderTier[];
  models: BuilderModelFile[];
  diagrams: BuilderWiringDiagram[];
  firmware: BuilderFirmwareNode[];
  fullFirmwareBundleUrl: string | null;
  live: Record<BuilderResource, boolean>;
}

/** Live data where the Pi answered, the built-in copy everywhere else
 *  (`live` null = still loading → everything built-in). */
export function resolveBuilderData(live: BuilderLive | null): ResolvedBuilderData {
  return {
    tiers: live?.tiers ?? HARDWARE_TIERS,
    models: live?.models ?? BUILDER_3D_MODELS,
    diagrams: live?.diagrams ?? BUILDER_WIRING_DIAGRAMS,
    firmware: live?.firmware?.nodes ?? BUILDER_FIRMWARE,
    fullFirmwareBundleUrl: live?.firmware?.fullBundleUrl ?? null,
    live: {
      tiers: Boolean(live?.tiers),
      models: Boolean(live?.models),
      diagrams: Boolean(live?.diagrams),
      firmware: Boolean(live?.firmware),
    },
  };
}

const RESOURCE_LABELS: Record<BuilderResource, string> = {
  tiers: "BOM",
  models: "models",
  diagrams: "diagrams",
  firmware: "firmware",
};

export interface BuilderSourceState {
  tone: "idle" | "accent" | "warn";
  label: string;
  detail: string;
}

/** The page's data-source indicator. */
export function builderSourceState(loading: boolean, live: Record<BuilderResource, boolean>): BuilderSourceState {
  if (loading) {
    return {
      tone: "idle",
      label: "checking this Pi…",
      detail: "showing the built-in copy until the Pi answers",
    };
  }
  const resources = Object.keys(RESOURCE_LABELS) as BuilderResource[];
  const missing = resources.filter((r) => !live[r]);
  if (missing.length === 0) {
    return {
      tone: "accent",
      label: "live from this Pi",
      detail: "BOM, models, wiring diagrams and firmware as served by this Pi",
    };
  }
  if (missing.length === resources.length) {
    return {
      tone: "warn",
      label: "built-in copy — Pi API unreachable",
      detail: "generated from the public repo when this UI was built; may differ from this Pi's release",
    };
  }
  return {
    tone: "warn",
    label: `partly live — built-in copy for ${missing.map((r) => RESOURCE_LABELS[r]).join(", ")}`,
    detail: "the Pi did not answer for those; everything else is live",
  };
}

/** The firmware toolchain, as the public README's Prerequisites state it.
 *  The firmware builds on the pinned pioarduino platform (Arduino-ESP32 core
 *  3.x); an older PlatformIO Core cannot install it. The public repo's
 *  test_docs_consistency pins the core version to platformio.ini, and
 *  builder-page.test pins these to the generated Builder setup step. */
export const FIRMWARE_TOOLCHAIN = {
  platformioMin: "6.2.0",
  installCommand: "pip install -U platformio",
  arduinoCore: "3.3.12",
  firstBuildDownload: "about 1 GB",
} as const;
