"use client";

import { cn } from "../lib/cn";

export type TimeRange = "LIVE" | "1H" | "4H" | "24H" | "7D" | "30D";

const ALL: TimeRange[] = ["LIVE", "1H", "4H", "24H", "7D", "30D"];

// Two renders, one contract:
//   • controlled (onChange given) → an interactive tablist. Same plain
//     anchor-based markup as SegmentedControl (`.v-time-ranges a` /
//     `.v-time-ranges a.active`), which pre-existing suites assert on directly.
//   • uncontrolled (no onChange) → a STATIC window indicator, not a tablist.
//     A picker with no handler was rendering as clickable tabs that did nothing
//     — reading as "nav that doesn't nav". Display-only markup makes it honest.
//     Pass onChange to get the real picker.
export function RangeSelector({
  value,
  onChange,
  /** Pi UI only exposes short-range windows — long history lives on cloud. */
  options = ALL,
}: {
  value: TimeRange;
  onChange?: (next: TimeRange) => void;
  options?: TimeRange[];
}) {
  if (!onChange) {
    return (
      <span className="v-time-range-static" aria-label={`showing ${value} window`}>
        <span className="win-label">window</span>
        {value}
      </span>
    );
  }

  return (
    <div className={cn("v-time-ranges")} role="tablist" aria-label="time range">
      {options.map((r) => {
        const active = r === value;
        return (
          <a
            key={r}
            href={`#${r.toLowerCase()}`}
            className={cn(
              active && "active",
              "transition-colors duration-200 ease-brand",
            )}
            role="tab"
            aria-selected={active}
            onClick={(e) => {
              e.preventDefault();
              onChange(r);
            }}
          >
            {r}
          </a>
        );
      })}
    </div>
  );
}
