import type { ReactNode } from "react";
import { cn } from "../lib/cn";

export type StatusPillTone = "signal" | "accent" | "warn" | "err" | "idle" | "default";

/** A danger / severity level as the Pi API spells it (e.g. the contamination
 *  library's `danger_level`), most severe first. "moderate" is accepted as a
 *  synonym of "medium". */
export type SeverityLevel = "critical" | "high" | "medium" | "moderate" | "low";

/**
 * Severity → pill tone, one ladder for every page: critical is red (`err`),
 * high is amber (`warn`), medium / moderate / low are the calm neutral pill.
 * Never `signal` (teal) — that tone means healthy / OK, which no contaminant
 * is — and never `idle`, whose text-3 grey is under 3:1 on the pill.
 */
export const SEVERITY_TONE: Record<SeverityLevel, StatusPillTone> = {
  critical: "err",
  high: "warn",
  medium: "default",
  moderate: "default",
  low: "default",
};

/** Sort rank, most severe first. */
export const SEVERITY_RANK: Record<SeverityLevel, number> = {
  critical: 0,
  high: 1,
  medium: 2,
  moderate: 2,
  low: 3,
};

function asSeverity(level: string | null | undefined): SeverityLevel | null {
  const key = (level ?? "").trim().toLowerCase();
  return Object.prototype.hasOwnProperty.call(SEVERITY_TONE, key) ? (key as SeverityLevel) : null;
}

/** The pill tone for a severity string from an API (case-insensitive). An
 *  unknown or missing level gets the neutral pill. */
export function severityTone(level: string | null | undefined): StatusPillTone {
  const key = asSeverity(level);
  return key ? SEVERITY_TONE[key] : "default";
}

/** Sort rank for a severity string: 0 is the most severe; unknown sorts last. */
export function severityRank(level: string | null | undefined): number {
  const key = asSeverity(level);
  return key ? SEVERITY_RANK[key] : Number.MAX_SAFE_INTEGER;
}

/**
 * Non-interactive status pill — the read-only sibling of `Chip`.
 *
 * Renders the `.status-pill` classes from components.css (the same engine
 * Chip uses), so it is byte-for-byte identical to the resolved-utility
 * `STATUS_PILL_BASE`/`STATUS_PILL_TONE` trio the pi-ui pages used to carry
 * per-file. `default` keeps the base border/text (the pages' unstyled case).
 */
export function StatusPill({
  tone = "default",
  className,
  children,
}: {
  tone?: StatusPillTone;
  className?: string;
  children: ReactNode;
}) {
  return (
    <span className={cn("status-pill", tone !== "default" && tone, className)}>
      {children}
    </span>
  );
}
