import type { BuilderComponent } from "@sporeprint/design";
import { amountText, isMeasure, packParts, perUnitText, unitWord, type PackFigures } from "../lib/bom-labels";

/** "of 100 ft" never splits ("ft" alone on a line); "of 3" + "chamber sets"
 *  may wrap between the count and a noun's words. */
function OfSize({ size, unit }: { size: number; unit: string | undefined }) {
  const word = unitWord(size, unit);
  if (word && isMeasure(unit)) return <span className="whitespace-nowrap">of {size} {word}</span>;
  return (
    <>
      <span className="whitespace-nowrap">of {size}</span>
      {word && ` ${word}`}
    </>
  );
}

/**
 * A BOM line's ~Price cell on both pages: "$5.49 / pack of 100" (wrapping
 * only before "of", and between the words of a unit: "of 100 ft") over
 * "~$0.05 ea" — or "~$0.26 / ft" for a line counted in something other than
 * pieces (Component.unit) — for a pack-sold line, else the unit price; lib/
 * bom-labels priceText() in the CSV.
 */
export function BomPrice({
  component: c,
  packSize,
  testId,
}: {
  component: BuilderComponent;
  packSize: number | null;
  testId?: string;
}) {
  if (!c.packPrice) return <span className="whitespace-nowrap font-mono text-text-0">{c.priceApprox}</span>;
  return (
    <>
      <span className="font-mono text-text-0" data-testid={testId}>
        <span className="whitespace-nowrap">{c.packPrice} / pack</span>
        {packSize !== null && (
          <>
            {" "}
            <OfSize size={packSize} unit={c.unit} />
          </>
        )}
      </span>
      <div className="mt-0.5 font-mono text-[12px] text-text-3" data-testid={testId ? `${testId}-each` : undefined}>
        {perUnitText(c)}
      </div>
    </>
  );
}

/**
 * The line under a BOM quantity — "1 pack of 100 · 76 spare", "5 packs of
 * 100 ft · 80 ft spare" — for the Builder's Shopping tab and the Shopping
 * List. It wraps only between its pieces ("5 packs" / "of 100" / the unit's
 * words / "· 80 ft spare"), so a narrow Qty column never shows "1 pack of /
 * 100 · 76 / spare". Nothing for a part bought singly.
 */
export function PackNote({ figures, testId }: { figures: PackFigures; testId?: string }) {
  const parts = packParts(figures);
  if (!parts) return null;
  const size = parts.size !== null && figures.packSize !== null ? figures.packSize : null;
  return (
    <div className="mt-0.5 font-mono text-[12px] text-text-3" data-testid={testId}>
      <span className="whitespace-nowrap">{parts.count}</span>
      {size !== null && (
        <>
          {" "}
          <OfSize size={size} unit={figures.unit} />
        </>
      )}
      {parts.spare && (
        <>
          {" "}
          <span className="whitespace-nowrap">· {parts.spare}</span>
        </>
      )}
    </div>
  );
}

/**
 * A BOM line's Qty cell, the same on the Builder's Shopping tab and the
 * Shopping List: the amount ("×4", or "420 ft" / "24 straps" for a line that
 * counts something other than pieces), "(shared)" for a line bought once
 * per installation, then the pack line — the words of lib/bom-labels
 * quantityText(), which the CSV writes as "×4 · 2 packs of 2".
 */
export function BomQty({
  figures,
  shared,
  qtyTestId,
  packsTestId,
}: {
  figures: PackFigures;
  shared: boolean;
  qtyTestId?: string;
  packsTestId?: string;
}) {
  return (
    <>
      <span className="font-mono text-text-0" data-testid={qtyTestId}>
        {amountText(figures.units, figures.unit)}
      </span>
      {shared && <div className="mt-0.5 font-mono text-[12px] text-text-3">(shared)</div>}
      <PackNote figures={figures} testId={packsTestId} />
    </>
  );
}
