"use client";
import { useMemo, useState, type ReactNode } from "react";
import {
  flexRender,
  getCoreRowModel,
  getSortedRowModel,
  useReactTable,
  type ColumnDef,
  type SortingState,
} from "@tanstack/react-table";
import { ChevronDown, ChevronUp } from "lucide-react";
import { cn } from "../lib/cn";

export interface Column<R> {
  key: string;
  header: string;
  align?: "left" | "right";
  render: (row: R) => ReactNode;
  /** Provide to make the column sortable. */
  sortValue?: (row: R) => string | number;
  /** A fixed width (any CSS length, e.g. "96px"). When a column sets one the
   *  table renders a `<colgroup>` and lays out with `table-layout: fixed`:
   *  each sized column keeps exactly that width — in every table built from
   *  the same columns, so a page of per-category tables lines up — and the
   *  columns without one share the rest. */
  width?: string;
  /** Hide the column while the table's own box is narrow (a container
   *  query on its `.data-table-host` wrapper, which DataTable adds whenever
   *  a column sets this): "optional" under 900px, "low" under 720px,
   *  "medium" under 560px (where cell padding also tightens). For data a
   *  reader can reach another way — e.g. it is repeated in the selected
   *  row's side panel. Unset: always shown. */
  priority?: "optional" | "low" | "medium";
  /** "end": keep the column in view at the table's right edge while the
   *  rest scrolls sideways (position: sticky inside the page's scroller) —
   *  for a row's primary action, e.g. an export or "open" link. */
  sticky?: "end";
  /** Leave the column off a printed page (components.css, `@media print`):
   *  for what means nothing on paper — a "buy →" link, a row action — so
   *  the columns that remain share the sheet's width. */
  hideInPrint?: boolean;
}

export function DataTable<R extends { id?: string | number }>({
  columns,
  rows,
  caption,
  rowKey,
  onRowClick,
  empty,
  stickyHeader = false,
  initialSort,
  stackOnPhone = false,
  stackWhenNarrow = false,
}: {
  columns: Column<R>[];
  rows: R[];
  caption?: string;
  rowKey?: (row: R) => string | number;
  onRowClick?: (row: R) => void;
  empty?: ReactNode;
  stickyHeader?: boolean;
  initialSort?: { key: string; desc?: boolean };
  /** Under 640px, lay each row out as a card — one "header: value" line per
   *  cell — instead of a table wider than the phone (components.css
   *  `.data-table.stack-phone`). Explicit table roles keep the semantics a
   *  browser drops from a `display: block` table. */
  stackOnPhone?: boolean;
  /** The same card layout whenever the table's own box is under 900px wide,
   *  whatever the viewport — for a wide table in a column beside a side nav
   *  (a 1024px laptop leaves ~750px). A container query: the table is
   *  wrapped in a `.data-table-host` query container. Implies stackOnPhone.
   *  Both are screen-only: a printed page keeps the table. */
  stackWhenNarrow?: boolean;
}) {
  const getKey = rowKey ?? ((r: R) => (r.id ?? "") as string | number);
  const [sorting, setSorting] = useState<SortingState>(
    initialSort ? [{ id: initialSort.key, desc: initialSort.desc ?? false }] : [],
  );

  // `cell` is never handed to flexRender (see the <td> below), so a new
  // `columns` array each render costs a column-model rebuild, not a remount.
  const columnDefs = useMemo<ColumnDef<R>[]>(
    () =>
      columns.map((c) => ({
        id: c.key,
        header: c.header,
        cell: ({ row }) => c.render(row.original),
        enableSorting: Boolean(c.sortValue),
        accessorFn: c.sortValue ?? (() => ""),
        sortingFn: "basic",
        sortDescFirst: false,
      })),
    [columns],
  );

  const table = useReactTable({
    data: rows,
    columns: columnDefs,
    state: { sorting },
    onSortingChange: setSorting,
    getCoreRowModel: getCoreRowModel(),
    getSortedRowModel: getSortedRowModel(),
    getRowId: (row, index) => String(getKey(row) || index),
  });

  if (rows.length === 0 && empty !== undefined) {
    return <>{empty}</>;
  }

  const byKey = new Map(columns.map((c) => [c.key, c]));
  const alignFor = (key: string) => byKey.get(key)?.align;
  const stacks = stackOnPhone || stackWhenNarrow;
  const fixed = columns.some((c) => c.width);
  // Stacking and column priority are container queries, so their container
  // is a wrapper of ours.
  const hosted = stackWhenNarrow || columns.some((c) => c.priority || c.sticky);
  const wrap = (t: ReactNode) => (hosted ? <div className="data-table-host">{t}</div> : t);
  // data-col-priority / data-col-sticky / data-col-print on every <col>,
  // <th> and <td> of the column (components.css hides / pins them).
  const colAttrs = (key: string) => {
    const c = byKey.get(key);
    return {
      "data-col-priority": c?.priority,
      "data-col-sticky": c?.sticky,
      "data-col-print": c?.hideInPrint ? "hide" : undefined,
    };
  };

  return wrap(
    <table
      className={cn(
        "data-table w-full",
        stacks && "stack-phone",
        stackWhenNarrow && "stack-narrow",
        fixed && "fixed-cols",
        columns.some((c) => c.sticky) && "sticky-cols",
      )}
      role={stacks ? "table" : undefined}
    >
      {caption && (
        <caption className="t-eyebrow mb-2 text-left">{caption}</caption>
      )}
      {fixed && (
        <colgroup>
          {columns.map((c) => (
            <col key={c.key} style={c.width ? { width: c.width } : undefined} {...colAttrs(c.key)} />
          ))}
        </colgroup>
      )}
      <thead className={cn(stickyHeader && "sticky top-0 z-10 bg-bg-1")} role={stacks ? "rowgroup" : undefined}>
        {table.getHeaderGroups().map((hg) => (
          <tr key={hg.id} role={stacks ? "row" : undefined}>
            {hg.headers.map((h) => {
              const align = alignFor(h.column.id);
              const sortable = h.column.getCanSort();
              const dir = h.column.getIsSorted();
              const ariaSort = sortable
                ? dir === "asc"
                  ? "ascending"
                  : dir === "desc"
                    ? "descending"
                    : "none"
                : undefined;
              return (
                <th
                  key={h.id}
                  scope="col"
                  role={stacks ? "columnheader" : undefined}
                  className={align === "right" ? "num" : ""}
                  aria-sort={ariaSort}
                  {...colAttrs(h.column.id)}
                >
                  {sortable ? (
                    <button
                      type="button"
                      onClick={h.column.getToggleSortingHandler()}
                      className={cn(
                        "inline-flex items-center gap-1 transition-colors duration-200 ease-brand hover:text-text-0",
                        align === "right" && "flex-row-reverse",
                      )}
                      aria-label={`sort by ${String(h.column.columnDef.header)}`}
                    >
                      {flexRender(h.column.columnDef.header, h.getContext())}
                      {dir === "asc" && <ChevronUp className="size-3" aria-hidden />}
                      {dir === "desc" && <ChevronDown className="size-3" aria-hidden />}
                    </button>
                  ) : (
                    flexRender(h.column.columnDef.header, h.getContext())
                  )}
                </th>
              );
            })}
          </tr>
        ))}
      </thead>
      <tbody role={stacks ? "rowgroup" : undefined}>
        {table.getRowModel().rows.map((row) => (
          <tr
            key={row.id}
            onClick={onRowClick ? () => onRowClick(row.original) : undefined}
            onKeyDown={
              onRowClick
                ? (e) => {
                    if (e.key === "Enter" || e.key === " ") {
                      e.preventDefault();
                      onRowClick(row.original);
                    }
                  }
                : undefined
            }
            tabIndex={onRowClick ? 0 : undefined}
            role={onRowClick ? "button" : stacks ? "row" : undefined}
            className={cn(onRowClick && "cursor-pointer")}
          >
            {row.getVisibleCells().map((cell) => (
              <td
                key={cell.id}
                className={alignFor(cell.column.id) === "right" ? "num" : ""}
                role={stacks ? "cell" : undefined}
                data-label={stacks ? (byKey.get(cell.column.id)?.header ?? "") : undefined}
                {...colAttrs(cell.column.id)}
              >
                {/* Call the renderer; never flexRender(columnDef.cell).
                    flexRender mounts any function as a React component, and
                    callers pass a fresh `columns` array (fresh closures) on
                    every render — so each keystroke in a cell's <input>
                    would unmount and remount it, dropping focus after one
                    character. A plain call keeps the returned elements'
                    own component types, which are stable. */}
                {stacks ? (
                  // One grid item beside the ::before label, however many
                  // nodes the renderer returns (e.g. "×1" + "(shared)").
                  <div className="min-w-0">{byKey.get(cell.column.id)?.render(row.original)}</div>
                ) : (
                  byKey.get(cell.column.id)?.render(row.original)
                )}
              </td>
            ))}
          </tr>
        ))}
      </tbody>
    </table>,
  );
}
