"use client";
import type { ReactNode } from "react";
import { cn } from "../lib/cn";

type ChipTone = "accent" | "signal" | "warn" | "err" | "idle" | "default";

// Engine choice: kept the legacy `status-pill`/tone/`idle` classes (already
// button-compatible — see `.status-pill[role="button"], button.status-pill`
// in components.css) rather than switching to `badgeVariants`, so the
// existing appearance is byte-for-byte unchanged. New token utilities
// (transition) are layered on via `cn` alongside them; focus falls back to
// the global `:focus-visible` saffron outline defined in theme.css.
export function Chip({
  active = false,
  count,
  tone = "default",
  onClick,
  type = "button",
  children,
  ariaLabel,
}: {
  active?: boolean;
  count?: number;
  tone?: ChipTone;
  onClick?: () => void;
  type?: "button" | "submit";
  children: ReactNode;
  ariaLabel?: string;
}) {
  // An inactive chip is the quiet `idle` pill plus `chip-off`, which draws
  // its label in --text-1: the idle pill's --text-2 on --bg-2 is ~4.35:1,
  // short of WCAG AA (4.5:1) for this 12px label (2026-10 audit; it was
  // --text-3, ~2.2:1).
  const legacyCls = active
    ? `status-pill ${tone === "default" ? "accent" : tone}`
    : "status-pill idle chip-off";
  const inner = (
    <>
      <span>{children}</span>
      {count !== undefined && (
        <span className="t-mono-sm" style={{ marginLeft: 6 }}>
          {count}
        </span>
      )}
    </>
  );

  // A Chip with no `onClick` (and not a form submit) is a display-only status
  // pill — it must NOT render as an interactive button, which read as a
  // clickable filter that did nothing. Render the non-interactive `.status-pill`
  // span (same engine as StatusPill) instead. Pass an onClick (or type="submit")
  // to get the real interactive control. Same uncontrolled-handler honesty as
  // RangeSelector.
  const interactive = onClick !== undefined || type === "submit";
  if (!interactive) {
    return (
      <span
        className={cn(legacyCls, "transition-colors duration-200 ease-brand")}
        aria-label={ariaLabel}
        style={{ appearance: "none", padding: "6px 14px" }}
      >
        {inner}
      </span>
    );
  }

  return (
    <button
      type={type}
      className={cn(
        legacyCls,
        "transition-colors duration-200 ease-brand",
      )}
      aria-pressed={active}
      aria-label={ariaLabel}
      onClick={onClick}
      style={{ cursor: "pointer", appearance: "none", padding: "6px 14px" }}
    >
      {inner}
    </button>
  );
}

export function ChipGroup({
  label,
  children,
  scroll = false,
}: {
  label?: string;
  children: ReactNode;
  /** Below the `sm` breakpoint keep the label and every chip on ONE line
   *  that scrolls sideways, instead of wrapping into a stack of rows — for
   *  a filter bar that must not push the content it filters off a phone's
   *  first screen. The chips stay in DOM order, so focus order matches what
   *  is seen and a focused chip scrolls itself into view. From `sm` up the
   *  group wraps as usual. */
  scroll?: boolean;
}) {
  return (
    // flex-wrap: on a phone the chips continue on the next line under the
    // label rather than squeezing into a ragged column beside it.
    <div
      className={cn("row-8", "flex-wrap", scroll && "min-w-0 max-sm:w-full max-sm:flex-nowrap")}
      role="group"
      aria-label={label}
      data-chip-scroll={scroll ? "" : undefined}
    >
      {label && (
        <span className={cn("t-label", scroll && "shrink-0")} style={{ marginBottom: 0 }}>
          {label}
        </span>
      )}
      <div
        className={cn(
          "cluster",
          // A scroll box clips what pokes out of it, so a chip's focus
          // outline is drawn just inside its edge here (same saffron
          // :focus-visible outline, negative offset) instead of 2px outside.
          scroll &&
            "max-sm:min-w-0 max-sm:flex-1 max-sm:flex-nowrap max-sm:overflow-x-auto max-sm:whitespace-nowrap max-sm:[&_button:focus-visible]:-outline-offset-2",
        )}
      >
        {children}
      </div>
    </div>
  );
}
