import type { ChannelTrace } from "../data/types";

interface Props {
  /** Either pass a full ChannelTrace... */
  trace?: ChannelTrace;
  /** ...or a flat numeric series and let Sparkline derive the trace. */
  values?: number[];

  channel: "temp" | "hum" | "co2" | "vpd";
  label: string;
  /** Display value with unit ("64.2", "94", "812"). */
  display: string;
}

const SPARK_W = 100;
const SPARK_H = 22;

/**
 * The sparkline's path data. A sample that is not a finite number (a sensor
 * that reported nothing → NaN / null) is a gap: the line lifts and restarts
 * after it, and never writes "NaN" into the path (the browser rejects
 * `d="M 0.0 NaN"`). `range` defaults to the finite samples' min..max.
 * Returns "" when there is nothing to draw.
 */
export function sparkPath(
  samples: ReadonlyArray<{ v: number | null | undefined }>,
  range?: readonly [number, number],
): string {
  const finite = samples.map((s) => s.v).filter((v): v is number => typeof v === "number" && Number.isFinite(v));
  if (finite.length === 0) return "";
  let lo = range?.[0];
  let hi = range?.[1];
  if (lo === undefined || hi === undefined || !Number.isFinite(lo) || !Number.isFinite(hi)) {
    lo = Math.min(...finite);
    hi = Math.max(...finite);
  }
  const span = Math.max(1e-6, hi - lo);
  const n = samples.length;
  const parts: string[] = [];
  let pen = false;
  samples.forEach((s, i) => {
    const v = s.v;
    if (typeof v !== "number" || !Number.isFinite(v)) {
      pen = false;
      return;
    }
    const x = (i / Math.max(1, n - 1)) * SPARK_W;
    const y = SPARK_H - ((v - lo!) / span) * SPARK_H;
    parts.push(`${pen ? "L" : "M"} ${x.toFixed(1)} ${y.toFixed(1)}`);
    pen = true;
  });
  return parts.join(" ");
}

/**
 * Compact 22px-tall sparkline used in side panels per components.md §9.
 * For full oscilloscope traces use TraceRow.
 *
 * Accepts either a `trace: ChannelTrace` (preferred when ticks are
 * meaningful) or a flat `values: number[]` series for the common case
 * of "just plot these numbers".
 */
export function Sparkline({ channel, trace, values, label, display }: Props) {
  // A trace brings its own range; a flat series is scaled to its own min..max.
  const d = trace ? sparkPath(trace.samples, trace.range) : sparkPath((values ?? []).map((v) => ({ v })));
  return (
    <div className="c-sparkrow">
      <div className={`srow ${channel}`}>
        <span>{label}</span>
        <svg viewBox={`0 0 ${SPARK_W} ${SPARK_H}`} preserveAspectRatio="none" aria-hidden>
          {d && <path className="spark" d={d} />}
        </svg>
        <span className="val">{display}</span>
      </div>
    </div>
  );
}
