import { useNavigate } from "react-router-dom";
import {
  Button,
  CategoryBreakdown,
  CategoryDot,
  Chip,
  ChipGroup,
  DataTable,
  EmptyState,
  Input,
  KpiCard,
  PageHeader,
  SearchInput,
  SPECIES_LIBRARY,
  StatusPill,
  cn,
  countByCategory,
  speciesCategories,
  type SpeciesEntry,
  type SpeciesPhase,
} from "@sporeprint/design";
import type { ReactNode } from "react";
import { CloudPill } from "../components/CloudPill";
import { PiTopBar } from "../components/PiTopBar";

// Full 74-entry catalog (gourmet + medicinal + active + novelty),
// ported from sporeprint/server/app/species/profiles.py.
const PI_SPECIES_LIBRARY: SpeciesEntry[] = SPECIES_LIBRARY;

// Every category the library has, in the shared display order — derived from
// the data, never hard-coded (a hard-coded gourmet/medicinal/active list left
// the 8 novelty species out of the KPI and the filter chips).
const CATEGORIES: string[] = speciesCategories(PI_SPECIES_LIBRARY);

function Section({ label, children }: { label: string; children: ReactNode }) {
  return (
    <section className="flex flex-col gap-2">
      <span className="font-mono text-[13px] font-medium tracking-[0.16em] uppercase text-text-2">{label}</span>
      {children}
    </section>
  );
}

const TONE: Record<SpeciesEntry["difficulty"], "signal" | "warn" | "err"> = {
  beginner: "signal",
  intermediate: "warn",
  advanced: "err",
};

/** "all" or one of CATEGORIES. */
type Cat = string;
type Diff = "all" | "beginner" | "intermediate" | "advanced";
const DIFFICULTIES: ReadonlyArray<Exclude<Diff, "all">> = ["beginner", "intermediate", "advanced"];

const RECENT_KEY = "pi:species:recent";

function loadRecent(): string[] {
  if (typeof window === "undefined") return [];
  try {
    const raw = window.localStorage.getItem(RECENT_KEY);
    return raw ? (JSON.parse(raw) as string[]) : [];
  } catch {
    return [];
  }
}

function pushRecent(id: string): string[] {
  const current = loadRecent().filter((x) => x !== id);
  const next = [id, ...current].slice(0, 6);
  if (typeof window !== "undefined") {
    try {
      window.localStorage.setItem(RECENT_KEY, JSON.stringify(next));
    } catch {}
  }
  return next;
}

function allTags(): string[] {
  const set = new Set<string>();
  for (const s of PI_SPECIES_LIBRARY) for (const t of s.tags) set.add(t);
  return Array.from(set).sort();
}

/** Tags offered while the tag list is collapsed. */
const COLLAPSED_TAG_COUNT = 12;

/**
 * Tags by how many species carry them (most first, ties A→Z), leaving out
 * tags that just repeat a category or difficulty — the chips above already
 * filter on those.
 */
function popularTags(): string[] {
  const counts = new Map<string, number>();
  for (const s of PI_SPECIES_LIBRARY) for (const t of s.tags) counts.set(t, (counts.get(t) ?? 0) + 1);
  const redundant = new Set<string>([...CATEGORIES, ...DIFFICULTIES]);
  return [...counts]
    .filter(([t]) => !redundant.has(t))
    .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
    .map(([t]) => t);
}

export function SpeciesPage() {
  const navigate = useNavigate();
  const [query, setQuery] = useState("");
  const [cat, setCat] = useState<Cat>("all");
  const [diff, setDiff] = useState<Diff>("all");
  const [tagFilter, setTagFilter] = useState<Set<string>>(new Set());
  const [expanded, setExpanded] = useState<string | null>(null);
  const [recent, setRecent] = useState<string[]>(() => loadRecent());
  const [grams, setGrams] = useState("2270");
  // Phones: the category / difficulty chips, the tag filter, the category
  // breakdown and the "recently viewed" strip fold behind one "filters"
  // button, so the first species card is on the first screen (2026-10
  // audit, 390×844: it started at 793px, 849px with a "recently viewed"
  // strip; at 390×667, 558px once a species had been opened — the strip
  // alone pushed it 57px further down). Wider screens always show them.
  const [filtersOpen, setFiltersOpen] = useState(false);
  const chipsId = useId();
  const tagsId = useId();
  const recentId = useId();
  const activeFilters = (cat !== "all" ? 1 : 0) + (diff !== "all" ? 1 : 0) + tagFilter.size;

  const tags = useMemo(allTags, []);
  const popular = useMemo(popularTags, []);

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    return PI_SPECIES_LIBRARY.filter((s) => {
      if (cat !== "all" && s.category !== cat) return false;
      if (diff !== "all" && s.difficulty !== diff) return false;
      if (tagFilter.size > 0 && !s.tags.some((t) => tagFilter.has(t))) return false;
      if (!q) return true;
      return [s.common, s.binomial, s.tldr, ...s.tags].join(" ").toLowerCase().includes(q);
    });
  }, [query, cat, diff, tagFilter]);

  const recentEntries = useMemo(
    () => recent.map((id) => PI_SPECIES_LIBRARY.find((s) => s.id === id)).filter(Boolean) as SpeciesEntry[],
    [recent],
  );

  function toggleTag(t: string) {
    setTagFilter((prev) => {
      const next = new Set(prev);
      if (next.has(t)) next.delete(t);
      else next.add(t);
      return next;
    });
  }

  function clearTags() {
    setTagFilter(new Set());
  }

  function handleExpand(id: string) {
    if (expanded === id) {
      setExpanded(null);
    } else {
      setExpanded(id);
      setRecent(pushRecent(id));
    }
  }

  return (
    <>
      <PiTopBar
        crumbs={[{ label: "control" }, { label: "species", active: true }]}
        right={<CloudPill />}
      />

      <PageHeader
        eyebrow="Control"
        title="Species library"
        italic={false}
        meta={
          <span>
            {filtered.length} of {PI_SPECIES_LIBRARY.length} cached locally · works offline · TEK guides + substrate recipes per species
          </span>
        }
      />

      <div className="grid grid-cols-[minmax(0,1fr)] gap-[22px] px-4 pt-4 pb-6 sm:px-7 sm:pt-[22px] sm:pb-7 max-w-none">
        <main className="flex flex-col gap-[18px]">
          <Kpis filtered={filtered} breakdownOnPhone={filtersOpen} />

          <Toolbar
            query={query}
            onQuery={setQuery}
            cat={cat}
            onCat={setCat}
            diff={diff}
            onDiff={setDiff}
            filtersOpen={filtersOpen}
            onToggleFilters={() => setFiltersOpen((o) => !o)}
            activeFilters={activeFilters}
            controls={[chipsId, tagsId, ...(recentEntries.length > 0 ? [recentId] : [])]}
            chipsId={chipsId}
          />

          <TagFilter
            id={tagsId}
            hiddenOnPhone={!filtersOpen}
            tags={tags}
            popular={popular}
            active={tagFilter}
            onToggle={toggleTag}
            onClear={clearTags}
          />

          {recentEntries.length > 0 && (
            <RecentStrip id={recentId} hiddenOnPhone={!filtersOpen} entries={recentEntries} onPick={handleExpand} />
          )}

          {/* Rows size to their own cards (no auto-rows-fr: that made all 74
              cards as tall as the tallest one in the library, and every row
              as tall as an expanded card). An expanded card takes a whole
              row — its phase table and galleries need the width — so it is
              never stretched against row-mates either. No `grid-flow-dense`:
              back-filling the gap an expanded card leaves pulled later cards
              up AHEAD of it on screen while they stayed after it in the DOM,
              so Tab order no longer matched what was seen. The card expands
              where it is; cards before it in its row keep their row (with a
              gap after them), cards after it follow it. */}
          <div
            className="grid min-w-0 grid-cols-[repeat(auto-fit,minmax(min(320px,100%),1fr))] gap-3"
            data-species-grid=""
          >
            {filtered.map((s) => (
              <SpeciesCard
                key={s.id}
                s={s}
                expanded={expanded === s.id}
                onExpand={() => handleExpand(s.id)}
                onPlan={() => navigate(`/planner?species=${encodeURIComponent(s.id)}`)}
                grams={grams}
                onGrams={setGrams}
              />
            ))}
          </div>

          {filtered.length === 0 && (
            <EmptyState
              title="No matches"
              body="Clear tags or broaden the search to see the full library."
            />
          )}
        </main>
      </div>
    </>
  );
}

function Kpis({ filtered, breakdownOnPhone }: { filtered: SpeciesEntry[]; breakdownOnPhone: boolean }) {
  const beginner = filtered.filter((s) => s.difficulty === "beginner").length;
  const avgTtf = filtered.length
    ? Math.round(filtered.reduce((sum, s) => sum + s.ttf, 0) / filtered.length)
    : 0;
  // Every category, so the breakdown always sums to "visible".
  const byCategory = countByCategory(filtered, CATEGORIES);
  // Short one-line labels, so every value starts at the same height. The
  // breakdown is its own small grid (count over name, per category) rather
  // than "30 · 11 · 25" under a three-line "gourmet · medicinal · active"
  // label: that ran past its card at 1280px and sat lower than its
  // neighbours, and a fourth category would only make it longer.
  // Phones: three short KPIs share a row (.kpi-grid-dense compresses them)
  // and the breakdown takes the next one — while the filters are open (it
  // is what they filter by); closed, it waits behind the "filters" button.
  return (
    <section
      className="kpi-grid-dense grid grid-cols-3 gap-3 xl:grid-cols-4"
      aria-label="library summary"
      data-species-kpis=""
    >
      <KpiCard label="visible" value={filtered.length.toString()} />
      <KpiCard label="beginner" value={beginner.toString()} tone="signal" />
      <KpiCard label="avg ttf" value={`${avgTtf}d`} tone="accent" />
      <KpiCard
        label="by category"
        className={cn("col-span-3 xl:col-span-1", !breakdownOnPhone && "max-sm:hidden")}
        valueClassName="text-[12px] leading-none"
        value={<CategoryBreakdown rows={byCategory} label="visible species by category" />}
      />
    </section>
  );
}

function Toolbar({
  query,
  onQuery,
  cat,
  onCat,
  diff,
  onDiff,
  filtersOpen,
  onToggleFilters,
  activeFilters,
  controls,
  chipsId,
}: {
  query: string;
  onQuery: (v: string) => void;
  cat: Cat;
  onCat: (c: Cat) => void;
  diff: Diff;
  onDiff: (d: Diff) => void;
  filtersOpen: boolean;
  onToggleFilters: () => void;
  /** Category + difficulty + tags in use — said on the closed button. */
  activeFilters: number;
  /** Ids of everything the phone's "filters" button shows and hides. */
  controls: string[];
  chipsId: string;
}) {
  return (
    <section className="flex min-w-0 flex-row flex-wrap items-center gap-2 rounded-md border border-border-soft bg-bg-1 p-4 sm:p-[26px]">
      {/* phone: a 180px basis, so the "filters" button fits beside it */}
      <div className="min-w-[240px] flex-[1_1_280px] max-sm:min-w-0 max-sm:basis-[180px]">
        <SearchInput
          value={query}
          onChange={onQuery}
          placeholder="search by name, binomial, tag …"
          ariaLabel="search species"
        />
      </div>
      {/* Phones only: the filters below fold behind this. */}
      <Button
        variant="ghost"
        size="sm"
        className="shrink-0 sm:hidden"
        aria-expanded={filtersOpen}
        aria-controls={controls.join(" ")}
        onClick={onToggleFilters}
        data-phone-filters-toggle=""
      >
        {filtersOpen ? "filters ↑" : activeFilters > 0 ? `filters · ${activeFilters} ↓` : "filters ↓"}
      </Button>
      {/* display: contents — the chip groups stay items of this row */}
      <div id={chipsId} className={cn("contents", !filtersOpen && "max-sm:hidden")}>
      {/* scroll: on a phone each group is one sideways-scrolling line, not
          three wrapped rows of chips. */}
      <ChipGroup label="category" scroll>
        <Chip active={cat === "all"} onClick={() => onCat("all")}>all</Chip>
        {CATEGORIES.map((c) => (
          <Chip key={c} active={cat === c} onClick={() => onCat(c)}>
            <CategoryDot category={c} className="mr-1.5" />
            {c}
          </Chip>
        ))}
      </ChipGroup>
      <ChipGroup label="difficulty" scroll>
        <Chip active={diff === "all"} onClick={() => onDiff("all")}>all</Chip>
        {DIFFICULTIES.map((d) => (
          <Chip key={d} active={diff === d} onClick={() => onDiff(d)}>{d}</Chip>
        ))}
      </ChipGroup>
      </div>
    </section>
  );
}

/**
 * The 129-tag multi-select, collapsed by default: all of it wrapped was
 * ~3,100px tall on a phone, so the first species card started ~4,500px down.
 * Collapsed it shows the most-used tags, up to COLLAPSED_TAG_COUNT (one
 * sideways-scrolling line on a phone), in a fixed order: a chip never moves
 * when it is toggled (selecting one used to pull it to the front, so a
 * quick second click landed on a different tag). Selected tags from outside
 * that dozen follow it, taking the places of its least-used unselected
 * chips. Tags combine as OR — a species shows when it has any of them —
 * which the row's label says. "all N tags"
 * is a disclosure button (aria-expanded / aria-controls) for the full A→Z
 * list. Every chip stays a real toggle button with aria-pressed either way.
 */
/** The collapsed tag row: the most-used dozen in a fixed order, selected
 *  ones kept in place, then selected tags from outside the dozen — which
 *  take the places of the dozen's last unselected chips. */
function collapsedTags(popular: readonly string[], selected: readonly string[]): string[] {
  const top = popular.slice(0, COLLAPSED_TAG_COUNT);
  const picked = new Set(selected);
  const extra = selected.filter((t) => !top.includes(t));
  let room = COLLAPSED_TAG_COUNT - extra.length - top.filter((t) => picked.has(t)).length;
  const kept = top.filter((t) => {
    if (picked.has(t)) return true;
    room -= 1;
    return room >= 0;
  });
  return [...kept, ...extra];
}

function TagFilter({
  id,
  hiddenOnPhone,
  tags,
  popular,
  active,
  onToggle,
  onClear,
}: {
  id: string;
  /** Folded behind the toolbar's "filters" button (phones only). */
  hiddenOnPhone: boolean;
  tags: string[];
  popular: string[];
  active: Set<string>;
  onToggle: (t: string) => void;
  onClear: () => void;
}) {
  const [open, setOpen] = useState(false);
  const labelId = useId();
  const listId = useId();
  const selected = tags.filter((t) => active.has(t));
  const shown = open ? tags : collapsedTags(popular, selected);
  return (
    <section
      id={id}
      className={cn("flex min-w-0 flex-col gap-2", hiddenOnPhone && "max-sm:hidden")}
      data-tag-filter={open ? "open" : "collapsed"}
    >
      <div className="flex flex-wrap items-center gap-x-3 gap-y-1">
        <span id={labelId} className="font-mono text-[13px] font-medium tracking-[0.16em] uppercase text-text-2">
          tags · any of
        </span>
        {/* Always mounted: a live region added together with its first
            text is often not announced, so the first selection went
            unsaid. Back at none it says so (to screen readers only). */}
        <span className="font-mono text-[12px] text-accent" aria-live="polite" aria-atomic="true" data-tag-count="">
          {selected.length > 0 ? `${selected.length} selected` : <span className="sr-only">no tags selected</span>}
        </span>
        <span className="ml-auto flex items-center gap-3">
          {selected.length > 0 && (
            <Button variant="link" size="sm" onClick={onClear}>
              clear
            </Button>
          )}
          <Button
            variant="link"
            size="sm"
            aria-expanded={open}
            aria-controls={listId}
            onClick={() => setOpen((o) => !o)}
          >
            {open ? "fewer tags ↑" : `all ${tags.length} tags ↓`}
          </Button>
        </span>
      </div>
      <div
        id={listId}
        role="group"
        aria-labelledby={labelId}
        data-tag-list=""
        className={cn(
          "flex min-w-0 flex-wrap gap-1.5",
          // Phone: one sideways-scrolling line; focus outline drawn inside
          // the chip so the scroll box does not clip it (as ChipGroup scroll).
          !open && "max-sm:flex-nowrap max-sm:overflow-x-auto max-sm:whitespace-nowrap max-sm:[&_button:focus-visible]:-outline-offset-2",
        )}
      >
        {shown.map((t) => (
          <Chip key={t} active={active.has(t)} onClick={() => onToggle(t)}>
            {t}
          </Chip>
        ))}
      </div>
    </section>
  );
}

/** The species opened lately, as chips that open them again. On a phone it
 *  is folded behind the toolbar's "filters" button with the rest (so opening
 *  a card never pushes the first card of the list below the fold); opened,
 *  its label sits above one sideways-scrolling line of chips. */
function RecentStrip({
  id,
  hiddenOnPhone,
  entries,
  onPick,
}: {
  id: string;
  /** Folded behind the toolbar's "filters" button (phones only). */
  hiddenOnPhone: boolean;
  entries: SpeciesEntry[];
  onPick: (id: string) => void;
}) {
  // 2026-10 audit, 390×667: label and chips shared one scroller, so the
  // ~160px label left room for exactly one chip and the next began 1px past
  // the edge — nothing hinted at more (the category, difficulty and tag rows
  // each show a partly cut chip). On a phone the label now sits above its
  // own line of chips, so two show whole and a third is cut, and a fade at
  // the right edge marks the line as scrollable.
  return (
    <section
      id={id}
      aria-label="recently viewed"
      data-recent-strip=""
      className={cn(
        // flex-nowrap on a phone too: a wrapping column sizes its line to
        // the widest item, so the chip line ran past the screen unscrolled.
        "flex min-w-0 flex-wrap items-center gap-2.5 max-sm:flex-col max-sm:flex-nowrap max-sm:items-stretch max-sm:gap-1.5",
        hiddenOnPhone && "max-sm:hidden",
      )}
    >
      <span className="mr-1.5 shrink-0 font-mono text-[13px] font-medium tracking-[0.16em] uppercase text-text-2">
        recently viewed
      </span>
      <div
        data-recent-chips=""
        className="flex min-w-0 flex-wrap gap-2.5 max-sm:flex-nowrap max-sm:overflow-x-auto max-sm:whitespace-nowrap max-sm:pr-6 max-sm:[mask-image:linear-gradient(to_right,#000_calc(100%-24px),transparent)] max-sm:[&_button:focus-visible]:-outline-offset-2"
      >
        {entries.map((e) => (
          <Chip key={e.id} active={false} onClick={() => onPick(e.id)}>
            {e.common}
          </Chip>
        ))}
      </div>
    </section>
  );
}

const CARD_CELL_BASE = "flex min-w-0 cursor-pointer flex-col gap-3 rounded-md border bg-bg-1 px-6 py-[22px]";

function SpeciesCard({
  s,
  expanded,
  onExpand,
  onPlan,
  grams,
  onGrams,
}: {
  s: SpeciesEntry;
  expanded: boolean;
  onExpand: () => void;
  onPlan: () => void;
  grams: string;
  onGrams: (v: string) => void;
}) {
  const ref = useRef<HTMLElement>(null);
  const detailId = useId();
  // Opening a card (from its button or the "recently viewed" strip) can move
  // it — to its own row, or it was off-screen to begin with: bring its top
  // into view when it is not.
  useEffect(() => {
    const el = ref.current;
    if (!expanded || !el || typeof el.scrollIntoView !== "function") return;
    // 68px: the sticky top bar; scroll-mt clears it.
    const top = el.getBoundingClientRect().top;
    if (top < 68 || top > window.innerHeight - 80) el.scrollIntoView({ block: "start", behavior: "smooth" });
  }, [expanded]);
  return (
    <article
      ref={ref}
      className={cn(
        CARD_CELL_BASE,
        expanded ? "col-span-full scroll-mt-[84px] border-accent-line" : "border-border-soft",
      )}
      data-expanded={expanded ? "" : undefined}
      onClick={onExpand}
    >
      <div className="flex items-baseline justify-between gap-3">
        <div className="flex min-w-0 flex-col gap-1">
          <span className="font-mono text-[13px] font-medium tracking-[0.16em] uppercase text-text-2">{s.common}</span>
          {/* Binomial audit: font-serif italic always, per CLAUDE.md §7 — parity
              with the pre-migration `.t-display-sm.binomial` cascade (`.binomial`
              is declared after `.t-display-sm` in components.css so its serif
              font-family already won; verified live via getComputedStyle before
              this edit). */}
          <h2 className="font-serif text-[26px] font-medium italic leading-[1.18] tracking-[-0.005em] text-text-0">
            {s.binomial}
          </h2>
        </div>
        <StatusPill tone={TONE[s.difficulty]}>{s.difficulty}</StatusPill>
      </div>
      <span className="font-mono text-[12px] text-text-2">
        <CategoryDot category={s.category} className="mr-1.5" />
        {s.category} · ttf ~{s.ttf}d · {s.flushCount}
        {!s.edible && <span className="ml-2 text-err">· not edible</span>}
      </span>
      <p className="font-body text-[16px] leading-[1.55] text-text-1">{s.tldr}</p>
      <div className="mt-1.5 flex flex-wrap gap-1.5">
        {s.tags.slice(0, 5).map((t) => (
          <span
            key={t}
            className="rounded-sm bg-bg-2 px-[9px] py-[3px] font-mono text-[12px] text-text-2"
          >
            {t}
          </span>
        ))}
      </div>

      <div className="mt-auto flex flex-wrap gap-2.5">
        <Button
          variant="link"
          size="sm"
          aria-expanded={expanded}
          aria-controls={expanded ? detailId : undefined}
          onClick={(e) => { e.stopPropagation(); onExpand(); }}
        >
          {expanded ? "collapse ↑" : "details ↓"}
        </Button>
        <Button
          variant="link"
          size="sm"
          className="ml-auto"
          onClick={(e) => { e.stopPropagation(); onPlan(); }}
        >
          apply to chamber →
        </Button>
        <Button
          variant="link"
          size="sm"
          onClick={(e) => { e.stopPropagation(); onPlan(); }}
        >
          plan grow →
        </Button>
      </div>

      {expanded && (
        <Detail id={detailId} s={s} grams={grams} onGrams={onGrams} />
      )}
    </article>
  );
}

function Detail({
  id,
  s,
  grams,
  onGrams,
}: {
  id: string;
  s: SpeciesEntry;
  grams: string;
  onGrams: (v: string) => void;
}) {
  return (
    <div
      id={id}
      className="mt-3 flex flex-col gap-[18px] border-t border-border-soft pt-[18px]"
      onClick={(e) => e.stopPropagation()}
    >
      {s.flavorProfile && (
        <Section label="Flavour"><p className="font-body text-[16px] leading-[1.55] text-text-1">{s.flavorProfile}</p></Section>
      )}

      <Section label="Phases">
        <div className="min-w-0 overflow-x-auto" data-table-scroll="">
        <table className="w-full overflow-hidden border-collapse rounded-md border border-border-soft bg-bg-1 font-body text-[13px] text-text-1">
          <thead>
            <tr>
              <th className="border-b border-border-soft bg-bg-1 px-3.5 py-2.5 text-left font-mono text-[12px] font-medium uppercase tracking-[0.14em] text-text-2">Phase</th>
              <th className="border-b border-border-soft bg-bg-1 px-3.5 py-2.5 text-left font-mono text-[12px] font-medium uppercase tracking-[0.14em] text-text-2">Temp</th>
              <th className="border-b border-border-soft bg-bg-1 px-3.5 py-2.5 text-left font-mono text-[12px] font-medium uppercase tracking-[0.14em] text-text-2">RH</th>
              <th className="border-b border-border-soft bg-bg-1 px-3.5 py-2.5 text-left font-mono text-[12px] font-medium uppercase tracking-[0.14em] text-text-2">CO₂</th>
              <th className="border-b border-border-soft bg-bg-1 px-3.5 py-2.5 text-left font-mono text-[12px] font-medium uppercase tracking-[0.14em] text-text-2">Light</th>
              <th className="border-b border-border-soft bg-bg-1 px-3.5 py-2.5 text-left font-mono text-[12px] font-medium uppercase tracking-[0.14em] text-text-2">FAE</th>
              <th className="border-b border-border-soft bg-bg-1 px-3.5 py-2.5 text-left font-mono text-[12px] font-medium uppercase tracking-[0.14em] text-text-2">Duration</th>
            </tr>
          </thead>
          <tbody>
            {s.phases.map((p, i) => <PhaseRow key={i} p={p} />)}
          </tbody>
        </table>
        </div>
      </Section>

      <Section label="Substrates">
        <p className="font-body text-[16px] leading-[1.55] text-text-1">{s.substrates.join(" · ")}</p>
        <p className="mt-1 font-mono text-[12px] text-text-2">
          ranking · {s.substrateRanking.join(" → ")}
        </p>
      </Section>

      <YieldEstimator s={s} grams={grams} onGrams={onGrams} />

      <TekGuide s={s} />

      <Recipes s={s} />

      <PhotoGallery s={s} />

      <Section label="Cultivation notes"><p className="font-body text-[16px] leading-[1.55] text-text-1">{s.cultivationNotes}</p></Section>
      <Section label="Pinning trigger"><p className="font-body text-[16px] leading-[1.55] text-text-1">{s.pinningTrigger}</p></Section>
      <Section label="Contamination risks"><p className="font-body text-[16px] leading-[1.55] text-text-1">{s.contaminationRisks}</p></Section>
      <Section label="Yield"><p className="font-body text-[16px] leading-[1.55] text-text-1">{s.yieldNotes}</p></Section>

      {s.safetyWarning && (
        <div className="flex flex-col gap-[18px] rounded-md border border-warn bg-bg-1 p-[26px]">
          {/* `.head`'s descendant selector (.side-panel .head, specificity 0-2-0)
              out-ranks the stacked `.t-warn` (0-1-0) at clean HEAD, so this
              label has always rendered muted text-2, never warn-colored —
              verified live via getComputedStyle before this edit (color
              resolved to #857E6F = --text-2, not #C89660 = --warn). Reproduced
              faithfully (text-text-2), not "fixed" to text-warn — this task is
              a parity gate, matching the `.accent`/`.override-btn` bare-usage
              precedent documented elsewhere this phase. */}
          <div className="mb-1.5 font-mono text-[15px] font-medium tracking-[0.16em] uppercase text-text-2">Safety</div>
          <p className="font-body text-[14px] leading-[1.55] text-text-1">{s.safetyWarning}</p>
        </div>
      )}
    </div>
  );
}

function YieldEstimator({
  s,
  grams,
  onGrams,
}: {
  s: SpeciesEntry;
  grams: string;
  onGrams: (v: string) => void;
}) {
  const blockGrams = Math.max(0, parseInt(grams, 10) || 0);
  // Use cultivationNotes + difficulty to derive a yield range.
  const beRange: [number, number] =
    s.difficulty === "beginner" ? [0.9, 1.2] :
    s.difficulty === "intermediate" ? [0.6, 0.9] :
    [0.4, 0.7];
  const lo = Math.round(blockGrams * beRange[0]);
  const hi = Math.round(blockGrams * beRange[1]);

  return (
    <Section label="Yield estimator">
      <div className="flex flex-wrap items-center gap-3.5">
        <label className="flex flex-col gap-1">
          <span className="font-mono text-[12px] font-medium tracking-[0.14em] uppercase text-text-2">Block size (g)</span>
          <Input
            type="number"
            min={0}
            value={grams}
            onChange={(e) => onGrams(e.target.value)}
            onClick={(e) => e.stopPropagation()}
            className="w-[140px]"
          />
        </label>
        <span className="font-mono text-[12px] text-text-2">×</span>
        <span className="font-mono text-[12px] text-text-2">
          BE {Math.round(beRange[0] * 100)}–{Math.round(beRange[1] * 100)}%
        </span>
        <span className="font-mono text-[12px] text-text-2">=</span>
        <span className="font-mono text-[28px] leading-none tracking-normal text-text-0">
          {lo.toLocaleString()}–{hi.toLocaleString()} g
        </span>
        <span className="font-mono text-[12px] text-text-3">
          (~{(lo / 454).toFixed(1)}–{(hi / 454).toFixed(1)} lb wet)
        </span>
      </div>
    </Section>
  );
}

function TekGuide({ s }: { s: SpeciesEntry }) {
  const steps = deriveTekSteps(s);
  return (
    <Section label="TEK guide">
      <ol className="flex list-none flex-col gap-2.5 p-0">
        {steps.map((step) => (
          <li
            key={step.step}
            className="flex gap-3.5 rounded-sm border border-border-soft bg-bg-2 p-3.5"
          >
            <span className="flex h-[30px] w-[30px] shrink-0 items-center justify-center rounded-full border border-accent-line bg-accent-soft font-mono text-[14px] font-medium text-accent">
              {step.step}
            </span>
            <div className="flex min-w-0 flex-col gap-1">
              <div className="flex justify-between gap-2.5">
                <span className="font-body text-[18px] font-medium leading-[1.25] text-text-0">{step.title}</span>
                <span className="font-mono text-[12px] text-text-2">{step.duration}</span>
              </div>
              <p className="font-body text-[14px] leading-[1.55] text-text-1">{step.description}</p>
              {step.tips.length > 0 && (
                <div className="font-mono text-[12px] text-accent">
                  ✓ {step.tips.join(" · ")}
                </div>
              )}
              {step.mistakes.length > 0 && (
                <div className="font-mono text-[12px] text-err">
                  ✗ {step.mistakes.join(" · ")}
                </div>
              )}
            </div>
          </li>
        ))}
      </ol>
    </Section>
  );
}

function Recipes({ s }: { s: SpeciesEntry }) {
  const recipes = deriveRecipes(s);
  // No matching recipe (e.g. CVG / manure substrates): no empty heading.
  if (recipes.length === 0) return null;
  return (
    <Section label="Substrate recipes">
      <div className="flex flex-col gap-2.5">
        {recipes.map((r, i) => {
          // DataTable's `R extends { id?: string | number }` constraint rejects
          // the fixture's ingredient type outright (zero shared props with an
          // all-optional target) — map a synthetic `id` per row, same
          // workaround BuilderPage/FirmwarePage/SetupPage already use.
          const rows = r.ingredients.map((it, j) => ({ ...it, id: j }));
          const suitabilityTone =
            r.suitability === "optimal" ? "accent" : r.suitability === "good" ? "signal" : "warn";
          return (
            <article
              key={i}
              className="flex flex-col gap-2 rounded-sm border border-border-soft bg-bg-2 p-3.5"
            >
              <div className="flex items-baseline justify-between gap-2.5">
                <span className="font-body text-[18px] font-medium leading-[1.25] text-text-0">{r.name}</span>
                <StatusPill tone={suitabilityTone}>
                  {r.suitability}
                </StatusPill>
              </div>
              {/* DataTable has no `.compact` density equivalent (no prop for
                  it, and `render` only returns cell content, not the `<td>`
                  itself) — adopted anyway per "primitives over hand-rolling";
                  rows render at DataTable's own (larger) default density, a
                  disclosed difference, not a fix. Same finding as
                  BuilderPage's Substitutions/FirmwareNodeCard tables (T6). */}
              <DataTable<(typeof rows)[number]>
                columns={[
                  { key: "ingredient", header: "Ingredient", render: (row) => row.ingredient },
                  { key: "amount", header: "Amount", align: "right", render: (row) => row.amount },
                ]}
                rows={rows}
              />
              <div className="font-mono text-[12px] text-text-2">
                hydration {r.hydrationPct}% · spawn {r.spawnRatePct}% · {r.sterilization}
              </div>
              {r.notes && <p className="font-body text-[14px] leading-[1.55] text-text-1">{r.notes}</p>}
            </article>
          );
        })}
      </div>
    </Section>
  );
}

function PhotoGallery({ s }: { s: SpeciesEntry }) {
  const photos = derivePhotos(s);
  return (
    <Section label="Photo references">
      <div className="grid grid-cols-[repeat(auto-fit,minmax(280px,1fr))] gap-3">
        {photos.map((p, i) => (
          <div key={i} className="flex flex-col overflow-hidden rounded-md border border-border-soft bg-bg-1">
            <div className="relative flex aspect-[4/3] shrink-0 items-center justify-center border-b border-border-soft bg-[radial-gradient(circle_at_30%_30%,var(--bg-2),var(--bg-0))] font-mono text-[13px] font-medium tracking-[0.12em] uppercase text-text-3 after:pointer-events-none after:absolute after:inset-0 after:bg-gradient-to-b after:from-transparent after:to-black/40 after:content-['']">
              {p.phase}
            </div>
            <div className="flex h-[116px] flex-col gap-1.5 overflow-hidden px-[18px] pt-4 pb-[18px]">
              <span className="overflow-hidden text-ellipsis whitespace-nowrap font-mono text-[13px] font-medium tracking-[0.05em] text-text-1">{p.phase}</span>
              <span className="font-mono text-[12px] text-text-2">{p.caption}</span>
            </div>
          </div>
        ))}
      </div>
    </Section>
  );
}

// ---- Helpers — derive content from existing fields -----------

interface DerivedTekStep {
  step: number;
  title: string;
  description: string;
  duration: string;
  tips: string[];
  mistakes: string[];
}

function deriveTekSteps(s: SpeciesEntry): DerivedTekStep[] {
  // Shiitake's "Browning" stage sits between the spawn run and pinning; the
  // generic steps read the run without it, then it gets a step of its own.
  const run = s.phases.filter((p) => p.phase !== "Browning");
  const browning = s.phases.find((p) => p.phase === "Browning");
  const steps: Omit<DerivedTekStep, "step">[] = [
    {
      title: "Inoculate substrate",
      description: `Mix ${s.substrateRanking[0] ?? s.substrates[0]} at the recommended hydration. Sterilise (or pasteurise as noted), cool to <80°F, then add 5–10% grain spawn under sterile conditions.`,
      duration: "1 day",
      tips: ["work near a still-air box or laminar flow", "knead spawn through the bag thoroughly"],
      mistakes: ["adding spawn while substrate is still hot", "skipping sterile gloves"],
    },
    {
      title: "Spawn run",
      description: `Hold ${run[0]?.tempF ?? "65–75°F"} at low FAE. Mycelium will fully colonise the substrate. Keep CO₂ elevated to encourage hyphal growth.`,
      duration: run[0]?.duration ?? "10–14d",
      tips: ["leave the chamber alone", "darkness is fine for spawn run"],
      mistakes: ["opening the bag prematurely", "introducing FAE before full colonisation"],
    },
    {
      title: "Pin induction",
      description: s.pinningTrigger,
      duration: run[1]?.duration ?? "3–5d",
      tips: ["temp drop overnight is the strongest single trigger", "watch for primordia within 48–72h"],
      mistakes: ["skipping cold shock when species needs it", "blasting the surface with mist"],
    },
    {
      title: "Fruit",
      description: `Hold ${run[run.length - 1]?.tempF ?? "60–70°F"} with continuous FAE per phase setpoints. Mist 2–3× per day to keep RH at the upper bound.`,
      duration: run[run.length - 1]?.duration ?? "5–7d / flush",
      tips: ["don't over-mist — substrate slime invites bacteria", "aim mist at walls, not fruits"],
      mistakes: ["letting CO₂ climb above the species ceiling", "skipping FAE because misting was 'wet'"],
    },
    {
      title: "Harvest + reset",
      description: `Cut at first veil break (or at peak shape for non-oysters). Re-soak the block, lower temperature briefly, and prepare for the next flush. Expect ${s.flushCount}.`,
      duration: "1 day per flush",
      tips: ["weigh wet + dry to track BE over flushes", "rotate the block 180° between flushes"],
      mistakes: ["leaving fruits past spore drop", "not resetting RH after harvest"],
    },
  ];

  if (browning) {
    steps.splice(2, 0, {
      title: "Browning",
      description: browning.notes ?? "Unbag the colonized block and let its outer skin brown before pinning.",
      duration: browning.duration,
      tips: ["indirect light and air on the unbagged block drive the brown skin", "evenly brown and firm = done"],
      mistakes: ["mistaking the brown, popcorned skin for contamination", "keeping the surface wet — green mold"],
    });
  }
  return steps.map((step, i) => ({ ...step, step: i + 1 }));
}

interface DerivedRecipe {
  name: string;
  ingredients: Array<{ ingredient: string; amount: string }>;
  hydrationPct: number;
  spawnRatePct: number;
  sterilization: string;
  suitability: "optimal" | "good" | "marginal";
  notes: string;
}

const RECIPE_BANK: Array<{ key: string; match: (s: SpeciesEntry) => boolean; recipe: DerivedRecipe }> = [
  {
    key: "mastermix",
    match: (s) => (s.substrateRanking[0] ?? "").toLowerCase().includes("mastermix"),
    recipe: {
      name: "MasterMix · 50/50 hardwood/soy",
      ingredients: [
        { ingredient: "Hardwood pellets · oak", amount: "1.0 kg" },
        { ingredient: "Soy hull pellets", amount: "1.0 kg" },
        { ingredient: "Filtered water", amount: "2.5 L" },
        { ingredient: "Gypsum (CaSO₄)", amount: "30 g" },
      ],
      hydrationPct: 65, spawnRatePct: 7, sterilization: "autoclave · 90 min @ 250°F", suitability: "optimal",
      notes: "Standard 4–5 lb fruiting blocks, sterilised in 0.2µm filter-patch bags.",
    },
  },
  {
    key: "hardwood",
    match: (s) => s.substrateRanking.slice(0, 2).some((r) => r.toLowerCase().includes("hardwood")),
    recipe: {
      name: "Supplemented hardwood block",
      ingredients: [
        { ingredient: "Hardwood pellets · oak", amount: "2.0 kg" },
        { ingredient: "Wheat bran (or rice bran)", amount: "200 g" },
        { ingredient: "Filtered water", amount: "2.4 L" },
        { ingredient: "Gypsum", amount: "20 g" },
      ],
      hydrationPct: 62, spawnRatePct: 5, sterilization: "autoclave · 90 min @ 250°F", suitability: "good",
      notes: "Cheaper than MasterMix but lower yields on demanding species.",
    },
  },
  {
    key: "straw",
    match: (s) => s.substrates.some((sb) => sb.toLowerCase().includes("straw")),
    recipe: {
      name: "Pasteurised straw",
      ingredients: [
        { ingredient: "Wheat or oat straw, chopped", amount: "5 kg" },
        { ingredient: "Hot water · 165°F", amount: "to cover" },
        { ingredient: "Hydrated lime (optional)", amount: "20 g per 10 L" },
      ],
      hydrationPct: 70, spawnRatePct: 10, sterilization: "lime-bath pasteurisation · 1 hr", suitability: "good",
      notes: "Cheapest substrate. Higher contam pressure — use only with oysters or beech.",
    },
  },
  {
    key: "grain",
    match: (s) => s.substrates.some((sb) => /grain|rice/i.test(sb)),
    recipe: {
      name: "Grain spawn (rye or brown rice)",
      ingredients: [
        { ingredient: "Whole rye / brown rice", amount: "1.0 kg" },
        { ingredient: "Filtered water", amount: "1.4 L (24h soak)" },
        { ingredient: "Gypsum (optional)", amount: "5 g" },
      ],
      hydrationPct: 55, spawnRatePct: 0, sterilization: "autoclave · 90 min @ 250°F", suitability: "optimal",
      notes: "Used to expand from agar / liquid culture. Shake daily during colonisation.",
    },
  },
];

function deriveRecipes(s: SpeciesEntry): DerivedRecipe[] {
  return RECIPE_BANK.filter((b) => b.match(s)).map((b) => b.recipe);
}

function derivePhotos(s: SpeciesEntry): Array<{ phase: string; caption: string }> {
  return s.phases.map((p) => ({
    phase: p.phase,
    caption: `${p.duration} · ${p.tempF}`,
  }));
}

function PhaseRow({ p }: { p: SpeciesPhase }) {
  return (
    <>
      <tr className="hover:bg-bg-2">
        <td className="border-t border-border-soft px-3.5 py-2.5 align-middle font-body text-text-0">{p.phase}</td>
        <td className="border-t border-border-soft px-3.5 py-2.5 align-middle font-mono text-text-0">{p.tempF}</td>
        <td className="border-t border-border-soft px-3.5 py-2.5 align-middle font-mono text-text-0">{p.humidity}</td>
        <td className="border-t border-border-soft px-3.5 py-2.5 align-middle font-mono text-text-0">{p.co2}</td>
        <td className="border-t border-border-soft px-3.5 py-2.5 align-middle">{p.light}</td>
        <td className="border-t border-border-soft px-3.5 py-2.5 align-middle">{p.fae}</td>
        <td className="border-t border-border-soft px-3.5 py-2.5 align-middle font-mono text-text-0">{p.duration}</td>
      </tr>
      {p.notes && (
        <tr className="hover:bg-bg-2">
          <td colSpan={7} className="border-t border-border-soft px-3.5 pt-0 pb-2 align-middle font-mono text-[12px] text-text-2">
            ↳ {p.notes}
          </td>
        </tr>
      )}
    </>
  );
}
