import { useEffect, useRef, useState, type ReactNode } from "react";
import { NavLink, useLocation } from "react-router-dom";
import { Menu, X } from "lucide-react";
import { Sidebar, Toaster, cn } from "@sporeprint/design";
import { apiGet } from "../lib/api";
import { useCloudStatus } from "./CloudPill";

// `.sidebar-link`/`.sidebar-link.active` utilities (see
// classmap-pi-delta.md §10). `.active` is SAFFRON at base — reproduced
// exactly per the Phase-3 controller ruling (parity default; grammar
// unification deferred to a coordinated all-surface sidebar-link
// retirement, same standing flag as Phase 2's tabs-neutral thread).
const SIDEBAR_LINK =
  "flex items-center gap-2.5 border-l-[3px] border-l-transparent px-[26px] py-[13px] font-body text-[16px] font-normal text-text-1 no-underline transition-all duration-[var(--dur-fast)] ease-brand hover:bg-bg-2 hover:text-text-0";
const SIDEBAR_LINK_ACTIVE = "border-l-border bg-bg-3 font-medium text-text-0";

// v3.4.x Pi UI sidebar parity: full nav, organized by section. Exported so
// copy that names a page ("Monitor → Hardware", "the Vision page") can be
// checked against it (builder-page.test).
export const NAV_SECTIONS: Array<{ label: string; items: Array<{ to: string; label: string }> }> = [
  {
    label: "Monitor",
    items: [
      { to: "/", label: "Chambers" },
      { to: "/sessions", label: "Sessions" },
      { to: "/hardware", label: "Hardware" },
      { to: "/vision", label: "Vision" },
    ],
  },
  {
    label: "Control",
    items: [
      { to: "/automation", label: "Automation" },
      { to: "/species", label: "Species" },
    ],
  },
  {
    label: "Plan",
    items: [
      { to: "/planner", label: "Planner" },
      { to: "/wizard", label: "Species Wizard" },
      { to: "/shopping", label: "Shopping List" },
    ],
  },
  {
    label: "Track",
    items: [
      { to: "/cultures", label: "Cultures" },
      // Not "Chambers": Monitor → Chambers (/) is the live view.
      { to: "/inventory", label: "Chamber inventory" },
      { to: "/experiments", label: "Experiments" },
      { to: "/contamination", label: "Contamination" },
      { to: "/transcripts", label: "Transcripts" },
    ],
  },
  {
    label: "System",
    items: [
      { to: "/builder", label: "Builder" },
      { to: "/firmware", label: "Firmware" },
      { to: "/integrations", label: "Integrations" },
      { to: "/setup", label: "Setup" },
      { to: "/settings", label: "Settings" },
    ],
  },
];

function uptimeShort(sec: number) {
  const days = Math.floor(sec / 86400);
  const hours = Math.floor((sec % 86400) / 3600);
  return `up ${days}d ${hours}h`;
}

// Sidebar-footer identity (server version + uptime) — real reads replacing
// the fake PI_HEALTH constant. Module-cached like CloudPill's status so
// remounts on navigation don't refetch; 60s staleness is plenty for an
// uptime string.
interface FooterInfo {
  version: string | null;
  uptimeSec: number | null;
}
const FOOTER_TTL_MS = 60_000;
let footerCache: { info: FooterInfo; at: number } | null = null;

function freshFooter(): FooterInfo | null {
  return footerCache && Date.now() - footerCache.at < FOOTER_TTL_MS ? footerCache.info : null;
}

function useFooterInfo(): FooterInfo | null {
  const [info, setInfo] = useState<FooterInfo | null>(freshFooter);
  useEffect(() => {
    if (freshFooter()) return;
    let cancelled = false;
    void Promise.allSettled([
      apiGet<{ version?: string }>("/api/health"),
      apiGet<{ uptime_hours?: number }>("/api/health/detail/system"),
    ]).then(([health, system]) => {
      const next: FooterInfo = {
        version: health.status === "fulfilled" ? (health.value.version ?? null) : null,
        uptimeSec:
          system.status === "fulfilled" && typeof system.value.uptime_hours === "number"
            ? Math.round(system.value.uptime_hours * 3600)
            : null,
      };
      footerCache = { info: next, at: Date.now() };
      if (!cancelled) setInfo(next);
    });
    return () => {
      cancelled = true;
    };
  }, []);
  return info;
}

/** What Tab may land on inside the open drawer. */
const FOCUSABLE =
  'a[href], button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])';

/** The drawer only exists below this width; from it up the rail is fixed. */
const DESKTOP_QUERY = "(min-width: 768px)";

export function AppShell({ children }: { children: ReactNode }) {
  const { pathname } = useLocation();
  const cloud = useCloudStatus();
  const footerInfo = useFooterInfo();
  // Below 768px the rail would leave a phone ~170px of page, so it becomes a
  // drawer behind a menu button; from 768px up it is the fixed left rail as
  // before. The open drawer is a modal dialog: role="dialog" +
  // aria-modal, the page behind it inert, Tab kept inside it, Escape or the
  // close button shuts it, and focus goes back to the menu button.
  const [navOpen, setNavOpen] = useState(false);
  const toggleRef = useRef<HTMLButtonElement>(null);
  const closeRef = useRef<HTMLButtonElement>(null);
  const drawerRef = useRef<HTMLDivElement>(null);
  const wasOpen = useRef(false);
  useEffect(() => {
    setNavOpen(false);
  }, [pathname]);
  // Widening past 768px turns the drawer back into the rail — not a dialog.
  useEffect(() => {
    if (typeof window === "undefined" || typeof window.matchMedia !== "function") return;
    const mq = window.matchMedia(DESKTOP_QUERY);
    const onChange = () => {
      if (mq.matches) setNavOpen(false);
    };
    mq.addEventListener?.("change", onChange);
    return () => mq.removeEventListener?.("change", onChange);
  }, []);
  // Focus follows the dialog: into it on open, back to the menu button on
  // close (after the page behind stops being inert, so the focus sticks).
  useEffect(() => {
    if (navOpen) {
      closeRef.current?.focus();
    } else if (wasOpen.current) {
      toggleRef.current?.focus();
    }
    wasOpen.current = navOpen;
  }, [navOpen]);
  useEffect(() => {
    if (!navOpen) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        setNavOpen(false);
        return;
      }
      if (e.key !== "Tab") return;
      const drawer = drawerRef.current;
      if (!drawer) return;
      // Visible, focusable elements of the dialog, in DOM (= Tab) order —
      // its close button first.
      const items = [...drawer.querySelectorAll<HTMLElement>(FOCUSABLE)].filter(
        (el) => !el.closest("[hidden], [inert]"),
      );
      if (items.length === 0) return;
      const first = items[0]!;
      const last = items[items.length - 1]!;
      const active = document.activeElement;
      const inside = active instanceof Node && drawer.contains(active);
      if (e.shiftKey ? !inside || active === first : !inside || active === last) {
        e.preventDefault();
        (e.shiftKey ? last : first).focus();
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [navOpen]);
  return (
    <>
      {/* Mounted before the page so it is subscribed when a page toasts
          from its first effect (e.g. /shopping?bom=<unknown> on a full
          load) — and OUTSIDE the shell grid: sonner always renders a
          <section aria-label="Notifications …">, and as a grid child it
          took column 2 of row 1, pushing the page under the sidebar. */}
      <Toaster />
      <div className="grid min-h-screen grid-cols-[280px_minmax(0,1fr)] bg-bg-0 max-[1180px]:grid-cols-[220px_minmax(0,1fr)] max-md:grid-cols-[minmax(0,1fr)] max-md:grid-rows-[auto_1fr]">
        <div className="flex items-center gap-3 border-b border-border-soft bg-bg-1 px-4 py-2.5 md:hidden" inert={navOpen}>
          <button
            ref={toggleRef}
            type="button"
            onClick={() => setNavOpen((o) => !o)}
            aria-expanded={navOpen}
            aria-controls="pi-primary-nav"
            aria-label={navOpen ? "close navigation" : "open navigation"}
            className="inline-flex h-10 w-10 cursor-pointer items-center justify-center rounded-sm border border-border-soft bg-bg-2 p-0 text-text-1 hover:text-text-0"
          >
            {navOpen ? <X size={20} aria-hidden /> : <Menu size={20} aria-hidden />}
          </button>
          <span className="font-body text-[18px] font-medium text-text-0">sporeprint</span>
          <span className="font-mono text-[13px] text-text-2">· local</span>
        </div>
        {navOpen && (
          <div aria-hidden="true" className="fixed inset-0 z-40 bg-bg-0/70 md:hidden" onClick={() => setNavOpen(false)} />
        )}
        <div
          id="pi-primary-nav"
          ref={drawerRef}
          role={navOpen ? "dialog" : undefined}
          aria-modal={navOpen ? true : undefined}
          aria-label={navOpen ? "navigation menu" : undefined}
          className={cn(
            "max-md:fixed max-md:inset-y-0 max-md:left-0 max-md:z-50 max-md:w-[min(300px,85vw)] max-md:overflow-y-auto max-md:border-r max-md:border-border-soft max-md:shadow-2xl",
            !navOpen && "max-md:hidden",
          )}
        >
          {navOpen && (
            // The drawer covers the menu button, so it has its own close
            // button — part of the dialog (first in its Tab order), drawn
            // just right of the drawer on the dimmed backdrop.
            <button
              ref={closeRef}
              type="button"
              onClick={() => setNavOpen(false)}
              aria-label="close navigation menu"
              className="fixed top-4 left-[calc(min(300px,85vw)_+_8px)] z-50 inline-flex h-10 w-10 cursor-pointer items-center justify-center rounded-sm border border-border-soft bg-bg-2 p-0 text-text-1 hover:text-text-0 md:hidden"
            >
              <X size={20} aria-hidden />
            </button>
          )}
          <Sidebar
            brand={{ word: "sporeprint", suffix: " · local" }}
            sections={NAV_SECTIONS.map((s) => ({
              label: s.label,
              items: s.items.map((item) => {
                const active =
                  item.to === "/"
                    ? pathname === "/" || pathname.startsWith("/chamber/")
                    : pathname === item.to || pathname.startsWith(`${item.to}/`);
                return (
                  <NavLink
                    key={item.to}
                    to={item.to}
                    end={item.to === "/"}
                    className={cn(SIDEBAR_LINK, active && SIDEBAR_LINK_ACTIVE)}
                  >
                    <span>{item.label}</span>
                  </NavLink>
                );
              }),
            }))}
            footer={
              footerInfo?.version
                ? {
                    version: `v${footerInfo.version}`,
                    // Cloud status only when forwarding is configured + readable —
                    // a local-only Pi shows just its version + uptime.
                    ...(cloud
                      ? {
                          statusLabel: cloud.state,
                          statusKind:
                            cloud.state === "synced" ? ("signal" as const) : cloud.state === "syncing" ? ("warn" as const) : ("err" as const),
                        }
                      : {}),
                    ...(footerInfo.uptimeSec != null
                      ? { extra: <span className="text-text-3">{uptimeShort(footerInfo.uptimeSec)}</span> }
                      : {}),
                  }
                : undefined
            }
          />
        </div>
        {/* Behind the open drawer the page is inert: not focusable, not
            clickable, hidden from assistive tech. */}
        <div className="flex min-w-0 flex-col" inert={navOpen}>
          {children}
        </div>
      </div>
    </>
  );
}
