import { useEffect, useState } from "react";
import { CloudSyncIndicator } from "@sporeprint/design";
import type { PiHealth } from "@sporeprint/design";
import { apiGet } from "../lib/api";
import { relativeSeen } from "../lib/chambers";

/** `GET /api/cloud/status` (cloud/service.py get_cloud_status) — the fields
 *  the pill reads (the endpoint returns more). */
interface CloudStatus {
  configured: boolean;
  connected: boolean;
  queue_depth: number;
  last_forward: number | null;
}

// Module-level cache: every page remounts its top bar on navigation, so
// without this each route change would refetch. ~30s staleness is fine for
// a sync indicator. Only successful fetches are cached — errors render null
// (below) and the next mount retries.
const CACHE_TTL_MS = 30_000;
let cached: { status: CloudStatus; at: number } | null = null;

function freshCache(): CloudStatus | null {
  return cached && Date.now() - cached.at < CACHE_TTL_MS ? cached.status : null;
}

function toCloud(s: CloudStatus): PiHealth["cloud"] | null {
  // A self-host Pi with cloud forwarding off isn't in an error state —
  // show nothing rather than a scary "offline".
  if (!s.configured) return null;
  if (s.connected && s.queue_depth === 0) {
    return {
      state: "synced",
      pending: 0,
      lastSync: s.last_forward != null ? relativeSeen(s.last_forward) : undefined,
    };
  }
  if (s.connected) return { state: "syncing", pending: s.queue_depth };
  return { state: "offline", pending: s.queue_depth };
}

/**
 * Top-bar cloud sync pill, wired to `GET /api/cloud/status` — replaces the
 * fake `<CloudSyncIndicator cloud={PI_HEALTH.cloud} />` constant every page
 * used to render. Renders nothing while loading, on fetch failure, or when
 * cloud forwarding is not configured — never a fake state.
 */
/**
 * Cached cloud-status hook — the CloudPill's engine, also consumed by the
 * AppShell sidebar footer so both read the same 30s-cached fetch. Returns
 * the mapped indicator state, or null while loading / on error / when
 * cloud forwarding is not configured.
 */
export function useCloudStatus(): PiHealth["cloud"] | null {
  const [status, setStatus] = useState<CloudStatus | null>(freshCache);

  useEffect(() => {
    if (freshCache()) return; // state already seeded from the cache
    let cancelled = false;
    apiGet<CloudStatus>("/api/cloud/status")
      .then((s) => {
        cached = { status: s, at: Date.now() };
        if (!cancelled) setStatus(s);
      })
      .catch(() => {
        /* unreadable status → render nothing */
      });
    return () => {
      cancelled = true;
    };
  }, []);

  return status ? toCloud(status) : null;
}

export function CloudPill() {
  const cloud = useCloudStatus();
  return cloud ? <CloudSyncIndicator cloud={cloud} /> : null;
}
