"use client";
/**
 * One hardware tier's wiring diagram, sized to its container.
 *
 * Renders the public repo's GENERATED docs/wiring-tier*.svg (built there by
 * scripts/wiring_svg/build.py; scripts/wiring_svg/fit_check.py verifies that
 * every label fits its box), which scripts/port_builder.py embeds byte-for-byte
 * in data/builder.wiring.generated.ts. It is an <img> with a data: URI, so:
 *  - it needs no bundler config (Vite or Next.js) and no network request to
 *    a Pi;
 *  - the page's CSS cannot reach inside the SVG and move its labels;
 *  - by default it has no fixed pixel width: it fills its container (never
 *    wider) and keeps the diagram's aspect ratio. Pass `href` to let readers
 *    open a full-size copy, and `zoom` to show it at a readable scale inside
 *    a scrolling box: the tier 2/3 diagrams are 1600 px wide with 7-9 px
 *    labels, so fitted into a card their text renders at 2-6 px.
 *
 * The SVG text (~170 KB) is loaded on demand — a plain dynamic import(), its
 * own chunk in Vite and Next.js alike, fetched the first time a diagram is
 * shown — instead of riding in every page's main bundle. Until it arrives the
 * component holds the diagram's place with an empty box. `loadWiringSvgs()`
 * preloads it (a test awaits it so the first render is the <img>).
 *
 * It replaces a hand-drawn per-node sketch that clipped labels at the panel
 * edge, drew pin labels under wires, cut off its legend and showed stale parts
 * (no fuses, no pull-downs).
 */
import { useEffect, useState, type CSSProperties } from "react";
import type { BuilderTier, BuilderWiringSvg } from "../data/fakeChambers";

export interface WiringDiagramProps {
  tierId: BuilderTier["id"];
  /** Makes the diagram a link (opens in a new tab) to a full-size copy, e.g.
   *  the Pi's /api/builder/diagrams/<file> or BUILDER_WIRING_DIAGRAMS'
   *  `sourceUrl`. A data: URL will not work here: browsers block opening
   *  one in a top-level tab. */
  href?: string;
  /** Replaces the default alt text (the diagram's own title and summary).
   *  Pass "" only when the same description is already on the page. */
  alt?: string;
  /** Class for the outermost element: the link when `href` is set, else the
   *  image. */
  className?: string;
  /** Show the diagram at this multiple of its natural size (its viewBox width
   *  in CSS px) — never narrower than that, wider when the container is.
   *  Omit to fit the container. With a zoom the diagram is usually wider than
   *  its container: put it in a box that scrolls (`overflow: auto`). */
  zoom?: number;
}

export type WiringSvgs = Record<BuilderTier["id"], BuilderWiringSvg>;

let loaded: WiringSvgs | null = null;
let pending: Promise<WiringSvgs> | null = null;

/**
 * The embedded tier SVGs, loaded once (a separate chunk). Resolves at once
 * after the first load; a failed load is retried by the next call.
 */
export function loadWiringSvgs(): Promise<WiringSvgs> {
  if (loaded) return Promise.resolve(loaded);
  if (!pending) {
    pending = import("../data/builder.wiring.generated").then(
      (m) => {
        loaded = m.BUILDER_WIRING_SVGS;
        return loaded;
      },
      (err: unknown) => {
        pending = null;
        throw err;
      },
    );
  }
  return pending;
}

const dataUris = new Map<BuilderTier["id"], string>();

/** The tier's SVG as a data: URI (percent-encoded UTF-8), built once. */
function svgDataUri(diagram: BuilderWiringSvg): string {
  let uri = dataUris.get(diagram.tierId);
  if (uri === undefined) {
    uri = `data:image/svg+xml;charset=utf-8,${encodeURIComponent(diagram.svg)}`;
    dataUris.set(diagram.tierId, uri);
  }
  return uri;
}

/** The SVGs once loaded: synchronously when an earlier diagram (or
 *  loadWiringSvgs) already loaded them, else after the import resolves. */
function useWiringSvgs(): { svgs: WiringSvgs | null; failed: boolean } {
  const [svgs, setSvgs] = useState<WiringSvgs | null>(loaded);
  const [failed, setFailed] = useState(false);
  useEffect(() => {
    if (svgs) return;
    let alive = true;
    loadWiringSvgs().then(
      (m) => {
        if (alive) setSvgs(m);
      },
      () => {
        if (alive) setFailed(true);
      },
    );
    return () => {
      alive = false;
    };
  }, [svgs]);
  return { svgs, failed };
}

export function WiringDiagram({ tierId, href, alt, className, zoom }: WiringDiagramProps) {
  const { svgs, failed } = useWiringSvgs();
  const diagram = svgs?.[tierId];
  const zoomed = zoom !== undefined && Number.isFinite(zoom) && zoom > 0;
  const minWidth = zoomed && diagram ? `${Math.round(diagram.width * zoom)}px` : undefined;
  const maxWidth = zoomed ? "none" : "100%";

  let inner;
  if (diagram) {
    inner = (
      <img
        src={svgDataUri(diagram)}
        alt={alt ?? `${diagram.title}. ${diagram.summary}`}
        decoding="async"
        data-tier={tierId}
        className={href ? undefined : className}
        style={{
          display: "block",
          width: "100%",
          maxWidth,
          minWidth,
          height: "auto",
          // Reserves the right height before the image decodes.
          aspectRatio: `${diagram.width} / ${diagram.height}`,
        }}
      />
    );
  } else if (failed) {
    // The chunk did not load (offline mid-upgrade, say): say so instead of
    // an empty box; a remount retries.
    inner = (
      <span
        data-tier={tierId}
        data-wiring-diagram="failed"
        className={href ? undefined : className}
        style={{
          display: "block",
          padding: "12px",
          borderRadius: "var(--r-sm)",
          background: "var(--bg-2)",
          color: "var(--text-2)",
          fontFamily: "var(--f-mono)",
          fontSize: "12px",
        }}
      >
        couldn&apos;t load the built-in wiring diagram{href ? " — open it full size" : ""}
      </span>
    );
  } else {
    // Holds the diagram's place (no layout jump when it arrives); the real
    // ratio is unknown until the SVG loads, so a typical one (the diagrams
    // run 1000x850 to 1600x1770). Hidden from assistive tech: it has nothing
    // to say yet, and it must not add words to a surrounding link's name.
    const placeholder: CSSProperties = {
      display: "block",
      width: "100%",
      maxWidth: "100%",
      aspectRatio: "1 / 1",
      maxHeight: "60vh",
      borderRadius: "var(--r-sm)",
      background: "var(--bg-2)",
    };
    inner = (
      <span
        aria-hidden="true"
        data-tier={tierId}
        data-wiring-diagram="loading"
        className={href ? undefined : className}
        style={placeholder}
      />
    );
  }

  if (!href) return inner;
  return (
    <a
      href={href}
      target="_blank"
      rel="noopener noreferrer"
      title={diagram ? `Open ${diagram.filename} full size` : "Open the wiring diagram full size"}
      className={className}
      style={{ display: "block", maxWidth, minWidth }}
    >
      {inner}
    </a>
  );
}
