interface RowState {
  purchased: Record<string, boolean>;
  notes: Record<string, string>;
  /** Grow rows bought for some of the species they serve (ticked per
   *  species before the lists were merged): row id → those species. */
  partlyBought: ReadonlyMap<string, string[]>;
  onToggle: (id: string) => void;
  onSetNote: (id: string, v: string) => void;
}

/** "partly bought — for Blue Oyster" for a partly bought grow row, else "". */
function partlyBoughtText(boughtFor: readonly string[] | undefined, speciesName: (id: string) => string): string {
  return boughtFor && boughtFor.length > 0 ? `partly bought — for ${boughtFor.map(speciesName).join(" · ")}` : "";
}

function PurchasedBox({ id, label, rs }: { id: string; label: string; rs: RowState }) {
  const partly = rs.partlyBought.has(id);
  // A partly bought row's box is mixed (indeterminate: a DOM property, not
  // an attribute) — read as "mixed" / "partially checked" by screen readers.
  const ref = useRef<HTMLInputElement>(null);
  useLayoutEffect(() => {
    if (ref.current) ref.current.indeterminate = partly;
  }, [partly]);
  return (
    <input
      ref={ref}
      type="checkbox"
      checked={Boolean(rs.purchased[id])}
      onChange={() => rs.onToggle(id)}
      aria-label={`mark ${label} purchased`}
      className="h-[18px] w-[18px] accent-accent"
      data-partly-bought={partly ? "" : undefined}
    />
  );
}

/**
 * A row's note: a textarea that grows with its text, so a long note is read
 * in full rather than scrolled inside a one-line box. In print the box gives
 * way to the note as plain wrapped text. A module-level component (a stable
 * type), so DataTable's per-render cells keep the same node — focus and the
 * whole note survive every keystroke.
 */
function NoteField({ id, label, rs }: { id: string; label: string; rs: RowState }) {
  const value = rs.notes[id] ?? "";
  const ref = useRef<HTMLTextAreaElement>(null);

  // Fit the box to its text: on every change, and when the column's width
  // changes (the text rewraps).
  function fit() {
    const el = ref.current;
    if (!el) return;
    el.style.height = "auto";
    el.style.height = `${el.scrollHeight}px`;
  }
  useLayoutEffect(fit, [value]);
  useEffect(() => {
    const el = ref.current;
    if (!el || typeof ResizeObserver === "undefined") return;
    let width = el.clientWidth;
    const ro = new ResizeObserver(() => {
      if (el.clientWidth === width) return;
      width = el.clientWidth;
      fit();
    });
    ro.observe(el);
    return () => ro.disconnect();
  }, []);

  return (
    <>
      <textarea
        ref={ref}
        rows={1}
        value={value}
        onChange={(e) => rs.onSetNote(id, e.target.value)}
        placeholder="…"
        aria-label={`note for ${label}`}
        data-note-field=""
        className="block min-h-8 w-full min-w-[120px] resize-none overflow-hidden rounded-md border border-border bg-bg-1 px-2.5 py-[5px] font-body text-sm leading-[1.4] text-text-0 transition-colors duration-200 ease-brand [overflow-wrap:anywhere] placeholder:text-text-3 hover:border-accent-line focus:border-accent-line print:hidden"
      />
      {value && (
        <p
          className="hidden whitespace-pre-wrap font-body text-[13px] leading-[1.4] text-text-0 [overflow-wrap:anywhere] print:block"
          data-testid="note-print"
        >
          {value}
        </p>
      )}
    </>
  );
}

export function ShoppingPage() {
  const location = useLocation();
  const navigate = useNavigate();
  // Ticks, notes, custom items and grow counts: each change is written
  // into what is stored now (not this tab's copy), and another tab's write
  // shows here (lib/use-stored-state) — two open lists never undo each
  // other's ticks.
  const [purchased, updatePurchased] = useStoredState(STORAGE_PURCHASED, parsePurchased, NO_FLAGS);
  const [notes, updateNotes] = useStoredState(STORAGE_NOTES, parseNotes, NO_NOTES);
  const [custom, updateCustom] = useStoredState(STORAGE_CUSTOM, toCustomItems, NO_CUSTOM);
  const [growPrefs, updateGrowPrefs] = useStoredState<GrowPrefs>(STORAGE_GROW, toGrowPrefs, EMPTY_GROW_PREFS);
  // The Builder's link carries the build (/shopping?bom=…&chambers=…), so a
  // tab opened with middle-click shows it too; otherwise the stored hand-off.
  const [bom, setBom] = useState<ShoppingBomHandoff | null>(() => {
    const sent = parseShoppingSearch(location.search).bom;
    return sent ? makeShoppingBom(sent.tierId, sent.chambers) : readShoppingBom();
  });
  const [showAdd, setShowAdd] = useState(false);
  const [filter, setFilter] = useState<StatusFilter>("all");
  const [query, setQuery] = useState("");

  // A build sent (or cleared) from another tab — the Builder's "send BOM",
  // another /shopping tab's chamber count — shows here too.
  useEffect(() => {
    const onStorage = (e: StorageEvent) => {
      if (e.key === null || e.key === SHOPPING_BOM_KEY) setBom(readShoppingBom());
    };
    window.addEventListener("storage", onStorage);
    return () => window.removeEventListener("storage", onStorage);
  }, []);

  // A hand-off in the URL is stored like a click's (pi:shopping:bom), then
  // dropped from the URL, so a reload or a later edit here is not undone by
  // a stale query.
  useEffect(() => {
    const sent = parseShoppingSearch(location.search);
    if (!sent.present) return;
    if (sent.bom) {
      const { tierId, chambers: n } = sent.bom;
      setBom(writeShoppingBom(tierId, n) ?? makeShoppingBom(tierId, n));
    } else {
      // An unknown ?bom= used to fall back without a word to whatever was
      // stored before (2026-10 audit). Say what happened (one toast, even
      // when the effect runs twice).
      const named = new URLSearchParams(location.search).get("bom") ?? "";
      toast.warning(`The link names no Builder build ("${named.slice(0, 40)}")`, {
        id: "shopping-unknown-bom",
        description: readShoppingBom()
          ? "Showing the hardware already on this list."
          : "No hardware listed — send a BOM from the Builder.",
      });
    }
    navigate({ search: withoutShoppingSearch(location.search), hash: location.hash }, { replace: true });
  }, [location.search, location.hash, navigate]);

  // ── Hardware: the sent BOM, live from this Pi (built-in copy when it
  //    can't answer) — fetched only once there is a BOM to show.
  const hasBom = bom !== null;
  const { data: liveTiers, loading: tiersLoading } = usePiLoad(
    () => (hasBom ? loadBomTiers() : Promise.resolve(null)),
    [hasBom],
  );
  const tierChoices = liveTiers ?? HARDWARE_TIERS;
  const resolved = bom ? resolveBomTier(liveTiers, bom.tierId) : null;
  const tier = resolved?.tier ?? null;
  const chambers = bom?.chambers ?? 1;
  const sections = useMemo(() => (tier ? bomSections(tier, chambers) : []), [tier, chambers]);
  const totals = tier ? bomTotals(tier.components, chambers) : null;
  // Rounded exactly as the Builder's "Estimated total" is.
  const hardwareTotal = totals ? Math.round(totals.total) : null;
  const hardwareSource: SourceState | undefined = !tier
    ? undefined
    : tiersLoading
      ? { tone: "idle", label: "checking this Pi…", detail: "showing the built-in copy until the Pi answers" }
      : resolved?.live
        ? { tone: "accent", label: "live from this Pi", detail: "parts, prices and links as this Pi's Builder serves them" }
        : {
            tone: "warn",
            label: "built-in copy — Pi API unreachable",
            detail: "generated from the public repo when this UI was built; may differ from this Pi's release",
          };

  function updateBom(tierId: ShoppingBomTierId, n: number) {
    setBom(writeShoppingBom(tierId, n) ?? makeShoppingBom(tierId, n));
  }

  function clearBom() {
    clearShoppingBom();
    setBom(null);
  }

  // ── Grow supplies: the Pi's generator for every species with an active
  //    session, plus species added by hand. Each species loads on its own;
  //    a changed grow count reloads only that species (lib/grow-lists).
  const { data: growCtx, loading: growCtxLoading } = usePiLoad(() => loadGrowContext(), []);
  const sessionsKnown = growCtx?.sessions != null;
  const counts = useMemo(() => activeGrowCounts(growCtx?.sessions ?? []), [growCtx]);
  const targets = useMemo(() => growTargets(counts, growPrefs), [counts, growPrefs]);
  const growLists = useGrowLists(targets, !growCtxLoading);

  // A stored grow count that no longer changes anything (its species is
  // neither active nor added, or it equals the active-session count) is
  // dropped once the Pi's sessions are known — never kept forever.
  useEffect(() => {
    if (!sessionsKnown) return;
    updateGrowPrefs((prev) => pruneGrowOverrides(prev, counts));
  }, [sessionsKnown, counts, updateGrowPrefs]);

  const speciesNames = useMemo(() => {
    const m = new Map<string, string>();
    for (const s of growCtx?.species ?? []) m.set(canonicalSpeciesId(s.id), s.common_name);
    return m;
  }, [growCtx]);
  const speciesName = (id: string) => {
    const r = growLists[id]?.result;
    return speciesNames.get(id) ?? (r?.status === "ok" ? r.list.common_name : id);
  };

  // Every species' list as one: each shared supply once, with the species it
  // serves (lib/shopping-list mergeGrowLists).
  const loadedLists = useMemo(
    () =>
      targets.flatMap((t): Array<{ speciesId: string; list: PiShoppingList }> => {
        const r = growLists[t.speciesId]?.result;
        return r?.status === "ok" ? [{ speciesId: t.speciesId, list: r.list }] : [];
      }),
    [targets, growLists],
  );
  const growGroups = useMemo<GrowRowGroup[]>(() => mergeGrowLists(loadedLists), [loadedLists]);

  // A supply noted per species before the lists were merged
  // (grow:<species>:<item>) keeps its note on the merged row. Its ticks stay
  // per species: one species' tick is not the whole merged row bought —
  // growPurchase reads them as "partly bought" until every species is ticked.
  useEffect(() => {
    const rows = growGroups.flatMap((g) => g.rows);
    updateNotes((prev) => migrateGrowKeys(prev, rows, combineNotes));
  }, [growGroups, updateNotes]);
  const growRowList = useMemo(() => growGroups.flatMap((g) => g.rows), [growGroups]);
  const growRowById = useMemo(() => new Map(growRowList.map((r) => [r.id, r])), [growRowList]);
  // What the page shows as bought / noted: each grow row's own state, read
  // with its per-species ticks (and a split culture row with its old merged
  // row's tick / note) — lib/shopping-list growPurchase.
  const shownPurchased = useMemo(() => effectiveGrowFlags(purchased, growRowList), [purchased, growRowList]);
  const shownNotes = useMemo(() => effectiveGrowNotes(notes, growRowList), [notes, growRowList]);
  const partlyBought = useMemo(() => {
    const m = new Map<string, string[]>();
    for (const r of growRowList) {
      const p = growPurchase(r, purchased);
      if (p.state === "partial") m.set(r.id, p.boughtFor);
    }
    return m;
  }, [purchased, growRowList]);

  const growUnreachable = !growCtxLoading && !sessionsKnown && growCtx?.species == null;
  const growSource: SourceState = growCtxLoading
    ? { tone: "idle", label: "checking this Pi…" }
    : growUnreachable
      ? {
          tone: "warn",
          label: "unavailable — Pi API unreachable",
          detail: "grow supplies are generated by the Pi from its species profiles; there is no built-in copy",
        }
      : !sessionsKnown
        ? // The panel below says what that means; no second caption here.
          { tone: "warn", label: "partly live — active sessions unavailable" }
        : { tone: "accent", label: "live from this Pi", detail: "generated by this Pi from each species' substrate recipe" };

  function setGrows(target: GrowTarget, n: number) {
    updateGrowPrefs((prev) => setGrowCount(prev, target.speciesId, clampCount(n), defaultGrows(target)));
  }

  function addSpecies(rawId: string) {
    const speciesId = canonicalSpeciesId(rawId);
    updateGrowPrefs((prev) => (prev.added.includes(speciesId) ? prev : { ...prev, added: [...prev.added, speciesId] }));
  }

  function removeSpecies(speciesId: string) {
    updateGrowPrefs((prev) => {
      const grows = { ...prev.grows };
      delete grows[speciesId];
      return { added: prev.added.filter((id) => id !== speciesId), grows };
    });
  }

  // ── Row state ──────────────────────────────────────────────────────
  const rs: RowState = {
    purchased: shownPurchased,
    notes: shownNotes,
    partlyBought,
    // The box's new state is what this tab shows flipped — set, not
    // toggled, in the stored map, so a tick another tab made is kept. A
    // partly bought row's box shows mixed, and a click buys it for every
    // species it serves. A grow row's own tick decides for its per-species
    // ones, which go.
    onToggle: (id) => {
      const next = !shownPurchased[id];
      const row = growRowById.get(id);
      updatePurchased((prev) => (row ? setGrowPurchased(prev, row, next) : { ...prev, [id]: next }));
    },
    onSetNote: (id, value) => updateNotes((prev) => ({ ...prev, [id]: value })),
  };

  function removeCustom(id: string) {
    updateCustom((prev) => prev.filter((c) => c.id !== id));
    const drop = <T,>(prev: Record<string, T>) => {
      if (!(id in prev)) return prev;
      const next = { ...prev };
      delete next[id];
      return next;
    };
    updatePurchased(drop);
    updateNotes(drop);
  }

  const shown = (id: string, haystack: ReadonlyArray<string | undefined>) =>
    matchesFilter(id, haystack, filter, query, shownPurchased);

  // Every row on the list (unfiltered) — for the counts, totals and CSV.
  const growRows = growGroups.flatMap((g) => g.rows.map((row) => ({ group: g, row })));
  // With two or more species listed, each row names the species it serves
  // (and a species' own row, its spawn, says whose it is).
  const manySpecies = loadedLists.length > 1;
  const growLabel = (row: GrowRow) =>
    manySpecies && row.perSpecies ? `${row.name} for ${speciesName(row.speciesIds[0]!)}` : row.name;
  const hardwareLines = sections.flatMap((s) => s.lines);
  const allIds = [...hardwareLines.map((l) => l.id), ...growRows.map((r) => r.row.id), ...custom.map((c) => c.id)];
  const toBuyCount = allIds.filter((id) => !shownPurchased[id]).length;
  const customSum = customTotal(custom);
  // Hardware is whole dollars like the Builder's total; what's left of it is
  // rounded the same way, so nothing bought → "still to buy" = priced total.
  const hardwareRemaining = totals
    ? Math.max(0, Math.round(hardwareLines.filter((l) => !purchased[l.id]).reduce((s, l) => s + l.total, 0)))
    : 0;
  // The cards show whole dollars (a cents figure overflows a 44px KPI);
  // the exact custom sum is in the card's caption and the section header.
  const pricedTotal = Math.round((hardwareTotal ?? 0) + customSum);
  const stillToBuy = Math.round(
    hardwareRemaining + custom.filter((c) => !purchased[c.id]).reduce((s, c) => s + c.estCost, 0),
  );
  const hardwareMatches = (l: BomLine, s: BomSection) =>
    shown(l.id, [l.component.name, l.component.role, s.label, l.component.notes]);

  function exportCsv() {
    const rows: CsvRow[] = [];
    for (const s of sections) {
      for (const l of s.lines) {
        const c = l.component;
        rows.push({
          section: "hardware",
          category: s.label,
          item: c.name,
          // "×4 · 2 packs of 2", "×1 (shared)": as the Qty column words it
          qty: quantityText(l, l.shared),
          unitPrice: priceText(c),
          lineTotal: formatUsd(l.total),
          supplier: isHttpUrl(c.url) ? linkLabel(c.url) : "",
          url: c.url,
          purchased: Boolean(purchased[l.id]),
          note: notes[l.id] ?? "",
        });
      }
    }
    for (const { group, row } of growRows) {
      const links = splitSupplierLinks(row.supplierLinks);
      rows.push({
        section: "grow supplies",
        category: `${row.speciesIds.map(speciesName).join(", ")} · ${group.category}`,
        item: row.name,
        qty: row.quantity,
        unitPrice: "",
        lineTotal: "",
        supplier: [...links.links.map((l) => l.label), ...links.hints].join("; "),
        // one URL per cell (the first supplier's); the rest are named above
        url: links.links[0]?.href ?? "",
        purchased: Boolean(shownPurchased[row.id]),
        // "purchased" is yes / no; a row bought for some of its species says so
        note: [partlyBoughtText(partlyBought.get(row.id), speciesName), shownNotes[row.id] ?? ""]
          .filter(Boolean)
          .join(" · "),
      });
    }
    for (const c of custom) {
      rows.push({
        section: "custom",
        category: c.category,
        item: c.item,
        qty: `${c.qty} ${c.unit}`.trim(),
        unitPrice: "",
        lineTotal: formatUsd(c.estCost),
        supplier: c.supplier,
        url: c.url,
        purchased: Boolean(purchased[c.id]),
        note: notes[c.id] ?? "",
      });
    }
    const blob = new Blob([toCsv(rows)], { type: "text/csv;charset=utf-8" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = "sporeprint-shopping-list.csv";
    a.click();
    URL.revokeObjectURL(url);
    toast.success(`downloaded · ${plural(rows.length, "row")} saved as CSV`);
  }

  return (
    <>
      <PiTopBar crumbs={[{ label: "plan" }, { label: "shopping", active: true }]} right={<CloudPill />} />

      <PageHeader
        eyebrow="Plan"
        title="Shopping list"
        italic={false}
        meta={
          <span className="[overflow-wrap:anywhere]">
            {plural(allIds.length, "item")} · {toBuyCount} to buy · hardware from the Builder · grow supplies from
            this Pi
          </span>
        }
      />

      <div className="grid grid-cols-[minmax(0,1fr)] gap-[22px] px-4 pt-4 pb-6 sm:px-7 sm:pt-[22px] sm:pb-7">
        <main className="flex min-w-0 flex-col gap-[22px]">
          <div className="grid grid-cols-[repeat(auto-fit,minmax(min(240px,100%),1fr))] gap-3">
            <KpiCard
              label="hardware"
              value={hardwareTotal === null ? "—" : formatUsd(hardwareTotal)}
              tone={hardwareTotal === null ? "default" : "accent"}
              delta={tier ? `${tier.name} × ${plural(chambers, "chamber")}` : "no BOM sent from the Builder"}
            />
            <KpiCard
              label="grow supplies"
              value="—"
              delta={`unpriced · ${plural(growRows.length, "item")} · the Pi's generator lists quantities and suppliers, not prices`}
            />
            <KpiCard
              label="custom"
              value={formatUsd(Math.round(customSum))}
              delta={`${plural(custom.length, "item")} · ${formatUsd(customSum)} est.`}
            />
            <KpiCard
              label="priced total"
              value={formatUsd(pricedTotal)}
              delta={`hardware + custom · ${formatUsd(stillToBuy)} still to buy`}
            />
          </div>

          <Toolbar
            filter={filter}
            onFilter={setFilter}
            query={query}
            onQuery={setQuery}
            showAdd={showAdd}
            onAddCustom={() => setShowAdd((v) => !v)}
            onPrint={() => {
              if (typeof window !== "undefined") window.print();
            }}
            onExport={exportCsv}
          />

          {showAdd && (
            <CustomItemForm
              onAdd={(item) => {
                updateCustom((prev) => [...prev, item]);
                setShowAdd(false);
              }}
            />
          )}

          {/* ── Hardware ─────────────────────────────────────────── */}
          <section aria-labelledby="shop-hw" className="flex min-w-0 flex-col gap-3.5">
            <SectionHeader
              id="shop-hw"
              title="Hardware"
              source={hardwareSource}
              meta={
                tier && bom
                  ? `${tier.name} bill of materials × ${plural(chambers, "chamber")} · sent ${new Date(bom.sentAt).toLocaleString()}`
                  : "the parts list of a Builder reference build, sized for your chamber count"
              }
            />
            {tier && bom ? (
              <>
                <div className={cn(PANEL, "print:hidden")}>
                  <ChipGroup label="build">
                    {tierChoices.map((t) => (
                      <Chip key={t.id} active={t.id === bom.tierId} onClick={() => updateBom(t.id, chambers)}>
                        {t.name}
                      </Chip>
                    ))}
                  </ChipGroup>
                  <div className="flex flex-wrap items-center gap-x-4 gap-y-2">
                    <span className={T_EYEBROW}>Chambers</span>
                    <CountInput value={chambers} label="chambers" onChange={(n) => updateBom(bom.tierId, n)} />
                    <span className="ml-auto flex flex-wrap items-center gap-4">
                      <Link to={builderLink(bom.tierId, chambers)} className={T_LINK_CTA}>
                        open in builder →
                      </Link>
                      <Button variant="ghost" size="sm" onClick={clearBom}>
                        clear hardware
                      </Button>
                    </span>
                  </div>
                  <p className={T_CAPTION}>
                    {SHARED_PARTS_NOTE} · {PER_CHAMBER_NOTE} · ticks and notes follow each part across builds
                  </p>
                </div>

                {sections.map((s) => (
                  <BomTable key={s.category} section={s} lines={s.lines.filter((l) => hardwareMatches(l, s))} rs={rs} />
                ))}
                {sections.every((s) => s.lines.every((l) => !hardwareMatches(l, s))) && (
                  <p className={T_CAPTION}>no hardware rows match the current filter</p>
                )}

                {totals && hardwareTotal !== null && (
                  <div className={PANEL}>
                    <span className={T_EYEBROW}>Hardware total · {plural(chambers, "chamber")}</span>
                    <span className="font-mono text-[28px] leading-none text-text-0" data-testid="hardware-total">
                      {formatUsd(hardwareTotal)}
                    </span>
                    {totalsCaption(totals, chambers).map((line) => (
                      <p key={line} className={T_CAPTION}>
                        {line}
                      </p>
                    ))}
                  </div>
                )}
              </>
            ) : (
              <EmptyState
                title="No BOM sent from the Builder"
                body="Pick a reference build in the Builder, set your chamber count, then use “send BOM to /shopping” — its parts, quantities and buy links land here."
                action={
                  <Link to="/builder" className={T_LINK_CTA}>
                    open the builder →
                  </Link>
                }
              />
            )}
          </section>

          {/* ── Grow supplies ────────────────────────────────────── */}
          <section aria-labelledby="shop-grow" className="flex min-w-0 flex-col gap-3.5">
            <SectionHeader
              id="shop-grow"
              title="Grow supplies"
              source={growSource}
              meta="substrate, spawn, containers and supplies from each species' first substrate recipe · quantities scale with the number of grows"
            />
            <GrowTargetsPanel
              targets={targets}
              species={growCtx?.species ?? null}
              sessionsKnown={sessionsKnown}
              unreachable={growUnreachable}
              loading={growCtxLoading}
              speciesName={speciesName}
              onGrows={setGrows}
              onAdd={addSpecies}
              onRemove={removeSpecies}
            />
            {/* Only when the Pi said so: with its sessions unreadable the
                panel above already says active grows are unknown. */}
            {targets.length === 0 && !growCtxLoading && sessionsKnown && (
              <EmptyState
                title="No active grows"
                body={
                  growCtx?.species
                    ? "Grow supplies appear here for every species with an active session. Start a session, or add a species above to see what a grow needs."
                    : "Grow supplies appear here for every species with an active session. Start a session to see what a grow needs."
                }
              />
            )}
            {targets.length > 0 && <GrowListStatus targets={targets} slots={growLists} speciesName={speciesName} />}
            {growGroups.length > 0 && (
              <GrowSupplies
                groups={growGroups}
                manySpecies={manySpecies}
                speciesName={speciesName}
                label={growLabel}
                isShown={shown}
                rs={rs}
              />
            )}
          </section>

          {/* ── Custom ───────────────────────────────────────────── */}
          <section aria-labelledby="shop-custom" className="flex min-w-0 flex-col gap-3.5">
            <SectionHeader
              id="shop-custom"
              title="Custom items"
              meta={`anything else you're buying · ${formatUsd(customSum)} est. · saved in this browser`}
            />
            {custom.length === 0 ? (
              <p className={T_CAPTION}>nothing added yet — use “+ custom item” above</p>
            ) : (
              <CustomTable
                items={custom.filter((c) => shown(c.id, [c.item, c.supplier, c.category]))}
                rs={rs}
                onRemove={removeCustom}
              />
            )}
          </section>
        </main>
      </div>
    </>
  );
}

