import { useCallback, useEffect, useRef, useState } from "react";
import { loadStored, saveStored } from "./shopping-list";

// One localStorage value as React state, kept in step with the other tabs
// of this Pi's dashboard (2026-10 browser audit: two /shopping tabs each
// wrote their whole in-memory map back, so a tick made in one tab was lost
// when the other, stale, tab ticked something else):
//
//   • every change is read-modify-write — `update(change)` applies `change`
//     to what is stored NOW (parsed), not to this tab's copy, and writes
//     only when something changed;
//   • a `storage` event (another tab wrote the key, or cleared storage)
//     re-reads it.
//
// Storage that can't be read (a private window, blocked site data) falls
// back to this tab's copy, so the page still works for the visit.

/** The stored value, parsed — or undefined when nothing is stored or
 *  storage can't be read. */
function readStored<T>(key: string, parse: (value: unknown) => T): T | undefined {
  try {
    if (typeof window === "undefined") return undefined;
    const raw = window.localStorage.getItem(key);
    return raw ? parse(JSON.parse(raw)) : undefined;
  } catch {
    return undefined;
  }
}

/**
 * `[value, update]` for localStorage `key`. `parse` validates (and migrates)
 * a stored value; `fallback` is the value when nothing is stored. Both must
 * be stable (module-level), like a hook's dependencies. `update(change)`
 * returns the value it settled on. A value that `parse` migrated (an older
 * key layout) is written back in its new form on mount.
 */
export function useStoredState<T>(
  key: string,
  parse: (value: unknown) => T,
  fallback: T,
): [T, (change: (current: T) => T) => T] {
  const [value, setValue] = useState<T>(() => loadStored(key, parse, fallback));
  // The latest value, for update() between renders (two changes in one
  // event) and for the fallback when storage can't be read.
  const latest = useRef(value);

  const update = useCallback(
    (change: (current: T) => T): T => {
      const base = readStored(key, parse) ?? latest.current;
      const next = change(base);
      if (next !== base) saveStored(key, next);
      latest.current = next;
      setValue(next);
      return next;
    },
    [key, parse],
  );

  // Write a migrated value back once (parse folded older keys into new ones).
  useEffect(() => {
    if (readStored(key, parse) !== undefined) saveStored(key, latest.current);
  }, [key, parse]);

  useEffect(() => {
    if (typeof window === "undefined") return;
    const onStorage = (e: StorageEvent) => {
      // key null: another tab cleared storage
      if (e.key !== null && e.key !== key) return;
      const next = readStored(key, parse) ?? fallback;
      latest.current = next;
      setValue(next);
    };
    window.addEventListener("storage", onStorage);
    return () => window.removeEventListener("storage", onStorage);
  }, [key, parse, fallback]);

  return [value, update];
}
