import { useEffect, useRef, useState } from "react";
import { Check, Copy, X } from "lucide-react";
import { cn } from "@sporeprint/design";
import { copyText, splitCodeSpans } from "../lib/code-spans";

type CopyState = "idle" | "copied" | "failed";

const RESET_MS = 2000;

// The copy button is an atomic inline: browsers may always wrap before it,
// which left it alone at the start of the next line after a long command.
// The code's last few characters and the button share a no-wrap run, so the
// icon always sits right after the code.
const GLUED_TAIL_CHARS = 6;

// The chip is drawn on two spans (head + glued tail) that read as one. No
// `box-decoration-break: clone`: Chrome does not count the cloned end padding
// when it breaks the line, so each wrapped line overran its paragraph by the
// padding (2–6 px in the 2026-10 audit).
const CHIP = "border-y border-border-soft bg-bg-2 py-px";
const CHIP_START = "rounded-l-sm border-l pl-[5px]";
const CHIP_END = "rounded-r-sm border-r pr-[5px]";

/**
 * One inline code span with a copy button. The code wraps anywhere
 * (`overflow-wrap: anywhere`), so a long command or URL breaks inside its
 * line instead of pushing the page wider than a phone screen.
 *
 * Copying uses the Clipboard API when the page may (https), else the
 * textarea fallback (the Pi UI is usually plain http on the LAN). If both
 * fail the button turns into an ✕, the code is selected so ⌘C / long-press
 * copies it, and the failure is announced.
 */
export function CodeSpan({ code, className }: { code: string; className?: string }) {
  const [state, setState] = useState<CopyState>("idle");
  const codeRef = useRef<HTMLElement>(null);

  useEffect(() => {
    if (state === "idle") return;
    const t = window.setTimeout(() => setState("idle"), RESET_MS);
    return () => window.clearTimeout(t);
  }, [state]);

  async function onCopy() {
    const ok = await copyText(code);
    setState(ok ? "copied" : "failed");
    if (!ok && codeRef.current) {
      try {
        window.getSelection()?.selectAllChildren(codeRef.current);
      } catch {
        // selection API unavailable — the ✕ + message still say what happened
      }
    }
  }

  const label = state === "copied" ? "copied" : state === "failed" ? "copy failed" : "copy";
  const Icon = state === "copied" ? Check : state === "failed" ? X : Copy;
  // By code point, so an emoji or astral character is never split.
  const chars = Array.from(code);
  const cut = Math.max(0, chars.length - GLUED_TAIL_CHARS);
  const head = chars.slice(0, cut).join("");
  const tail = chars.slice(cut).join("");

  return (
    <span className={cn("[overflow-wrap:anywhere]", className)} data-code-span="">
      {/* <code>'s text is exactly `code` (the button holds only an icon). */}
      <code ref={codeRef} className="font-mono text-[0.875em] text-text-0 [overflow-wrap:anywhere]">
        {head && <span className={cn(CHIP, CHIP_START)}>{head}</span>}
        <span className="whitespace-nowrap">
          <span className={cn(CHIP, CHIP_END, !head && CHIP_START)}>{tail}</span>
          <CopyButton state={state} label={label} code={code} Icon={Icon} onCopy={onCopy} />
        </span>
      </code>
      <span className="sr-only" aria-live="polite">
        {state === "copied" ? "copied to clipboard" : state === "failed" ? "copy failed — select the code and copy it manually" : ""}
      </span>
    </span>
  );
}

function CopyButton({
  state,
  label,
  code,
  Icon,
  onCopy,
}: {
  state: CopyState;
  label: string;
  code: string;
  Icon: typeof Copy;
  onCopy: () => Promise<void>;
}) {
  return (
    <button
      type="button"
      onClick={(e) => {
        e.stopPropagation();
        void onCopy();
      }}
      aria-label={`${label}: ${code}`}
      title={state === "failed" ? "couldn't copy — the code is selected, copy it manually" : label}
      className={cn(
        "ml-0.5 inline-flex h-6 w-6 shrink-0 cursor-pointer items-center justify-center rounded-sm border border-transparent bg-transparent p-0 align-middle text-text-2 hover:border-border-soft hover:text-text-0 focus-visible:border-accent-line focus-visible:outline-none",
        state === "copied" && "text-accent",
        state === "failed" && "text-warn",
      )}
    >
      <Icon size={14} strokeWidth={2} aria-hidden />
    </button>
  );
}

/** Text with its `backtick` spans rendered as CodeSpan; plain text as is. */
export function TextWithCode({ text }: { text: string }) {
  const parts = splitCodeSpans(text);
  return (
    <>
      {parts.map((p, i) => (p.kind === "code" ? <CodeSpan key={i} code={p.text} /> : <span key={i}>{p.text}</span>))}
    </>
  );
}
