// How a BOM line is worded — the ONE quantity / price wording the Builder's
// Shopping tab, the Shopping List page and its CSV all use, so they say the
// same thing about the same line ("×4 · 2 packs of 2", "×16 · 1 pack of 30 ·
// 14 spare", "420 ft · 5 packs of 100 ft · 80 ft spare"). The numbers come
// from lib/builder-data.ts bomLine() (the server's Component.units / packs /
// line_cost); this module only words them.

import type { BuilderComponent } from "@sporeprint/design";
import { approxUsd, type BomTotals } from "./builder-data";

const plural = (n: number, word: string) => `${n} ${word}${n === 1 ? "" : "s"}`;

/** The parts of a line's size that a quantity label needs — BomLineMath and
 *  the Shopping List's BomLine both have them. */
export interface PackFigures {
  units: number;
  packs: number | null;
  packSize: number | null;
  /** What the units are — Component.unit: a measure ("ft", "g") or one
   *  piece of a mixed kit ("chamber set", "M3 insert"); "" / absent =
   *  pieces of the part. */
  unit?: string;
}

/** Units of measure: written after the number as is ("420 ft"), never
 *  pluralised, and spare amounts say them ("80 ft spare"). Any other unit
 *  is a noun ("strap" → "24 straps"). */
const MEASURES = new Set(["ft", "in", "m", "cm", "mm", "g", "kg", "oz", "lb"]);

export const isMeasure = (unit: string | undefined) => MEASURES.has(unit?.trim() ?? "");

/** The unit as it reads after `n`: "ft", "strap" / "straps", "chamber set" /
 *  "chamber sets"; "" for pieces. */
export function unitWord(n: number, unit: string | undefined): string {
  const u = unit?.trim() ?? "";
  if (!u || isMeasure(u) || n === 1) return u;
  return /(?:s|x|ch|sh)$/.test(u) ? `${u}es` : `${u}s`;
}

/** "×4" for pieces; "420 ft", "24 straps", "1 chamber set" for a line that
 *  counts something else (Component.unit) — 2026-10 audit: "×420 … ~$0.26
 *  ea" for 420 ft of wire. */
export function amountText(n: number, unit: string | undefined): string {
  const word = unitWord(n, unit);
  return word ? `${n} ${word}` : `×${n}`;
}

/** Units left over from whole packs (0 when the packs are used up, or the
 *  pack size is unknown). */
export function spareUnits(m: PackFigures): number {
  if (m.packs === null || m.packSize === null) return 0;
  return Math.max(0, m.packs * m.packSize - m.units);
}

/** A pack line in pieces a narrow cell may wrap between — "5 packs", "of
 *  100 ft", "80 ft spare" — and nowhere else. `packs` is the first half
 *  whole ("5 packs of 100 ft"). Null for a part bought singly. */
export interface PackParts {
  packs: string;
  count: string;
  size: string | null;
  spare: string | null;
}

export function packParts(m: PackFigures): PackParts | null {
  if (m.packs === null) return null;
  const count = plural(m.packs, "pack");
  if (m.packSize === null) return { packs: count, count, size: null, spare: null };
  const word = unitWord(m.packSize, m.unit);
  const size = word ? `of ${m.packSize} ${word}` : `of ${m.packSize}`;
  const n = spareUnits(m);
  // a measure says what is spare ("80 ft spare"); a noun is named just above
  const spare = n > 0 ? (m.unit && isMeasure(m.unit) ? `${n} ${m.unit} spare` : `${n} spare`) : null;
  return { packs: `${count} ${size}`, count, size, spare };
}

/** The pack line under a quantity: "2 packs of 2", "1 pack of 30 · 14
 *  spare", "5 packs of 100 ft · 80 ft spare", "2 packs" (a Pi too old to
 *  send the pack size); null for a part bought singly. */
export function packLabel(m: PackFigures): string | null {
  const parts = packParts(m);
  if (!parts) return null;
  return parts.spare ? `${parts.packs} · ${parts.spare}` : parts.packs;
}

/** "×4 · 2 packs of 2" / "420 ft · 5 packs of 100 ft · 80 ft spare" / "×1
 *  (shared)": the amount, "(shared)" for a line bought once per
 *  installation, then what to buy it in — the CSV's qty cell, worded as the
 *  Qty column on screen (<BomQty>). */
export function quantityText(m: PackFigures, shared = false): string {
  const pack = packLabel(m);
  const amount = amountText(m.units, m.unit);
  const units = shared ? `${amount} (shared)` : amount;
  return pack ? `${units} · ${pack}` : units;
}

/** "~$0.26 / ft", "~$4 / chamber set", "~$0.05 ea": a pack line's price per
 *  counted unit. */
export function perUnitText(c: BuilderComponent): string {
  const u = c.unit?.trim();
  return u ? `~${c.priceApprox} / ${u}` : `~${c.priceApprox} ea`;
}

/** "$18 / pack of 3", "$26 / pack of 100 ft" (or "$18 / pack" without a
 *  size); the unit price for a part bought singly. */
export function priceText(c: BuilderComponent): string {
  if (!c.packPrice) return c.priceApprox;
  if (typeof c.packSize !== "number" || c.packSize <= 0) return `${c.packPrice} / pack`;
  const word = unitWord(c.packSize, c.unit);
  return `${c.packPrice} / pack of ${c.packSize}${word ? ` ${word}` : ""}`;
}

/** "$206 shared, bought once + ~$1,527 for 12 chambers" (or "… per
 *  chamber" for one): the one wording of a total's split, under the Builder's
 *  Overview cost and both pages' BOM totals. */
export function sharedSplitText(totals: BomTotals, chambers: number): string {
  const rest = chambers > 1 ? `for ${chambers} chambers` : "per chamber";
  return `${approxUsd(totals.shared)} shared, bought once + ${approxUsd(totals.chambered)} ${rest}`;
}

/** The caption under a BOM total: what is bought once, what the chambers
 *  take, and what buying whole packs across chambers saves. */
export function totalsCaption(totals: BomTotals, chambers: number): string[] {
  const lines = [sharedSplitText(totals, chambers)];
  if (totals.packSavings > 0) {
    lines.push(
      `whole packs shared across the ${chambers} chambers save ${approxUsd(totals.packSavings)} over buying each chamber's parts separately`,
    );
  }
  if (chambers > 1 && totals.packLinesPerChamber > 0) {
    lines.push(
      `${plural(totals.packLinesPerChamber, "pack-priced line")} from this Pi ${totals.packLinesPerChamber === 1 ? "has" : "have"} no pack size, so ${totals.packLinesPerChamber === 1 ? "it counts" : "they count"} one pack per chamber — an upper bound`,
    );
  }
  return lines;
}

/** What the "shared parts are counted once" captions list: the lines one
 *  installation buys once (lib/builder-data.ts isSharedComponent). The bulk
 *  consumables (zip ties, heat-shrink, grommets) are per-chamber pack lines
 *  since 2026-10: one pack covering 12 chambers under-bought from 17. */
export const SHARED_PARTS_NOTE = "shared parts (the Pi side and the bench breadboard) are counted once";

/** …and how the per-chamber pack lines (kits and spools the chambers use up)
 *  are bought. */
export const PER_CHAMBER_NOTE =
  "everything else scales with the chamber count, in whole packs — kits and spools the chambers use up included";
