/** A telemetry figure for display: `digits` decimals, or "—" when there is
 *  no reading. A chamber whose nodes have not reported a sensor yet carries
 *  NaN for it (the Telemetry type has no "unknown" slot), and NaN must never
 *  reach the screen as "NaN%". */
export function formatReading(value: number | null | undefined, digits = 0): string {
  return value != null && Number.isFinite(value) ? value.toFixed(digits) : "—";
}
export function relativeFromMin(min: number): string {
  if (min === 0) return "now";
  if (min < 60) return `${min}m ago`;
  const h = Math.floor(min / 60);
  if (h < 24) return `${h}h ago`;
  return `${Math.floor(h / 24)}d ago`;
}
export function relativeFromSec(sec: number): string {
  return relativeFromMin(Math.round(sec / 60));
}
export function relativeFromIso(iso: string, nowMs: number = Date.now()): string {
  return relativeFromMin(Math.max(0, Math.round((nowMs - new Date(iso).getTime()) / 60000)));
}
export function formatUptime(sec: number): string {
  const d = Math.floor(sec / 86400);
  const h = Math.floor((sec % 86400) / 3600);
  const m = Math.floor((sec % 3600) / 60);
  if (d > 0) return `${d}d ${h.toString().padStart(2, "0")}:${m.toString().padStart(2, "0")}`;
  if (h > 0) return `${h}h ${m}m`;
  return `${m}m`;
}
export function formatOnTime(sec: number): string {
  const h = Math.floor(sec / 3600);
  const m = Math.floor((sec % 3600) / 60);
  if (h > 0) return `${h}h ${m}m`;
  return `${m}m`;
}
export function rssiTone(dbm: number): "signal" | "warn" | "err" {
  if (dbm >= -60) return "signal";
  if (dbm >= -75) return "warn";
  return "err";
}
export function rssiLabel(dbm: number): string {
  if (dbm >= -60) return "strong";
  if (dbm >= -75) return "fair";
  return "weak";
}
