// The Shopping List's CSV export. Every cell is quoted, and any cell a
// spreadsheet could read as a formula is defused.

import { CSV_HEADER, type CsvRow } from "./shopping-list";

// A cell that is only a number ("-12", "+3.5", "1e3") is data, not a
// formula: it keeps its sign so the spreadsheet still sees a number.
const PLAIN_NUMBER = /^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$/;

// OWASP CSV injection: a leading = + - @, or a tab / carriage return, can
// start a formula (Excel and LibreOffice also skip leading blanks before =).
const FORMULA_START = /^(?:[\t\r\n]|\s*[=+\-@])/;

/** True when a spreadsheet could evaluate `value` as a formula. */
export function isFormulaLike(value: string): boolean {
  return FORMULA_START.test(value) && !PLAIN_NUMBER.test(value.trim());
}

/** Quote a cell; prefix a formula-like one with ' so a spreadsheet shows it
 *  as text ("-1+2", "-2+HYPERLINK(…)", "=SUM(…)", "\t=…"). Line breaks
 *  become spaces so one row stays one line. */
export function csvCell(value: string): string {
  const flat = value.replace(/[\r\n]+/g, " ");
  const safe = isFormulaLike(value) ? `'${flat}` : flat;
  return `"${safe.replace(/"/g, '""')}"`;
}

export function toCsv(rows: readonly CsvRow[]): string {
  const lines = rows.map((r) =>
    [
      r.section,
      r.category,
      r.item,
      r.qty,
      r.unitPrice,
      r.lineTotal,
      r.supplier,
      r.url,
      r.purchased ? "yes" : "no",
      r.note,
    ]
      .map(csvCell)
      .join(","),
  );
  return [CSV_HEADER.join(","), ...lines].join("\n");
}
