// GET /api/health/detail/mqtt → label / value rows for the Network panel.
//
// The payload is mostly the broker's flat $SYS strings ("load/messages/
// received/1min": "19.23"), but it also carries nested objects — e.g.
// `command_signing: { key_set, policy, cloud_configured, mode }` — which
// String() rendered as "[object Object]".

export type StatRow = readonly [label: string, value: string];

/** A stat key as a label: "_" → space, "/" → " / " (so long $SYS keys can
 *  wrap at their separators on a phone). */
export function statLabel(key: string): string {
  return key.replace(/_/g, " ").replace(/\s*\/\s*/g, " / ").trim();
}

function statValue(v: unknown): string {
  if (v === null || v === undefined || v === "") return "—";
  if (typeof v === "boolean") return v ? "yes" : "no";
  if (Array.isArray(v)) return v.length ? v.map(statValue).join(", ") : "—";
  return String(v);
}

/** Flatten nested objects into "parent · child" rows, in payload order. */
export function flattenStats(stats: Record<string, unknown>, prefix = ""): StatRow[] {
  const rows: StatRow[] = [];
  for (const [key, value] of Object.entries(stats)) {
    const label = prefix ? `${prefix} · ${statLabel(key)}` : statLabel(key);
    if (value !== null && typeof value === "object" && !Array.isArray(value)) {
      rows.push(...flattenStats(value as Record<string, unknown>, label));
    } else {
      rows.push([label, statValue(value)]);
    }
  }
  return rows;
}
