"use client";

import type { Chamber, ChamberPhase, ChamberState } from "../data/types";
import { formatReading } from "../lib/format";
import { Logo } from "./Logo";

const STATE_CLASS: Record<ChamberState, string> = {
  active: "active",
  warn: "warn",
  err: "err",
  idle: "idle",
};

function phaseLabel(
  phase: ChamberPhase,
  day: { current: number; total: number },
  phaseName?: string,
): string {
  if (phaseName && phase !== "idle") {
    if (day.current <= 0) return phaseName;
    return day.total > 0 ? `${phaseName} · day ${day.current}/${day.total}` : `${phaseName} · day ${day.current}`;
  }
  if (day.total <= 0) return "idle";
  switch (phase) {
    case "fruiting": return `fruiting · day ${day.current}`;
    case "spawn":    return `spawn · d${day.current}/${day.total}`;
    case "harvest":  return `harvest · d${day.current}`;
    default:         return "idle";
  }
}

interface Props {
  chamber: Chamber;
  selected?: boolean;
  /** Pi UI shows `R{rack}·S{shelf}` on each tile (the Pi's superpower
   *  per pi-interface.md — physical position). */
  showRackPosition?: boolean;
  /** Larger tile variant for the Pi grid. */
  large?: boolean;
  /** Random pulse offset — 0..3s. Each tile picks one so the wall
   *  pulses asynchronously per components.md §3. */
  pulseOffsetSec?: number;
  onSelect?: (id: string) => void;
}

export function FleetTile({
  chamber,
  selected,
  showRackPosition,
  large,
  pulseOffsetSec = 0,
  onSelect,
}: Props) {
  const cls = ["f-tile", STATE_CLASS[chamber.state], selected ? "selected" : "", large ? "large" : ""]
    .filter(Boolean)
    .join(" ");
  // "—" for an idle chamber, and for a grow with no humidity reading yet
  // (a new chamber before its nodes report: NaN, never "NaN%").
  const humidity = formatReading(chamber.telemetry.humidity);
  const value = chamber.phase === "idle" || humidity === "—" ? "—" : `${humidity}%`;

  const inner = (
    <>
      <span className="micro-mark">
        <Logo size={14} opts={{ baseDensity: 0.4, color: "currentColor" }} />
      </span>
      <div className="top">
        {chamber.name && chamber.name !== chamber.id ? (
          <>
            <span className="name" title={chamber.name}>{chamber.name}</span>
            <span className="cid" aria-label={`chamber ${chamber.id}`}>{chamber.id}</span>
          </>
        ) : (
          <span>{chamber.id}</span>
        )}
        {showRackPosition && (
          <span className="rack-pos">{`R${chamber.rack.rack}·S${chamber.rack.shelf}`}</span>
        )}
        <span
          className="dot"
          style={{ animationDelay: `-${pulseOffsetSec.toFixed(2)}s` }}
        />
      </div>
      <div className="species">{chamber.species.binomial}</div>
      <div className="met">
        <span className="k">{phaseLabel(chamber.phase, chamber.day, chamber.phaseName)}</span>
        <strong>{value}</strong>
      </div>
      <div className="bar">
        <i style={{ width: `${chamber.progress}%`, display: "block", height: "100%" }} />
      </div>
    </>
  );

  // Interactive only when it can select. Rendering a <button> with no onSelect
  // shipped a clickable-looking tile that did nothing (the dead-control class
  // the RangeSelector fix addressed); a read-only tile is a plain <div>.
  if (!onSelect) {
    return (
      <div className={cls} style={{ textAlign: "left" }}>
        {inner}
      </div>
    );
  }

  return (
    <button
      type="button"
      className={cls}
      onClick={() => onSelect(chamber.id)}
      aria-pressed={selected}
      style={{ appearance: "none", textAlign: "left" }}
    >
      {inner}
    </button>
  );
}
