import { Fragment, type ReactNode } from "react";

// After every "_", "/" and "." — the separators of the snake_case ids, paths
// and dotted names the Pi API hands back ("gt co2_emergency_ppm",
// "substrate_colonization", "firmware/boards/x.h").
const BREAK_AFTER = /(?<=[_/.])/;

/**
 * `text` with a line-break opportunity (`<wbr>`) after each "_", "/" and ".",
 * so a long identifier wraps at its separators inside a narrow cell or card
 * instead of running into the padding as one unbreakable token. It never
 * breaks mid-word, and `<wbr>` adds no characters: the element's text,
 * copy/paste and `getByText` still see the original string.
 */
export function SoftBreaks({ text }: { text: string }): ReactNode {
  const parts = text.split(BREAK_AFTER);
  if (parts.length < 2) return text;
  return parts.map((part, i) => (
    <Fragment key={i}>
      {i > 0 && <wbr />}
      {part}
    </Fragment>
  ));
}
