/**
 * Species categories — the one shared colour map and display order for
 * gourmet / medicinal / active / novelty, so every surface (Pi species
 * library, cloud species view, wizard) colours a category the same way.
 *
 * Each category has its own token (theme.css `--cat-*`, Tailwind
 * `bg-cat-*` / `text-cat-*`), per the design direction's category accents:
 *
 *   gourmet   → green        --cat-gourmet
 *   medicinal → amber        --cat-medicinal
 *   active    → blue-violet  --cat-active
 *   novelty   → orchid       --cat-novelty
 *
 * They used to borrow the state tokens (sage --signal, saffron --accent,
 * terracotta --err, bone --text-1), so "active" wore the colour that means
 * out of range / lost uplink, the same terracotta as an "advanced" pill and
 * "not edible" — and sage beside bone could not be told apart by a
 * protanope. The `--cat-*` values are a validated categorical palette
 * (theme.css says how), with lighter-surface steps for print.
 *
 * They are legend colours (a dot beside the category name), never a fill on
 * an interactive control: a toggled category filter keeps the standard chip
 * selection grammar (accent-soft fill + accent text + accent-line border).
 */
import type { SpeciesEntry } from "../data/fakeChambers";
import { cn } from "../lib/cn";

export type SpeciesCategory = SpeciesEntry["category"];

/** Display order for the categories we know; others sort after, A→Z. */
export const SPECIES_CATEGORY_ORDER: readonly SpeciesCategory[] = [
  "gourmet",
  "medicinal",
  "active",
  "novelty",
];

/** One token colour (a CSS `var()`) per species category. */
export const CATEGORY_COLORS: Readonly<Record<SpeciesCategory, string>> = {
  gourmet: "var(--cat-gourmet)",
  medicinal: "var(--cat-medicinal)",
  active: "var(--cat-active)",
  novelty: "var(--cat-novelty)",
};

/** Colour for a category this map does not know yet (data ran ahead of UI). */
export const CATEGORY_FALLBACK_COLOR = "var(--text-2)";

export function categoryColor(category: string): string {
  return Object.prototype.hasOwnProperty.call(CATEGORY_COLORS, category)
    ? CATEGORY_COLORS[category as SpeciesCategory]
    : CATEGORY_FALLBACK_COLOR;
}

function categoryRank(category: string): number {
  const i = (SPECIES_CATEGORY_ORDER as readonly string[]).indexOf(category);
  return i === -1 ? SPECIES_CATEGORY_ORDER.length : i;
}

/**
 * The categories the data actually has, each once: known ones in
 * SPECIES_CATEGORY_ORDER, then any unknown ones A→Z. Derive filter chips and
 * per-category counts from this — never from a hard-coded list, which is how
 * a fourth category ("novelty") went missing from a KPI that then summed to
 * less than the visible total.
 */
export function speciesCategories(entries: Iterable<{ category: string }>): string[] {
  const seen = new Set<string>();
  for (const e of entries) seen.add(e.category);
  return [...seen].sort((a, b) => categoryRank(a) - categoryRank(b) || a.localeCompare(b));
}

/**
 * Per-category counts over `entries`, one row per category in `categories`
 * (default: the categories `entries` has) — rows for a category with no
 * entries are kept, with count 0, so a breakdown keeps its shape as filters
 * narrow the list. The counts always sum to the number of entries whose
 * category is listed.
 */
export function countByCategory(
  entries: ReadonlyArray<{ category: string }>,
  categories: readonly string[] = speciesCategories(entries),
): Array<{ category: string; count: number }> {
  const counts = new Map<string, number>(categories.map((c) => [c, 0]));
  for (const e of entries) {
    const n = counts.get(e.category);
    if (n !== undefined) counts.set(e.category, n + 1);
  }
  return categories.map((category) => ({ category, count: counts.get(category) ?? 0 }));
}

/** A small round swatch in the category's colour. Decorative: the category
 *  name is always next to it, so it is hidden from assistive tech. It prints
 *  (browsers drop background colours on paper unless told otherwise), in
 *  the tokens' print steps. */
export function CategoryDot({ category, className }: { category: string; className?: string }) {
  return (
    <span
      aria-hidden="true"
      data-category-dot={category}
      className={cn("inline-block h-2 w-2 shrink-0 rounded-pill align-middle", className)}
      style={{ background: categoryColor(category), printColorAdjust: "exact", WebkitPrintColorAdjust: "exact" }}
    />
  );
}

/** A category name with its dot — for a table cell or a meta line, where the
 *  category is a fact about a species (not a filter). Mono, secondary text:
 *  the colour is the dot's, never the words'. */
export function CategoryLabel({ category, className }: { category: string; className?: string }) {
  return (
    <span
      className={cn("inline-flex items-center gap-1.5 font-mono text-[12px] text-text-2", className)}
      data-category={category}
    >
      <CategoryDot category={category} />
      {category}
    </span>
  );
}

/**
 * Per-category counts (countByCategory rows) as a small list: each
 * category's dot and count over its name, as many to a line as fit. Short
 * one-line labels, so it sits in a KpiCard's value beside plain numbers.
 */
export function CategoryBreakdown({
  rows,
  label = "species by category",
  className,
}: {
  rows: ReadonlyArray<{ category: string; count: number }>;
  /** The list's accessible name. */
  label?: string;
  className?: string;
}) {
  return (
    <ul
      className={cn("m-0 grid list-none grid-cols-[repeat(auto-fill,minmax(64px,1fr))] gap-x-3 gap-y-2.5 p-0", className)}
      aria-label={label}
      data-category-breakdown=""
    >
      {rows.map(({ category, count }) => (
        <li key={category} className="flex min-w-0 flex-col gap-1.5" data-category={category}>
          <span className="flex items-center gap-1.5">
            <CategoryDot category={category} />
            <span className="font-mono text-[22px] leading-none text-text-0">{count}</span>
          </span>
          <span className="truncate font-mono text-[12px] leading-none text-text-2">{category}</span>
        </li>
      ))}
    </ul>
  );
}
