import { useEffect, useState } from "react";
import { Button, Input } from "@sporeprint/design";
import { clampCount } from "../lib/shopping-list";

/**
 * An integer 1–99 entered as text, with − / + steppers: the field keeps what
 * is typed (an empty box mid-edit does not snap back to 1) and commits valid
 * numbers. The Builder's chamber count and the Shopping List's chamber and
 * grow counts. Hidden in print (the count is in the headings).
 */
export function CountInput({ value, onChange, label }: { value: number; onChange: (n: number) => void; label: string }) {
  const [draft, setDraft] = useState(String(value));
  useEffect(() => setDraft(String(value)), [value]);
  return (
    <span className="inline-flex items-center gap-1 print:hidden">
      <Button
        variant="ghost"
        size="sm"
        aria-label={`fewer ${label}`}
        disabled={value <= 1}
        onClick={() => onChange(clampCount(value - 1))}
      >
        −
      </Button>
      <Input
        type="number"
        inputMode="numeric"
        min={1}
        max={99}
        aria-label={label}
        className="w-16 text-center"
        value={draft}
        onChange={(e) => {
          setDraft(e.target.value);
          const n = Number(e.target.value);
          if (e.target.value !== "" && Number.isInteger(n) && n >= 1) onChange(clampCount(n));
        }}
        onBlur={() => setDraft(String(value))}
      />
      <Button
        variant="ghost"
        size="sm"
        aria-label={`more ${label}`}
        disabled={value >= 99}
        onClick={() => onChange(clampCount(value + 1))}
      >
        +
      </Button>
    </span>
  );
}
