type FullDescription = { status: "idle" | "loading" | "failed" } | { status: "loaded"; text: string };

/**
 * A model card's description, always whole words and never clipped (no line
 * clamp; the card grows). The Pi's listing cuts a long one at 240
 * characters (lib/builder-data.ts isCutDescription); then a "more" toggle
 * reads the whole paragraph from the model file's own header — this Pi's
 * download, else the file on GitHub — and "less" folds it back.
 */
function ModelDescription({ model }: { model: BuilderModelFile }) {
  const cut = isCutDescription(model.description);
  const [full, setFull] = useState<FullDescription>({ status: "idle" });
  const [open, setOpen] = useState(false);
  const alive = useRef(true);
  useEffect(() => {
    alive.current = true;
    return () => {
      alive.current = false;
    };
  }, []);
  const textId = `model-desc-${model.filename.replace(/[^A-Za-z0-9_-]/g, "-")}`;

  function toggle() {
    if (open) {
      setOpen(false);
      return;
    }
    setOpen(true);
    if (full.status === "loaded" || full.status === "loading") return;
    setFull({ status: "loading" });
    void loadModelDescription(model).then((text) => {
      if (!alive.current) return;
      setFull(text ? { status: "loaded", text } : { status: "failed" });
    });
  }

  const text =
    open && full.status === "loaded" ? full.text : cut ? wholeWordDescription(model.description) : model.description;
  return (
    <div className="flex min-w-0 flex-col gap-1">
      <p
        id={textId}
        data-testid="model-description"
        className="break-words font-body text-[14px] leading-[1.55] text-text-1"
      >
        {text}
      </p>
      {cut && (
        <span className="flex flex-wrap items-center gap-x-3 gap-y-1">
          <button
            type="button"
            onClick={toggle}
            aria-expanded={open && full.status === "loaded"}
            aria-controls={textId}
            className={cn(T_LINK_MONO, "text-[13px]")}
          >
            {open && full.status === "loading" ? "loading…" : open && full.status === "loaded" ? "less" : "more"}
          </button>
          {open && full.status === "failed" && (
            <span className="font-mono text-[12px] text-text-2">
              couldn&apos;t read the rest from this Pi or GitHub
              {model.sourceUrl && (
                <>
                  {" — "}
                  <a href={model.sourceUrl} target="_blank" rel="noopener noreferrer" className={T_LINK_MONO}>
                    open the file
                  </a>
                </>
              )}
            </span>
          )}
        </span>
      )}
    </div>
  );
}

