// Diagram scale. The tier 2/3 SVGs are 1600 px wide with 7–9 px labels:
// fitted into a 1048 px card their text renders at 4.6–5.9 px, on a phone
// at under 2 px. So the default is the SVG's own size (100%) in a box that
// pans — readable, like the full-size tab — and "fit" is the overview.
const ZOOMS = [
  { value: "fit", label: "fit" },
  { value: "1", label: "100%" },
  { value: "1.5", label: "150%" },
  { value: "2", label: "200%" },
] as const;
type Zoom = (typeof ZOOMS)[number]["value"];
const DEFAULT_ZOOM: Zoom = "1";
const ZOOM_KEY = "pi:builder:wiring-zoom";

/** The viewer's last zoom (a per-browser convenience; storage may throw). */
function loadZoom(): Zoom {
  try {
    const v = window.localStorage.getItem(ZOOM_KEY);
    const known = ZOOMS.find((z) => z.value === v);
    if (known) return known.value;
  } catch {
    // private mode / blocked storage — use the default
  }
  return DEFAULT_ZOOM;
}

function saveZoom(z: Zoom) {
  try {
    window.localStorage.setItem(ZOOM_KEY, z);
  } catch {
    // not remembered — harmless
  }
}

const zoomFactor = (z: Zoom): number | undefined => (z === "fit" ? undefined : Number(z));

/**
 * The box a wiring diagram sits in. Fitted, it just frames the image; zoomed,
 * it scrolls both ways (capped at 80% of the viewport height so both
 * scrollbars stay on screen), takes the keyboard (arrow keys pan), and a
 * mouse can drag to pan. A drag never counts as a click on the diagram's
 * link; touch keeps the browser's own swipe-to-scroll.
 */
function DiagramViewport({ zoomed, label, children }: { zoomed: boolean; label: string; children: ReactNode }) {
  const ref = useRef<HTMLDivElement>(null);
  const drag = useRef<{ id: number; x: number; y: number; left: number; top: number; moved: boolean } | null>(null);
  const suppressClick = useRef(false);

  return (
    <div
      ref={ref}
      role="region"
      aria-label={label}
      tabIndex={zoomed ? 0 : undefined}
      data-diagram-viewport={zoomed ? "zoomed" : "fit"}
      className={cn(
        "max-w-full rounded-sm border border-border-soft bg-bg-2",
        zoomed
          ? "max-h-[80vh] cursor-grab overflow-auto focus-visible:outline focus-visible:outline-1 focus-visible:outline-accent-line active:cursor-grabbing"
          : "overflow-hidden",
      )}
      onPointerDown={(e) => {
        const el = ref.current;
        if (!zoomed || !el || e.pointerType !== "mouse" || e.button !== 0) return;
        suppressClick.current = false;
        drag.current = { id: e.pointerId, x: e.clientX, y: e.clientY, left: el.scrollLeft, top: el.scrollTop, moved: false };
      }}
      onPointerMove={(e) => {
        const d = drag.current;
        const el = ref.current;
        if (!d || !el || e.pointerId !== d.id) return;
        const dx = e.clientX - d.x;
        const dy = e.clientY - d.y;
        if (!d.moved) {
          if (Math.hypot(dx, dy) < 4) return;
          d.moved = true;
          el.setPointerCapture?.(e.pointerId);
        }
        el.scrollLeft = d.left - dx;
        el.scrollTop = d.top - dy;
      }}
      onPointerUp={() => {
        if (drag.current?.moved) suppressClick.current = true;
        drag.current = null;
      }}
      onPointerCancel={() => {
        drag.current = null;
      }}
      onClickCapture={(e) => {
        if (!suppressClick.current) return;
        suppressClick.current = false;
        e.preventDefault();
        e.stopPropagation();
      }}
      // The browser's own image drag would fight the pan.
      onDragStart={(e) => {
        if (zoomed) e.preventDefault();
      }}
    >
      {children}
    </div>
  );
}

function Wiring({
  tier,
  diagrams,
  diagramsLive,
}: {
  tier: BuilderTier;
  diagrams: BuilderWiringDiagram[];
  /** The Pi answered GET /api/builder/diagrams — its SVG URLs are real. */
  diagramsLive: boolean;
}) {
  // The Pi's diagram when it listed one for this tier; otherwise (an older
  // Pi, or the API unreachable) the built-in copy embedded in this bundle —
  // no request to a Pi URL that will not answer.
  const piDiagram = diagramsLive ? diagrams.find((d) => d.tierId === tier.id) : undefined;
  const builtIn = BUILDER_WIRING_DIAGRAMS.find((d) => d.tierId === tier.id);
  // The URL whose image failed, so a tier switch (a new URL) tries again.
  const [failedUrl, setFailedUrl] = useState<string | null>(null);
  const [zoom, setZoom] = useState<Zoom>(() => loadZoom());
  // The Pi file's own width once it loads, when it is not the built-in file.
  const [loadedWidth, setLoadedWidth] = useState<{ url: string; width: number } | null>(null);
  const showPi = piDiagram !== undefined && failedUrl !== piDiagram.url;
  const fullSizeUrl = showPi ? piDiagram.url : builtIn?.sourceUrl;
  const caption = diagramCaption(tier.wiringDiagram);
  // The embedded SVG's size (for the zoom and the space held before the Pi
  // file loads) — from the lazy wiring chunk, null until it arrives.
  const svgs = useWiringSvgs();
  const svg = svgs?.[tier.id] ?? null;
  const factor = zoomFactor(zoom);
  const zoomed = factor !== undefined;
  const sameFile = piDiagram !== undefined && svg !== null && svg.filename === piDiagram.filename;
  // The Pi file's width: the built-in copy's when it is the same file, else
  // its own once loaded; unknown (no minimum width yet) until then.
  const piWidth: number | null = sameFile
    ? svg.width
    : loadedWidth && piDiagram && loadedWidth.url === piDiagram.url
      ? loadedWidth.width
      : (svg?.width ?? null);
  const piMinWidth = zoomed && piWidth !== null ? `${Math.round(piWidth * factor)}px` : undefined;

  function chooseZoom(z: Zoom) {
    setZoom(z);
    saveZoom(z);
  }

  return (
    <section className="flex min-w-0 flex-col gap-[18px]">
      <figure className={cn(PANEL, "m-0 flex flex-col gap-4 sm:gap-[18px]")}>
        <div className="flex flex-wrap items-center justify-between gap-x-4 gap-y-2">
          <div className={cn(SECTION_TITLE, "mb-0 min-w-0")}>Wiring diagram · {tier.name}</div>
          <div className="flex flex-wrap items-center gap-x-4 gap-y-2">
            <div className="flex flex-wrap items-center gap-1.5" role="group" aria-label="diagram zoom">
              {ZOOMS.map((z) => (
                <Chip key={z.value} active={zoom === z.value} onClick={() => chooseZoom(z.value)}>
                  {z.label}
                </Chip>
              ))}
            </div>
            {fullSizeUrl && <OpenFullSize href={fullSizeUrl} label={showPi ? "open full size" : "open full size on GitHub"} />}
          </div>
        </div>
        {showPi ? (
          <>
            <DiagramViewport zoomed={zoomed} label={`${tier.name} wiring diagram${zoomed ? " — scroll or drag to pan" : ""}`}>
              <a
                href={piDiagram.url}
                target="_blank"
                rel="noopener noreferrer"
                title="open full size in a new tab"
                className="block"
                style={piMinWidth ? { minWidth: piMinWidth } : undefined}
              >
                <img
                  key={piDiagram.url}
                  src={piDiagram.url}
                  alt={`Wiring diagram for the ${tier.name} tier${caption ? `: ${caption}` : ""}`}
                  decoding="async"
                  className={cn("block h-auto w-full", zoomed ? "max-w-none" : "max-w-full")}
                  style={{
                    // Space for the diagram before it loads: the built-in
                    // copy's ratio, `auto` so the Pi file's own ratio wins
                    // once known.
                    ...(sameFile ? { aspectRatio: `auto ${svg.width} / ${svg.height}` } : {}),
                    ...(piMinWidth ? { minWidth: piMinWidth } : {}),
                  }}
                  onLoad={(e) => {
                    const w = e.currentTarget.naturalWidth;
                    if (w > 0) setLoadedWidth({ url: piDiagram.url, width: w });
                  }}
                  onError={() => setFailedUrl(piDiagram.url)}
                />
              </a>
            </DiagramViewport>
            <p className={cn("font-mono text-[12px] text-text-2", WRAP_ANY)}>
              {piDiagram.filename} · served by this Pi ·{" "}
              {zoomed ? "scroll, drag or use the arrow keys to pan · " : ""}tap the diagram or “open full size” to
              open it in a new tab
            </p>
          </>
        ) : (
          <>
            {piDiagram && (
              <p className={cn("font-mono text-[12px] text-warn", WRAP_ANY)}>
                couldn&apos;t load {piDiagram.filename} from this Pi — showing the built-in copy
              </p>
            )}
            <DiagramViewport zoomed={zoomed} label={`${tier.name} wiring diagram${zoomed ? " — scroll or drag to pan" : ""}`}>
              <WiringDiagram tierId={tier.id} href={builtIn?.sourceUrl} zoom={factor} className="block" />
            </DiagramViewport>
            <p className={cn("font-mono text-[12px] text-text-2", WRAP_ANY)}>
              built-in copy of {builtIn?.filename ?? "this tier's diagram"} — generated from the public repo when this UI was built (may differ
              from this Pi&apos;s release){zoomed ? " · scroll, drag or use the arrow keys to pan" : ""}
            </p>
          </>
        )}
        {caption && (
          <figcaption className={cn("font-body text-[14px] leading-[1.55] text-text-1", WRAP_ANY)}>
            {caption}
          </figcaption>
        )}
      </figure>

      <div className="grid min-w-0 auto-rows-fr grid-cols-[repeat(auto-fit,minmax(min(280px,100%),1fr))] gap-3">
        {diagrams.map((d) => {
          // Without a live listing the Pi URL would 404 — open GitHub's copy.
          const href = diagramsLive ? d.url : d.sourceUrl;
          const selected = d.tierId === tier.id;
          return (
            <article
              key={d.tierId}
              className={cn(
                CARD,
                "flex min-h-[180px] flex-col gap-3",
                selected ? "border-accent-line" : "border-border-soft",
              )}
            >
              <span className="flex flex-wrap items-center justify-between gap-2">
                <span className={cn(EYEBROW, WRAP_ANY)}>{d.label}</span>
                {selected && <StatusPill tone="accent">this tier</StatusPill>}
              </span>
              {/* A thumbnail of the diagram (the built-in copy) over an
                  accent link label — it read as a disabled placeholder in
                  grey text3 on bg-2 (2.16:1). */}
              <a
                href={href}
                target="_blank"
                rel="noopener noreferrer"
                className="group flex flex-1 flex-col items-center justify-center gap-2.5 rounded-sm border border-border-soft bg-bg-2 p-3 text-center font-mono text-[13px] font-medium uppercase tracking-[0.16em] text-accent no-underline transition-colors duration-[var(--dur-fast)] ease-brand hover:border-accent-line hover:text-text-0"
              >
                {/* The built-in copy, loaded with the main diagram's lazy
                    chunk (it holds its place until then). flex-1 + centred:
                    the three diagrams differ in aspect ratio, so the labels
                    below still line up across cards. */}
                <span className="flex w-full flex-1 items-center">
                  <span className="block w-full overflow-hidden rounded-sm opacity-85 transition-opacity group-hover:opacity-100">
                    <WiringDiagram tierId={d.tierId} alt="" />
                  </span>
                </span>
                <span>full-size svg →</span>
              </a>
              <span className="flex flex-wrap items-center gap-x-3 gap-y-1 font-mono text-[12px] text-text-2">
                <span className={WRAP_ANY}>
                  {d.filename} · {d.sizeKb.toFixed(1)} KB
                </span>
                <a href={d.sourceUrl} target="_blank" rel="noopener noreferrer" className={T_LINK_MONO}>
                  GitHub
                </a>
              </span>
            </article>
          );
        })}
      </div>

      <div className="flex min-w-0 flex-col gap-2.5" role="region" aria-label="connection reference">
        <span className={EYEBROW}>Connection reference</span>
        {(() => {
          // Same DataTable `id` workaround as the BOM/Substitutions tables —
          // `BuilderWiring` rows have no natural unique field, so index the
          // (per-tier) array position instead.
          const rows = tier.wiring.map((w, i) => ({ ...w, id: i }));
          // Every caveat in the Note column must stay readable — it used to
          // run past the right edge of a sideways scroller from ~1024 to
          // ~1340 px, cut mid-word. Now the table never scrolls: the four
          // device/pin columns take fixed shares and Note the rest (≥ 37%,
          // ~330 px at the 900 px floor), and under 900 px of table each row
          // stacks as a card (stackWhenNarrow), every field full width.
          // Cells wrap between words (`break-words` only breaks a word
          // longer than its column — none is: the longest is 14 letters).
          return (
            <DataTable<(typeof rows)[number]>
              stackWhenNarrow
              rowKey={(w) => w.id}
              columns={[
                {
                  key: "from",
                  header: "From",
                  width: "14%",
                  render: (w) => <span className="block break-words font-mono text-text-0">{w.fromDevice}</span>,
                },
                {
                  key: "fromPin",
                  header: "From pin",
                  width: "14%",
                  render: (w) => <span className="block break-words font-mono text-accent">{w.fromPin}</span>,
                },
                {
                  key: "to",
                  header: "To",
                  width: "17%",
                  render: (w) => <span className="block break-words">{w.toDevice}</span>,
                },
                {
                  key: "toPin",
                  header: "To pin",
                  width: "18%",
                  render: (w) => <span className="block break-words font-mono text-text-0">{w.toPin}</span>,
                },
                {
                  key: "note",
                  header: "Note",
                  render: (w) => (
                    <span className="block break-words" data-testid="wiring-note">
                      <TextWithCode text={w.note} />
                    </span>
                  ),
                },
              ]}
              rows={rows}
            />
          );
        })()}
      </div>
    </section>
  );
}

