// Builder → Setup tab progress, saved per browser in localStorage.
//
// KEYING (why it looks like this): the Pi serves each tier's setup steps as
// plain strings — no ids — and the BOM audit rewrites them often (new steps
// inserted, details reworded, backtick code spans added). The old keys were
// `${tierId}:${index}`, so inserting one step silently moved every later
// tick onto the wrong step. Keys are now
//
//     `${tierId}/${stepId}`      e.g.  "recommended/flash-node"
//
// where stepId is derived from the step's LEAD PHRASE — the words before the
// first ": ", " — ", " (", ". ", "; " or ", " — lowercased, without
// backticks/apostrophes/punctuation and filler words, first 5 words. So
//   "Flash each node: `cd firmware && pio run …` — ONE unified image …"
//   "Flash the node: cd firmware && pio run …"
// both key as "flash-node": rewording, reformatting or extending a step's
// body keeps its tick, and inserting/reordering steps no longer shifts
// anyone's progress. Renaming a step's lead phrase is a new step (unticked)
// — that is a real change in what the step asks for. Duplicate ids within a
// tier get "~2", "~3" in order.
//
// Progress for a step that is no longer listed stays in storage (the list
// may be the built-in copy now and the Pi's live list a moment later) but is
// never counted: done/total/percent only look at the tier's current steps.
//
// MIGRATION: legacy `${tierId}:${index}` keys are converted on load with
// LEGACY_STEP_MAP — a hand-made map from the step lists the previous release
// shipped (the design package's hand-written HARDWARE_TIERS, 5 / 9 / 7
// steps) to today's step ids, by meaning. Index-for-index would be wrong
// (old recommended:1 "Wire the climate node" is today's "Install
// SporePrint"); a legacy step with no counterpart today is dropped. Legacy
// keys are removed once converted.

import type { BuilderTier } from "@sporeprint/design";

/** localStorage key (unchanged from the index-keyed version, so existing
 *  progress is found and migrated in place). */
export const SETUP_PROGRESS_KEY = "pi:builder:setupProgress";

export type SetupTierId = BuilderTier["id"];

/** Ticked steps: key → true. Unticked steps are absent. */
export type SetupProgress = Record<string, true>;

const MAX_ID_WORDS = 5;

const FILLER = new Set([
  "a",
  "an",
  "and",
  "as",
  "at",
  "by",
  "each",
  "for",
  "from",
  "in",
  "into",
  "it",
  "its",
  "of",
  "on",
  "onto",
  "or",
  "per",
  "that",
  "the",
  "then",
  "this",
  "to",
  "with",
  "your",
]);

// ": " (a colon followed by space — not the one in "http://" or ":3001"),
// an em/en dash between spaces, an opening paren, a sentence end, ";" or ",".
const LEAD_END = /:\s|\s[—–]\s|\s\(|\.\s|;\s|,\s/;

/** The stable id of one step (see the header). `index` only names a step
 *  whose lead phrase has no words at all. */
export function setupStepId(step: string, index: number): string {
  const lead = step.replace(/`/g, "").split(LEAD_END, 1)[0] ?? "";
  const words = lead
    .toLowerCase()
    .replace(/['’]/g, "")
    .split(/[^a-z0-9]+/)
    .filter((w) => w && !FILLER.has(w));
  return words.slice(0, MAX_ID_WORDS).join("-") || `step-${index + 1}`;
}

/** Ids for a tier's step list, in order; repeats get "~2", "~3", … */
export function setupStepIds(steps: ReadonlyArray<string>): string[] {
  const seen = new Map<string, number>();
  return steps.map((step, i) => {
    const base = setupStepId(step, i);
    const n = (seen.get(base) ?? 0) + 1;
    seen.set(base, n);
    return n === 1 ? base : `${base}~${n}`;
  });
}

export function setupStepKey(tierId: SetupTierId, stepId: string): string {
  return `${tierId}/${stepId}`;
}

/** Previous release's step lists (index → today's step ids). See header. */
export const LEGACY_STEP_MAP: Record<SetupTierId, ReadonlyArray<ReadonlyArray<string>>> = {
  bare_bones: [
    ["set-up-raspberry-pi"], // Flash Raspberry Pi OS (64-bit) onto microSD … hostname 'sporeprint'
    ["install-sporeprint-pi-one-command"], // Boot the Pi and run the SporePrint installer.
    ["wire-climate-node-stemma-qt"], // Wire the SHT31-D to the ESP32 per the diagram.
    ["flash-node"], // Flash the node firmware: pio run -t upload -e node_esp32
    ["esp32-opens-sporeprint-setup-wifi"], // Power the ESP32, join its 'SporePrint-Setup' WiFi AP …
  ],
  recommended: [
    ["set-up-raspberry-pi", "install-sporeprint-pi-one-command"], // Flash Raspberry Pi OS (64-bit). Run installer.
    ["wire-climate-node-stemma-qt"], // Wire the climate node (SHT31 + SCD41 + BH1750 …)
    ["build-relay-switch-board-relay"], // Wire the relay node (4× IRLZ44N MOSFETs …)
    ["build-lighting-switch-board-same"], // Wire the lighting node (white strip via MOSFET …)
    ["flash-node"], // Flash each node: cd firmware && pio run -t upload -e node_esp32 …
    ["flash-esp32-cam"], // ESP32-CAM flashes via the USB-UART programmer …
    ["esp32-opens-sporeprint-setup-wifi"], // Power up. Each node joins WiFi via its 'SporePrint-Setup' AP …
    ["open-http-pi-ip-3001"], // Verify in /chambers — all 4 nodes should be online within 60s.
    [], // Note: each node has GPIO 0 as a factory-reset pin … (no step today)
  ],
  all_the_things: [
    [], // Wire and flash Recommended tier first … (no single step today)
    ["wire-climate-node-2-identically"], // Mount second climate node … climate-02.
    ["camera-placement"], // Mount second ESP32-CAM top-down … cam-02.
    ["wire-hx711-relay-nodes-spare"], // Wire HX711 + 5kg load cell under the fruiting block …
    ["connect-peristaltic-pump-relay-nodes"], // Wire peristaltic pump to relay node aux MOSFET (GPIO 14).
    [], // Calibrate load cell with a known mass … (no step today)
    ["mount-door-contact-door-frame"], // Add reed switch to chamber door on GPIO 35 …
  ],
};

const LEGACY_KEY_RE = /^(bare_bones|recommended|all_the_things):(\d+)$/;

/** Normalise whatever is stored into SetupProgress: keep current-format
 *  ticks, convert legacy index keys via LEGACY_STEP_MAP, drop the rest.
 *  `migrated` is true when the stored value needs rewriting. */
export function migrateSetupProgress(raw: unknown): { progress: SetupProgress; migrated: boolean } {
  const progress: SetupProgress = {};
  if (typeof raw !== "object" || raw === null || Array.isArray(raw)) {
    return { progress, migrated: raw !== null && raw !== undefined };
  }
  let migrated = false;
  for (const [key, value] of Object.entries(raw as Record<string, unknown>)) {
    const legacy = LEGACY_KEY_RE.exec(key);
    if (legacy) {
      migrated = true;
      if (value !== true) continue;
      const tierId = legacy[1] as SetupTierId;
      for (const stepId of LEGACY_STEP_MAP[tierId][Number(legacy[2])] ?? []) {
        progress[setupStepKey(tierId, stepId)] = true;
      }
      continue;
    }
    if (value === true && key.includes("/")) progress[key] = true;
    else migrated = true; // false / junk entries are not kept
  }
  return { progress, migrated };
}

function defaultStorage(): Storage | null {
  try {
    return typeof window === "undefined" ? null : window.localStorage;
  } catch {
    return null;
  }
}

/** Read (and, if it held legacy keys, rewrite) the saved progress. Never
 *  throws: unavailable storage or unparsable JSON is an empty progress. */
export function loadSetupProgress(storage: Storage | null = defaultStorage()): SetupProgress {
  if (!storage) return {};
  let raw: unknown;
  try {
    const text = storage.getItem(SETUP_PROGRESS_KEY);
    if (!text) return {};
    raw = JSON.parse(text);
  } catch {
    return {};
  }
  const { progress, migrated } = migrateSetupProgress(raw);
  if (migrated) saveSetupProgress(progress, storage);
  return progress;
}

/** false when storage is unavailable or refused the write. */
export function saveSetupProgress(progress: SetupProgress, storage: Storage | null = defaultStorage()): boolean {
  if (!storage) return false;
  try {
    storage.setItem(SETUP_PROGRESS_KEY, JSON.stringify(progress));
    return true;
  } catch {
    return false;
  }
}

export function toggleSetupStep(progress: SetupProgress, key: string): SetupProgress {
  const next = { ...progress };
  if (next[key]) delete next[key];
  else next[key] = true;
  return next;
}

export interface TierSetupProgress {
  /** One storage key per current step, in order. */
  keys: string[];
  done: number;
  total: number;
  /** 0–100; 100 only when every step is ticked (never rounded up to it). */
  pct: number;
}

/** Progress of ONE tier over its CURRENT step list. */
export function tierSetupProgress(
  tierId: SetupTierId,
  steps: ReadonlyArray<string>,
  progress: SetupProgress,
): TierSetupProgress {
  const keys = setupStepIds(steps).map((id) => setupStepKey(tierId, id));
  const total = keys.length;
  const done = keys.filter((k) => progress[k]).length;
  const pct = total === 0 ? 0 : done === total ? 100 : Math.floor((done / total) * 100);
  return { keys, done, total, pct };
}
