import type { ReactNode } from "react";

type KpiTone = "default" | "accent" | "signal" | "warn" | "err";

export function KpiCard({
  label,
  value,
  unit,
  delta,
  trend,
  tone = "default",
  spark,
  children,
  valueClassName,
  className,
}: {
  label: string;
  /** Usually a string or number; a node (e.g. a small per-category
   *  breakdown) is allowed — size it with `valueClassName`. */
  value: ReactNode;
  unit?: string;
  delta?: string;
  trend?: "up" | "down" | "flat";
  tone?: KpiTone;
  spark?: ReactNode;
  children?: ReactNode;
  /** Extra classes for the value (e.g. a smaller size for a long value). */
  valueClassName?: string;
  /** Extra classes for the card itself (e.g. a grid column span). */
  className?: string;
}) {
  const cls = [`kpi-card`, tone === "default" ? "" : tone, className ?? ""].filter(Boolean).join(" ");
  const deltaCls = `kpi-delta ${trend === "up" ? "up" : trend === "down" ? "down" : ""}`.trim();
  return (
    <div className={cls}>
      <span className="kpi-label">{label}</span>
      <div className={valueClassName ? `kpi-value ${valueClassName}` : "kpi-value"}>
        {value}
        {unit && <span className="u">{unit}</span>}
      </div>
      {delta && <span className={deltaCls}>{delta}</span>}
      {spark && <div style={{ marginTop: 6 }}>{spark}</div>}
      {children}
    </div>
  );
}
